BEGIN;

UPDATE public.place_reviews SET content = '
10월의 시드니는 남반구 봄이라, 바람과 햇볕이 머물기 좋은 쪽으로 기우는 시기예요. **오페라하우스** 앞 인파보다 그 옆으로 이어지는 식물원 쪽이 훨씬 차분한 편이에요.

**왕립 식물원**([공식 사이트](https://www.botanicgardens.org.au/royal-botanic-garden-sydney/plan-your-visit))은 매일 07:00에 열고 해 질 무렵 닫는데(폐원 시각은 계절마다 달라요), 평지 동선이 길게 이어져서 서두를 이유가 없어요. 큰 나무 그늘 아래 벤치나 잔디에 앉으면 하버 물빛이 멀리 보이고, 도시 소리가 한 겹 물러나요. 하버 산책로는 한 구간만 골라 걷고, 중간 벤치에서 오래 쉬어 가도 괜찮아요.

오후에는 글리브 포인트 로드 49번지의 동네 책방 **글리브북스**(Gleebooks, [공식 사이트](https://gleebooks.com.au/))로 옮겨 보는 것도 좋아요. 매일 09:00~18:00 열고, 공휴일엔 10:00~16:00이에요(성탄절 휴무). 책장 사이를 천천히 돌다가 근처 카페 창가에 앉으면, 관광 동선과는 다른 리듬으로 하루가 흘러가거든요.

아쉬운 점은 봄이라도 날씨가 하루 안에 자주 바뀔 수 있다는 거예요. 햇볕이 강한 날은 그늘 없는 해안 구간이 생각보다 지치기 쉬워요.

공원 벤치와 책방 사이에서 봄 오후를 보내고 싶은 분께 추천해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"10월의 시드니는 남반구 봄이라, 바람과 햇볕이 머물기 좋은 쪽으로 기우는 시기예요. **오페라하우스** 앞 인파보다 그 옆으로 이어지는 식물원 쪽이 훨씬 차분한 편이에요.\n\n**왕립 식물원**([공식 사이트](https://www.botanicgardens.org.au/royal-botanic-garden-sydney/plan-your-visit))은 매일 07:00에 열고 해 질 무렵 닫는데(폐원 시각은 계절마다 달라요), 평지 동선이 길게 이어져서 서두를 이유가 없어요. 큰 나무 그늘 아래 벤치나 잔디에 앉으면 하버 물빛이 멀리 보이고, 도시 소리가 한 겹 물러나요. 하버 산책로는 한 구간만 골라 걷고, 중간 벤치에서 오래 쉬어 가도 괜찮아요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"오후에는 글리브 포인트 로드 49번지의 동네 책방 **글리브북스**(Gleebooks, [공식 사이트](https://gleebooks.com.au/))로 옮겨 보는 것도 좋아요. 매일 09:00~18:00 열고, 공휴일엔 10:00~16:00이에요(성탄절 휴무). 책장 사이를 천천히 돌다가 근처 카페 창가에 앉으면, 관광 동선과는 다른 리듬으로 하루가 흘러가거든요.\n\n","type":"text"},{"type":"image","image_index":1},{"text":"아쉬운 점은 봄이라도 날씨가 하루 안에 자주 바뀔 수 있다는 거예요. 햇볕이 강한 날은 그늘 없는 해안 구간이 생각보다 지치기 쉬워요.\n\n공원 벤치와 책방 사이에서 봄 오후를 보내고 싶은 분께 추천해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Royal+Botanic+Garden+Sydney","kind":"map","label":"왕립 식물원 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Gleebooks+49+Glebe+Point+Rd+Glebe","kind":"map","label":"글리브북스 지도"}]}]'::jsonb WHERE id = '04c02248-d84b-4d39-bdaa-4a9f008ec48c'::uuid;

UPDATE public.place_reviews SET content = '
해 진 뒤에는 **세체니 다리** 페스트 쪽 **도나우 강변**을 첫 촬영 자리로 잡아요. [세체니 다리와 마르게트 다리 사이 강변은 계절·시간대와 관계없이 전망이 열려 있어요](https://www.budapestinfo.hu/en/shoes-on-the-danube-bank). 수면에 비친 다리 불빛과 부다 쪽 실루엣을 한 화면에 두고, 강물을 아래쪽에 넉넉히 남기는 구도를 짜요.

이어서 다리 위로 올라가요. [보행으로 건널 수 있고, 장식 조명은 평소 따뜻한 흰색으로 켜져요](https://www.budapestinfo.hu/en/chain-bridge). 다리 중앙에서 양안 조명을 좌우로 나누는 컷이 잘 나와요. 블루아워에는 하늘과 조명의 대비가 살아나요.

귀가는 **세체니 이슈트반 테르**에서 **2번 트램**으로 묶어요. [공식 시간표](https://futar.bkk.hu/)의 Közvágóhíd H–Jászai Mari tér 강변 구간이라 도나우를 곁에 두고 이동해요. 촬영을 이 트램에 맞춰 끝내는 동선으로 추천해요.

정보 확인일 2026-11-09 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"해 진 뒤에는 **세체니 다리** 페스트 쪽 **도나우 강변**을 첫 촬영 자리로 잡아요. [세체니 다리와 마르게트 다리 사이 강변은 계절·시간대와 관계없이 전망이 열려 있어요](https://www.budapestinfo.hu/en/shoes-on-the-danube-bank). 수면에 비친 다리 불빛과 부다 쪽 실루엣을 한 화면에 두고, 강물을 아래쪽에 넉넉히 남기는 구도를 짜요.\n\n이어서 다리 위로 올라가요. [보행으로 건널 수 있고, 장식 조명은 평소 따뜻한 흰색으로 켜져요](https://www.budapestinfo.hu/en/chain-bridge). 다리 중앙에서 양안 조명을 좌우로 나누는 컷이 잘 나와요. 블루아워에는 하늘과 조명의 대비가 살아나요.\n\n귀가는 **세체니 이슈트반 테르**에서 **2번 트램**으로 묶어요. [공식 시간표](https://futar.bkk.hu/)의 Közvágóhíd H–Jászai Mari tér 강변 구간이라 도나우를 곁에 두고 이동해요. 촬영을 이 트램에 맞춰 끝내는 동선으로 추천해요.\n\n정보 확인일 2026-11-09 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Sz%C3%A9chenyi%20Chain%20Bridge%20Budapest","kind":"map","label":"세체니 다리 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Danube%20Promenade%20Chain%20Bridge%20Budapest","kind":"map","label":"도나우 강변 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=tram%202%20Sz%C3%A9chenyi%20Istv%C3%A1n%20t%C3%A9r%20Budapest","kind":"map","label":"2번 트램 지도"}]}]'::jsonb WHERE id = '0d85bbf2-9d7d-4900-ab6e-3784191a392c'::uuid;

UPDATE public.place_reviews SET content = '
매일 밤 20:00에 **빅토리아 하버** 양안의 빌딩 40여 채가 조명과 레이저, 음악에 맞춰 한꺼번에 움직여요. 무료 멀티미디어 쇼 **A Symphony of Lights**([공식 안내](https://www.tourism.gov.hk/symphony/english/details/details.html))예요. 정면 자리는 침사추이 **홍콩문화센터** 앞 해안 산책로와 **스타의 거리**(Avenue of Stars)이고, 쇼 음악도 여기서 같이 흘러나와요.

구도는 쇼가 시작되기 전에 끝내 두세요. 물결이 잔잔한 밤엔 **IFC** 두 동과 **HSBC 본사 빌딩**, **컨벤션 센터**의 불빛이 하버에 세로로 길게 떨어지고, 장노출로 누르면 레이저 궤적까지 같이 남아요. 섬 쪽에서 보고 싶다면 완차이 **골든 보히니아 광장** 산책로에 서 보세요. 이번엔 구룡 스카이라인이 배경이 돼요.

하버 전체를 위에서 내려다보는 자리는 해발 428m, 홍콩에서 가장 높은 전망대인 **피크**의 **Sky Terrace 428**([공식 사이트](https://www.thepeak.com.hk/en/the-peak-experience/the-sky-terrace-428))이에요. 매일 08:30~22:00 열려 있고, 입장권은 피크 트램과 묶은 콤보로 공식 웹스토어의 [티켓 예매](https://webstore.thepeak.com.hk/?lang=en_us) 페이지에서 온라인으로 팔아요. 산마루에 낮은 구름이 걸리는 날엔 도시 불빛이 안개 속에서 부드럽게 번져요.

변수는 날씨예요. 태풍 신호 3호 이상이나 적색·흑색 폭우 경보가 15:00 이후에 내려지면 그날 쇼는 취소되고, 쇼 전에 해제돼도 다시 열리지 않아요. 해 지는 시각은 철마다 움직여서, 블루아워 컷은 쇼보다 먼저 산 위나 해안에서 따로 챙겨 두세요.

쇼가 시작되는 순간 하버 앞에 서 있고 싶은 여행이라면 이 동선을 추천해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"매일 밤 20:00에 **빅토리아 하버** 양안의 빌딩 40여 채가 조명과 레이저, 음악에 맞춰 한꺼번에 움직여요. 무료 멀티미디어 쇼 **A Symphony of Lights**([공식 안내](https://www.tourism.gov.hk/symphony/english/details/details.html))예요. 정면 자리는 침사추이 **홍콩문화센터** 앞 해안 산책로와 **스타의 거리**(Avenue of Stars)이고, 쇼 음악도 여기서 같이 흘러나와요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"구도는 쇼가 시작되기 전에 끝내 두세요. 물결이 잔잔한 밤엔 **IFC** 두 동과 **HSBC 본사 빌딩**, **컨벤션 센터**의 불빛이 하버에 세로로 길게 떨어지고, 장노출로 누르면 레이저 궤적까지 같이 남아요. 섬 쪽에서 보고 싶다면 완차이 **골든 보히니아 광장** 산책로에 서 보세요. 이번엔 구룡 스카이라인이 배경이 돼요.\n\n","type":"text"},{"type":"image","image_index":1},{"text":"하버 전체를 위에서 내려다보는 자리는 해발 428m, 홍콩에서 가장 높은 전망대인 **피크**의 **Sky Terrace 428**([공식 사이트](https://www.thepeak.com.hk/en/the-peak-experience/the-sky-terrace-428))이에요. 매일 08:30~22:00 열려 있고, 입장권은 피크 트램과 묶은 콤보로 공식 웹스토어의 [티켓 예매](https://webstore.thepeak.com.hk/?lang=en_us) 페이지에서 온라인으로 팔아요. 산마루에 낮은 구름이 걸리는 날엔 도시 불빛이 안개 속에서 부드럽게 번져요.\n\n","type":"text"},{"type":"image","image_index":2},{"text":"변수는 날씨예요. 태풍 신호 3호 이상이나 적색·흑색 폭우 경보가 15:00 이후에 내려지면 그날 쇼는 취소되고, 쇼 전에 해제돼도 다시 열리지 않아요. 해 지는 시각은 철마다 움직여서, 블루아워 컷은 쇼보다 먼저 산 위나 해안에서 따로 챙겨 두세요.\n\n쇼가 시작되는 순간 하버 앞에 서 있고 싶은 여행이라면 이 동선을 추천해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Tsim+Sha+Tsui+Promenade+Hong+Kong","kind":"map","label":"A Symphony of Lights 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Sky+Terrace+428+The+Peak+Hong+Kong","kind":"map","label":"Sky Terrace 428 지도"}]}]'::jsonb WHERE id = '0f176b78-cf13-43cf-80d0-f572e7e215b8'::uuid;

UPDATE public.place_reviews SET content = '
울란바토르 하루의 축은 수도 동부의 **나란툴 시장**(Narantuul Market, [공식 페이지](https://tourism.ub.gov.mn/wp-content/uploads/Ulaanbaatar-korea-2025-2.pdf))이에요. 몽골에서 처음 생긴 최대 재래시장이자 야외 시장으로, 생필품을 중심으로 품목이 넓어요.

도심은 **수흐바타르 광장**(Sukhbaatar Square, [공식 페이지](https://www.visit-ulaanbaatar.com/EN/get-to-know))에서 시작해요. 수도 한가운데이고, 역사적인 건물과 동상이 광장을 둘러싸고 있어요. 아침에는 간단테그치늘렌 사원(Gandan Tegchilen Monastery)으로 이어 보세요. 승려들이 아침마다 법회와 기도를 해요.

일정은 아침 사원, 도심 광장, 이어서 동부의 나란툴 시장 순서로 짜 보세요.

나란툴 시장과 도심 리듬에 하루를 맡기고 싶을 때 추천해요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"울란바토르 하루의 축은 수도 동부의 **나란툴 시장**(Narantuul Market, [공식 페이지](https://tourism.ub.gov.mn/wp-content/uploads/Ulaanbaatar-korea-2025-2.pdf))이에요. 몽골에서 처음 생긴 최대 재래시장이자 야외 시장으로, 생필품을 중심으로 품목이 넓어요.\n\n도심은 **수흐바타르 광장**(Sukhbaatar Square, [공식 페이지](https://www.visit-ulaanbaatar.com/EN/get-to-know))에서 시작해요. 수도 한가운데이고, 역사적인 건물과 동상이 광장을 둘러싸고 있어요. 아침에는 간단테그치늘렌 사원(Gandan Tegchilen Monastery)으로 이어 보세요. 승려들이 아침마다 법회와 기도를 해요.\n\n일정은 아침 사원, 도심 광장, 이어서 동부의 나란툴 시장 순서로 짜 보세요.\n\n나란툴 시장과 도심 리듬에 하루를 맡기고 싶을 때 추천해요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Narantuul+Market+Ulaanbaatar","kind":"map","label":"나란툴 시장 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Sukhbaatar+Square+Ulaanbaatar","kind":"map","label":"수흐바타르 광장 지도"}]}]'::jsonb WHERE id = '18c5a722-12aa-4324-b252-01ef8b22a0c7'::uuid;

UPDATE public.place_reviews SET content = '
**도톤보리**라는 이름은 1612년 사재를 털어 이 강을 판 야스이 도톤에게서 왔어요. 극장과 찻집이 늘며 놀거리 거리로 자랐고, 지금은 거대한 입체 간판 아래 가게들이 한 해 내내 붐벼요([관광청 안내](https://osaka-info.jp/en/spot/dotonbori/)). 난카이·긴테쓰와 오사카 메트로 미도스지선·센니치마에선·요쓰바시선 난바역 바로 앞이에요.

밤 동선의 축은 강가예요. **톤보리 리버워크**는 에비스바시~닛폰바시와 미나토마치 구간을 합쳐 600m이고, 강 쪽으로 문을 낸 가게가 30곳 넘어요. 한 해 행사가 20번쯤 열려요([리버워크](https://osaka-info.jp/en/spot/tombori-riverwalk/)). 길목엔 글리코 간판과 돈키호테 관람차가 있어요.

겨울이면 산책로에 일루미네이션 **빛과 물의 원더랜드**가 켜져 거리 네온과 함께 강물에 비쳐요. 올해 점등 계획은 16:00부터 0:30까지예요([점등 안내](https://hikarimasse.osaka-chushin.fun/)).

물 위에서 보려면 다자에몬바시 선착장의 **톤보리 리버 크루즈**를 타요. 약 20분 동안 강을 돌며 글리코 간판을 물 위에서 보고, 요금은 2,000엔이에요([크루즈 안내](https://osaka-info.jp/special/dc/event/detail376/)).

즐기려면 일루미네이션이 켜진 휴일 저녁에 리버워크로 내려가요. 휴일엔 강가가 특히 북적여요. 피하려면 휴일 저녁을 비켜 가요.

아쉬운 점은 무대예요. 도톤보리에 하나뿐이던 극장, 에비스바시 근처 **오사카 쇼치쿠자**가 2026년 5월 공연을 끝으로 문을 닫았어요([공식 안내](https://www.shochiku.co.jp/wp-content/uploads/2025/08/shochiku20250828-1.pdf)).

정보 확인일 2026-11-15 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

