', content_blocks = '[{"text":"**도톤보리**라는 이름은 1612년 사재를 털어 이 강을 판 야스이 도톤에게서 왔어요. 극장과 찻집이 늘며 놀거리 거리로 자랐고, 지금은 거대한 입체 간판 아래 가게들이 한 해 내내 붐벼요([관광청 안내](https://osaka-info.jp/en/spot/dotonbori/)). 난카이·긴테쓰와 오사카 메트로 미도스지선·센니치마에선·요쓰바시선 난바역 바로 앞이에요.\n\n밤 동선의 축은 강가예요. **톤보리 리버워크**는 에비스바시~닛폰바시와 미나토마치 구간을 합쳐 600m이고, 강 쪽으로 문을 낸 가게가 30곳 넘어요. 한 해 행사가 20번쯤 열려요([리버워크](https://osaka-info.jp/en/spot/tombori-riverwalk/)). 길목엔 글리코 간판과 돈키호테 관람차가 있어요.\n\n겨울이면 산책로에 일루미네이션 **빛과 물의 원더랜드**가 켜져 거리 네온과 함께 강물에 비쳐요. 올해 점등 계획은 16:00부터 0:30까지예요([점등 안내](https://hikarimasse.osaka-chushin.fun/)).\n\n물 위에서 보려면 다자에몬바시 선착장의 **톤보리 리버 크루즈**를 타요. 약 20분 동안 강을 돌며 글리코 간판을 물 위에서 보고, 요금은 2,000엔이에요([크루즈 안내](https://osaka-info.jp/special/dc/event/detail376/)).\n\n즐기려면 일루미네이션이 켜진 휴일 저녁에 리버워크로 내려가요. 휴일엔 강가가 특히 북적여요. 피하려면 휴일 저녁을 비켜 가요.\n\n아쉬운 점은 무대예요. 도톤보리에 하나뿐이던 극장, 에비스바시 근처 **오사카 쇼치쿠자**가 2026년 5월 공연을 끝으로 문을 닫았어요([공식 안내](https://www.shochiku.co.jp/wp-content/uploads/2025/08/shochiku20250828-1.pdf)).\n\n정보 확인일 2026-11-15 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Ebisubashi%20Dotonbori%20Osaka","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=Tombori%20River%20Walk%20Osaka","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=Tombori%20River%20Cruise%20Osaka","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=Osaka%20Shochikuza%20Dotonbori","kind":"map","label":"지도에서 보기"}]}]'::jsonb WHERE id = '1904e49b-0ef9-4be9-8bb3-da7cd9603c4f'::uuid;

UPDATE public.place_reviews SET content = '
**라오허제 관광야시장**(饒河街觀光夜市, [시장처 안내](https://www.tcma.gov.taipei/News_Content.aspx?n=FAC14AD2DE4E01A4&s=0CFD6ED2C96E9CC4&sms=32F7BA052C5CA548))은 정부가 먼저 기획한 타이베이의 관광야시장이에요. 송산구 라오허제에 약 600m로 이어지고, 시장처 기준으로 매일 17:00부터 0시까지 열며 휴시일은 없어요. 기차·지하철 송산역 1·2호 출구에서 걸어 들어가요. 관광서도 약돈배이 가판이 많은 야시장으로 적어요.

입구 쪽 **세조 후자오빙**(世祖胡椒餅, [시장처 점포](https://www.tcma.gov.taipei/News_Content.aspx?n=A90BF1B705D5AC0E&s=FA645AE0684F4CBC&sms=E5D0A9B8CEF9D29F))은 17:00~24:00 열고, 249호 앞 제002번 가판이에요. 호요 가마(虎窯) 벽에 붙여 구운 후자오빙이 나와요. 돼지고기와 대파·후추를 넣고 참깨를 뿌려 굽고, 가마 여러 개를 번갈아 돌려 출고해요.

골목 안 **천둥 약돈배이**(陳董藥燉排骨, [시장처 점포](https://www.tcma.gov.taipei/News_Content.aspx?n=A90BF1B705D5AC0E&s=93592B425F56FEBB&sms=E5D0A9B8CEF9D29F))는 160호 제127번 가판으로, 17:00~24:00 열고 부정기 휴무예요. 십여 종 중약재로 서서히 끓인 약돈배이·약돈양고기와, 절인 오이를 넣은 과자육밥(瓜子肉飯)이 나와요. 배이에는 집 특제 두반장을 곁들이는 구성이에요.

타이베이 관광망도 이 야시장의 대표로 후자오빙과 약돈배이·굴 국수·오리·취두부를 적어요. 송산역 쪽에서 후자오빙을 먼저 잡고, 골목을 따라 약돈배이로 이어가면 한 끼 동선이 짧아져요.

정보 확인일 2026-11-09 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

