UPDATE public.place_reviews SET content = '
아이와 넓은 섬을 돌다 수유·기저귀 갈 곳과 유모차가 흩어질까 걱정이라면, **요코하마 하케이지마 시파라다이스**([공식 사이트](https://www.seaparadise.co.jp/institution/index.html))에서 풀려요.

수유와 기저귀 교환을 할 수 있는 베비룸이 섬 안 5곳에 있어요. 아쿠아뮤지엄 1층, 센터하우스 1층, 베이마켓 B동 1층, 카니발하우스 1층, 후레아이 라군 출구예요. 유모차 대여는 [베비칼](https://babycal-jre.com/) 사전예약제이고, 센터하우스 1층 서비스센터에서 받아요. 대상은 생후 1개월부터 4세(48개월), 몸무게 18kg까지이고, 처음 1시간은 250엔, 이후 30분마다 150엔이에요. 수족관과 베이마켓은 엘리베이터로 이동할 수 있어요. 구호센터와 미아센터도 센터하우스 1층에 있어요.

가장 가까운 역은 시사이드라인 하케이지마역이에요. 섬 안에는 일반 차량이 들어가지 못해요.

어린아이와 실내 수족관을 중심으로 반나절을 짜려는 가족에게 맞아요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

