', content_blocks = '[{"text":"아이와 넓은 섬을 돌다 수유·기저귀 갈 곳과 유모차가 흩어질까 걱정이라면, **요코하마 하케이지마 시파라다이스**([공식 사이트](https://www.seaparadise.co.jp/institution/index.html))에서 풀려요.\n\n수유와 기저귀 교환을 할 수 있는 베비룸이 섬 안 5곳에 있어요. 아쿠아뮤지엄 1층, 센터하우스 1층, 베이마켓 B동 1층, 카니발하우스 1층, 후레아이 라군 출구예요. 유모차 대여는 [베비칼](https://babycal-jre.com/) 사전예약제이고, 센터하우스 1층 서비스센터에서 받아요. 대상은 생후 1개월부터 4세(48개월), 몸무게 18kg까지이고, 처음 1시간은 250엔, 이후 30분마다 150엔이에요. 수족관과 베이마켓은 엘리베이터로 이동할 수 있어요. 구호센터와 미아센터도 센터하우스 1층에 있어요.\n\n가장 가까운 역은 시사이드라인 하케이지마역이에요. 섬 안에는 일반 차량이 들어가지 못해요.\n\n어린아이와 실내 수족관을 중심으로 반나절을 짜려는 가족에게 맞아요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Yokohama+Hakkeijima+Sea+Paradise","kind":"map","label":"요코하마 하케이지마 시파라다이스 지도"}]}]'::jsonb WHERE id = '1aad326e-a37f-40d8-95ca-f31847c494dd'::uuid;

UPDATE public.place_reviews SET content = '
무릎이 불편한 부모님과 **사파**에 간다면 첫 걱정은 긴 이동이에요. 하노이에서 라오까이까지 야간열차로 약 8시간, 라오까이에서 읍내까지 차로 약 1시간이 더 걸려요. 고속도로로 가는 차편도 있어요. 도착한 날은 일정을 비우고 다음 날 아침에 움직여요.

정상(3,143m)은 걸어서 오르지 않아도 돼요. **판시판 레전드**는 읍내와 케이블카 출발역을 므엉호아 산악열차로 잇고, 케이블카는 약 15분 만에 산 위로 올라가요. 내린 뒤 정상까지는 돌계단 약 600개가 이어지는데, 정상행 산악열차를 타면 이 계단을 다 걷지 않아도 돼요. [공식 안내](https://sunworld.vn/vi/fansipan/di-chuyen/lo-trinh-tham-quan-fansipan-chi-tiet-tu-a-den-z-29945)

산 위는 읍내와 기온이 꽤 달라요. 겹쳐 입을 옷과 돌계단에서 미끄럽지 않은 신발을 챙기고, 높은 곳이라 걸음을 서두르지 않아요.

하루 페이스는 이렇게 끊어 가요. 점심 무렵 사원 구역을 다 보기 전에 한 번 쉬어 가요. 붐비는 날은 이동과 대기 시간을 넉넉히 잡고, 정상을 본 뒤에는 늦지 않게 내려와요.

깟깟 마을은 벽돌길을 따라 수백 계단을 내려가는 길이라, 판시판과 같은 날에는 넣지 않아요.

오르막은 탈것에 맡기고 쉬는 시간을 먼저 정해 두려는 부모님 동반 가족에게 맞는 하루예요.

