UPDATE public.place_reviews SET content = '
가나자와는 정원 하나와 골목 하나만 고르면 걸음이 느려져요. 정원은 특별명승으로 지정된 **겐로쿠엔(兼六園)**이에요. 겨울을 앞둔 철에는 눈 무게에서 나무를 지키는 설조(雪吊り) 작업을 해요. 개원 시간은 날마다 공식 페이지에 올라와요([겐로쿠엔 공식](https://www.pref.ishikawa.jp/siro-niwa/kenrokuen/)).

정원에서 충분히 쉬었다면 히가시차야로 넘어가요. 보존 지구라서 입장료도 개원 시간도 없고, 대부분의 가게가 10:00에 열어 17:00에 닫아요. 이 골목에서는 먹으면서 걷는 게 금지라서 산 가게 안에서 먹어야 해요([히가시차야 안내](https://www.kanazawa-kankoukyoukai.or.jp/higashi)).

골목 한 줄만 보면 한 시간이 채 안 돼요. 강 건너 주계정 쪽 길과 묶어도 한 시간쯤이고, 저녁에는 사람 그림자가 드물어져요. 길 끝 아카리자카에서 속도를 한 번 더 낮춰 보세요.

히가시차야는 하시바초(橋場町) 정류장에서 걸어서 5분쯤이에요([교통 안내](https://www.kanazawa-kankoukyoukai.or.jp/spot/detail_10212.html)).

