UPDATE public.place_reviews SET content = '
도톤보리에서는 밀가루 없이 산마로만 굽는 오코노미야키와 큼직한 문어가 든 다코야키, 이 두 접시를 어느 가게에서 먹을지만 정하면 동선이 거의 끝나요.

도톤보리에서 아케이드로 들어서면 바로 나오는 **미즈노**(美津の, [공식 사이트](https://www.mizuno-osaka.com/))는 11:00~22:00(라스트오더 21:00) 열고, 2026년 2월부터 정기휴일 없이 운영해요. 산마 100%로 굽는 야마이모야키가 간판이고, 옛 방식의 요쇼쿠야키와 여섯 가지 재료를 넣은 믹스도 나와요. 2인부터 코스는 [전화 예약](tel:+81662126360)을 받아요. 다코야키는 도톤보리 1-10-5 **쿠쿠루**(くくる) 본점으로 가요. 포장은 평일 10:30~21:30, 주말·공휴일 10:00~21:45, 매장 식사는 평일 11:00~20:30, 주말·공휴일 10:30~20:30이에요. 큰 문어를 넣은 다코야키와 달걀 반죽의 아카시야키, 본점에만 있는 빗쿠리 다코야키가 나와요. 자리만 잡으려면 전날까지 [전화](tel:+81662127381)나 [타베로그](https://tabelog.com/osaka/A2701/A270202/27001546/)로 예약하면 돼요.

재료가 궁금하면 닛폰바시역 바로 앞 **구로몬 시장**([공식 안내](https://osaka-info.jp/en/spot/kuromon-market/))으로 이어 가요. 미즈노도 재료를 이 시장에서 들여와요. 580m쯤 되는 아케이드에 150곳 안팎의 가게가 늘어서고, 요리사들이 장을 보러 오는 시장이라 복어·생선 가게가 많아요. 아침엔 장보는 손님, 한낮부터는 여행객이 늘어나니 한산하게 보려면 이른 시간이 편해요. 하나 걸리는 건 도톤보리 저녁 피크엔 두 가게 모두 대기가 길어질 수 있다는 점이에요.

산마 오코노미야키 한 장과 문어 다코야키 한 접시로 도톤보리를 맛보고 싶은 저녁이라면 이 순서를 권해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"도톤보리에서는 밀가루 없이 산마로만 굽는 오코노미야키와 큼직한 문어가 든 다코야키, 이 두 접시를 어느 가게에서 먹을지만 정하면 동선이 거의 끝나요.\n\n도톤보리에서 아케이드로 들어서면 바로 나오는 **미즈노**(美津の, [공식 사이트](https://www.mizuno-osaka.com/))는 11:00~22:00(라스트오더 21:00) 열고, 2026년 2월부터 정기휴일 없이 운영해요. 산마 100%로 굽는 야마이모야키가 간판이고, 옛 방식의 요쇼쿠야키와 여섯 가지 재료를 넣은 믹스도 나와요. 2인부터 코스는 [전화 예약](tel:+81662126360)을 받아요. 다코야키는 도톤보리 1-10-5 **쿠쿠루**(くくる) 본점으로 가요. 포장은 평일 10:30~21:30, 주말·공휴일 10:00~21:45, 매장 식사는 평일 11:00~20:30, 주말·공휴일 10:30~20:30이에요. 큰 문어를 넣은 다코야키와 달걀 반죽의 아카시야키, 본점에만 있는 빗쿠리 다코야키가 나와요. 자리만 잡으려면 전날까지 [전화](tel:+81662127381)나 [타베로그](https://tabelog.com/osaka/A2701/A270202/27001546/)로 예약하면 돼요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"재료가 궁금하면 닛폰바시역 바로 앞 **구로몬 시장**([공식 안내](https://osaka-info.jp/en/spot/kuromon-market/))으로 이어 가요. 미즈노도 재료를 이 시장에서 들여와요. 580m쯤 되는 아케이드에 150곳 안팎의 가게가 늘어서고, 요리사들이 장을 보러 오는 시장이라 복어·생선 가게가 많아요. 아침엔 장보는 손님, 한낮부터는 여행객이 늘어나니 한산하게 보려면 이른 시간이 편해요. 하나 걸리는 건 도톤보리 저녁 피크엔 두 가게 모두 대기가 길어질 수 있다는 점이에요.\n\n산마 오코노미야키 한 장과 문어 다코야키 한 접시로 도톤보리를 맛보고 싶은 저녁이라면 이 순서를 권해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=%E7%BE%8E%E6%B4%A5%E3%81%AE+%E9%81%93%E9%A0%93%E5%A0%801-4-15+%E5%A4%A7%E9%98%AA","kind":"map","label":"미즈노 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E3%81%9F%E3%81%93%E5%AE%B6%E9%81%93%E9%A0%93%E5%A0%80%E3%81%8F%E3%81%8F%E3%82%8B+%E9%81%93%E9%A0%93%E5%A0%80%E6%9C%AC%E5%BA%97","kind":"map","label":"쿠쿠루 본점 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Kuromon+Market+Osaka","kind":"map","label":"구로몬 시장 지도"}]}]'::jsonb WHERE id = '2e1d1d1b-45ae-4e33-8016-c925186692a1'::uuid;

UPDATE public.place_reviews SET content = '
바스티유·슈맹 베르 역에서 가까운 **보주 광장**은 마레에서 ‘멈춰 앉을 자리’의 중심이에요. 아케이드로 둘러싸인 네모난 광장과 그 뒤 정원 하나를 문 하나로 잇는 반나절 동선이에요.

광장 한가운데 **루이 13세 소광장**([공식 안내](https://www.paris.fr/lieux/square-louis-xiii-36))은 아침에 문을 열고, 닫는 시각은 계절마다 달라요. 오솔길을 따라 벤치와 분수가 있고 화장실도 있어서, 잔디 가장자리 벤치에서 숨을 고르기 좋아요. 아케이드 아래 25번지의 살롱 드 테 **카레트**([공식 사이트](https://paris-carette.fr/nos-magasins/place-des-vosges/))는 매일 오전 7시부터 자정까지 열어요.

광장 쪽 파빌리온 문을 밀고 들어서면 **쉴리 저택**([공식 사이트](https://www.hotel-de-sully.fr/))의 정원이 나와요. 안뜰과 달리 상록 참나무 그늘 아래가 조용하고, 다섯 아치 위에 선 오랑주리 가운데엔 돌에 새긴 해시계가 있어요. 정원과 안뜰을 지나면 생탕투안 거리 62번지로 나와요. 안뜰과 정원은 매일 9시~19시 열고(쉴리 저택 전체가 1월 1일·5월 1일·11월 1일·11일·12월 25일 휴관), 안쪽 서점은 월요일을 빼고 13시~19시예요.

아쉬운 점은 쉴리 저택 건물 안은 예약제 해설 방문([온라인 예약](https://www.hotel-de-sully.fr/visiter/visites-et-activites)) 때만 열려서 안뜰과 정원까지만 걸을 수 있다는 거예요. 광장 정원엔 반려동물도 함께 들어갈 수 없어요.

분수 곁 벤치에서 오랑주리 해시계까지, 파빌리온 문 하나로 마레의 두 정원을 잇는 오후예요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
