UPDATE public.place_reviews SET content = '
프라하는 **카를교** 인파에서 한 걸음만 비켜서도 공기가 꽤 달라져요. 말라스트라나 쪽으로 강을 건너 페트르진 언덕으로 올라가면, 도시 소리가 나무 사이로 낮게 가라앉는 편이에요.

**페트르진 정원**([공식 안내](https://prague.eu/en/objevujte/petrin-gardens-petrinske-sady/))은 경사가 있지만 급하게 오를 필요가 없어요. 중간중간 벤치와 잔디 가장자리가 있어서, 숨이 차기 전에 한 번씩 앉아 가도 괜찮아요. 정원 안에는 화장실과 피크닉 자리도 있고, 남쪽 비탈의 **킨스키 정원**([공식 안내](https://prague.eu/cs/objevujte/zahrada-kinskych/))은 연중 자유롭게 들어갈 수 있어요. 오전이나 평일 오후라면 한산한 편이라 페이스를 낮추기 좋아요.

내려올 때는 큰길보다 말라스트라나의 좁은 뒷골목을 고르는 편이 머물기 편해요. 돌바닥 골목 안쪽 카페는 창가 자리 하나만 잡아도 오후 빛이 천천히 움직이는 게 보이거든요. 커피 한 잔이 식을 때까지 앉아 있어도 괜찮은 분위기예요.

아쉬운 점은 성 쪽으로 이어지는 주요 동선은 낮 시간대에 붐비기 쉽다는 거예요. 돌바닥과 오르막이 겹치면 발 피로도 금방 쌓여요.

정원 벤치와 골목 창가 사이를 천천히 오가고 싶은 분께 잘 맞아요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"프라하는 **카를교** 인파에서 한 걸음만 비켜서도 공기가 꽤 달라져요. 말라스트라나 쪽으로 강을 건너 페트르진 언덕으로 올라가면, 도시 소리가 나무 사이로 낮게 가라앉는 편이에요.\n\n**페트르진 정원**([공식 안내](https://prague.eu/en/objevujte/petrin-gardens-petrinske-sady/))은 경사가 있지만 급하게 오를 필요가 없어요. 중간중간 벤치와 잔디 가장자리가 있어서, 숨이 차기 전에 한 번씩 앉아 가도 괜찮아요. 정원 안에는 화장실과 피크닉 자리도 있고, 남쪽 비탈의 **킨스키 정원**([공식 안내](https://prague.eu/cs/objevujte/zahrada-kinskych/))은 연중 자유롭게 들어갈 수 있어요. 오전이나 평일 오후라면 한산한 편이라 페이스를 낮추기 좋아요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"내려올 때는 큰길보다 말라스트라나의 좁은 뒷골목을 고르는 편이 머물기 편해요. 돌바닥 골목 안쪽 카페는 창가 자리 하나만 잡아도 오후 빛이 천천히 움직이는 게 보이거든요. 커피 한 잔이 식을 때까지 앉아 있어도 괜찮은 분위기예요.\n\n","type":"text"},{"type":"image","image_index":1},{"text":"아쉬운 점은 성 쪽으로 이어지는 주요 동선은 낮 시간대에 붐비기 쉽다는 거예요. 돌바닥과 오르막이 겹치면 발 피로도 금방 쌓여요.\n\n정원 벤치와 골목 창가 사이를 천천히 오가고 싶은 분께 잘 맞아요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Pet%C5%99%C3%ADnsk%C3%A9+sady+Praha","kind":"map","label":"페트르진 정원 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Zahrada+Kinsk%C3%BDch+Praha","kind":"map","label":"킨스키 정원 지도"}]}]'::jsonb WHERE id = '2f5b5725-00d1-45a0-a9d3-01cd73716656'::uuid;

UPDATE public.place_reviews SET content = '
카이로의 한 끼는 예약하는 식당보다 길거리 가판과 작은 식당 카운터에서 고르는 쪽에 무게가 실려요. 뭘 먹을지보다 어디서, 언제 서서 기다릴지를 먼저 정하면 한결 편해요.

대표 메뉴는 코샤리예요. 쌀·파스타·렌틸콩 위에 토마토소스와 튀긴 양파를 얹어 섞어 먹는 한 그릇이라 든든한 편이에요. 다운타운 마아루프 거리 16번지, 샹폴리옹 거리와 만나는 모퉁이의 **코샤리 아부 타렉**(Koshary Abou Tarek, [공식 사이트](https://www.koshary-aboutarek.com/en/branches))은 코샤리와 디저트를 주력으로 내고, 가말 압델 나세르 지하철역이 가까워요. 잠두콩 팔라펠인 타메야는 자말렉 7월 26일 거리 16번지의 **주바**(Zööba, [공식 사이트](https://zoobaeats.com/)) 1호점에서 골라 보기 좋아요. 길거리 음식을 식당식으로 다듬은 곳이라 타메야, 코샤리, 발라디 빵에 눌러 구운 하와우시가 대표로 나와요. 자리는 서서 먹는 가판, 플라스틱 의자, 테이크아웃이 섞여 있어 혼밥도 자연스러운 편이에요.

타메야와 풀 메담스는 아침에 가장 활발한 편이에요. 코샤리 가게는 점심·저녁 식사 시간대에 붐비니 조금 비껴 가면 대기가 짧아지거든요. 회전이 빠르고 눈앞에서 바로 튀기거나 담아 주는 곳이 고르기 무난해요. 유적 주변 관광 동선 식당보다 동네 사람이 줄 서는 가판이 현지 쪽 신호예요. 아쉬운 점은 더운 날 날채소나 얼음 음료에 속이 불편할 수 있다는 거예요. 익힌 메뉴 위주로 고르는 걸 추천해요.

코샤리 한 그릇과 타메야 하나로 카이로다운 길거리 한 끼를 맛보고 싶은 일정에 추천해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"카이로의 한 끼는 예약하는 식당보다 길거리 가판과 작은 식당 카운터에서 고르는 쪽에 무게가 실려요. 뭘 먹을지보다 어디서, 언제 서서 기다릴지를 먼저 정하면 한결 편해요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"대표 메뉴는 코샤리예요. 쌀·파스타·렌틸콩 위에 토마토소스와 튀긴 양파를 얹어 섞어 먹는 한 그릇이라 든든한 편이에요. 다운타운 마아루프 거리 16번지, 샹폴리옹 거리와 만나는 모퉁이의 **코샤리 아부 타렉**(Koshary Abou Tarek, [공식 사이트](https://www.koshary-aboutarek.com/en/branches))은 코샤리와 디저트를 주력으로 내고, 가말 압델 나세르 지하철역이 가까워요. 잠두콩 팔라펠인 타메야는 자말렉 7월 26일 거리 16번지의 **주바**(Zööba, [공식 사이트](https://zoobaeats.com/)) 1호점에서 골라 보기 좋아요. 길거리 음식을 식당식으로 다듬은 곳이라 타메야, 코샤리, 발라디 빵에 눌러 구운 하와우시가 대표로 나와요. 자리는 서서 먹는 가판, 플라스틱 의자, 테이크아웃이 섞여 있어 혼밥도 자연스러운 편이에요.\n\n타메야와 풀 메담스는 아침에 가장 활발한 편이에요. 코샤리 가게는 점심·저녁 식사 시간대에 붐비니 조금 비껴 가면 대기가 짧아지거든요. 회전이 빠르고 눈앞에서 바로 튀기거나 담아 주는 곳이 고르기 무난해요. 유적 주변 관광 동선 식당보다 동네 사람이 줄 서는 가판이 현지 쪽 신호예요. 아쉬운 점은 더운 날 날채소나 얼음 음료에 속이 불편할 수 있다는 거예요. 익힌 메뉴 위주로 고르는 걸 추천해요.\n\n코샤리 한 그릇과 타메야 하나로 카이로다운 길거리 한 끼를 맛보고 싶은 일정에 추천해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/Koshary+Abou+Tarek+Champollion+Street+Downtown+Cairo","kind":"map","label":"코샤리 아부 타렉 지도"},{"url":"https://www.google.com/maps/search/Zooba+16+26th+of+July+St+Zamalek+Cairo","kind":"map","label":"주바 지도"}]}]'::jsonb WHERE id = '2fc0c1c5-0d8a-40a0-90f0-ef09858f894d'::uuid;

UPDATE public.place_reviews SET content = '
자카르타 서부의 옛 도심에서는 커피집이 14:00에 문을 닫고, 식당은 자정까지 불을 켜요. 그래서 한 끼의 순서가 시계대로 정해져요.

**코피 에스 탁키**(Kopi Es Tak Kie, [관광 안내](https://enjoy.jakarta.go.id/article/kopi-es-takkie))는 1927년 페탁 슴빌란의 수레에서 시작해 1930년 글로독 간 글로리아 시장 안에 문을 연 커피집이에요. 그 가게가 지금도 같은 자리에 있어요. 커피는 블랙과 밀크 두 가지뿐이고, 뜨겁게나 얼음 넣어 골라요. 곁들일 접시로는 박미 아얌, 꾸에띠아우, 나시 짬뿌르가 있어요. 07:00~14:00에 열고, 트랜스자카르타 1번 코리도르 글로독 정류장이나 KRL 자카르타 코타역에서 걸어서 닿아요.

**카페 바타비아**(Café Batavia, [공식 누리집](https://www.cafebatavia.com/))는 1805년에 지은 코타 투아의 식민지 시대 건물에서 1993년부터 영업해 온 식당이에요. 높은 유리창 옆자리에서 코타 투아 풍경이 보이고, 벽은 옛 사진으로 채워져 있어요. 시그니처는 꽃게에 망고·파파야·타마린드·야자 설탕을 버무린 루작 끄삐띵, 삼발 로아에 조개·새우·연어알을 올린 나시 고렝 로아, 판단 잎 향의 코코넛 디저트 뿌뜨리 만디예요. 월~목 09:00~24:00, 금 09:00~01:00, 토·일 07:00~01:00에 열어요. 외국인 여행자가 많이 찾는 곳이라 [전화 예약](tel:+622169155531)은 일찍 해 두면 좋아요.

토·일에는 두 집 모두 07:00에 열어요. 아침은 탁키의 얼음 밀크커피와 박미 아얌으로 먹고, 나시 고렝 로아는 바타비아 점심이나 저녁 몫으로 남겨 두세요.

정보 확인일 2026-11-17 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
