UPDATE public.place_reviews SET content = '
**더 그리드 푸드 마켓**(The Grid Food Market, [공식 누리집](https://thegridfoodmarket.com/))은 마카티 록웰 드라이브와 에스트레야가 만나는 파워플랜트 몰 R2 확장 층에 있어요.

돼지 구이는 **레 촌**(Le Chon, [레 촌 메뉴](https://thegridfoodmarket.com/collections/stall-5-le-chon))이 오리지널 레 촌 포르체타와 고르메 레촌 마녹을 내요. 포르체타에는 트러플과 바왕(마늘) 맛도 있고, 같은 가판에는 레 촌 시시그와 앙구스 비프 벨리도 있어요. 같은 장의 **플라워보이**(Flowerboy)는 팟타이, 오믈렛, 크리스피 포크찹을 내고, **톰슨 로드**(Thomson Road)는 점보 시오마이, 락사, 클레이팟 라이스를 내요.

레 촌의 포르체타를 먼저 고르고, 국수가 당기면 톰슨 로드의 락사로 이어가면 한 끼 구성이 맞춰져요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

