', content_blocks = '[{"text":"**더 그리드 푸드 마켓**(The Grid Food Market, [공식 누리집](https://thegridfoodmarket.com/))은 마카티 록웰 드라이브와 에스트레야가 만나는 파워플랜트 몰 R2 확장 층에 있어요.\n\n돼지 구이는 **레 촌**(Le Chon, [레 촌 메뉴](https://thegridfoodmarket.com/collections/stall-5-le-chon))이 오리지널 레 촌 포르체타와 고르메 레촌 마녹을 내요. 포르체타에는 트러플과 바왕(마늘) 맛도 있고, 같은 가판에는 레 촌 시시그와 앙구스 비프 벨리도 있어요. 같은 장의 **플라워보이**(Flowerboy)는 팟타이, 오믈렛, 크리스피 포크찹을 내고, **톰슨 로드**(Thomson Road)는 점보 시오마이, 락사, 클레이팟 라이스를 내요.\n\n레 촌의 포르체타를 먼저 고르고, 국수가 당기면 톰슨 로드의 락사로 이어가면 한 끼 구성이 맞춰져요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=The+Grid+Food+Market+Power+Plant+Mall+Rockwell+Makati","kind":"map","label":"더 그리드 푸드 마켓 지도"}]}]'::jsonb WHERE id = '407d7a88-3795-41bc-9740-70fc0b328600'::uuid;

UPDATE public.place_reviews SET content = '
교토는 담장 밖 골목과 작은 창이 분위기를 완성하는 도시예요. 소리보다 질감—자갈, 나무문, 창호—이 먼저 다가오고, 돌과 나무, 차 향이 섞인 공기에 맞춰 속도를 고르면 잘 맞아요.

하루는 이른 아침 **철학의 길**에서 시작해 보세요. **긴카쿠지**와 **냐쿠오지 다리** 사이 수로를 따라 걷는 길이라 페이스를 낮추기 좋아요. 길 가까이 있는 **호넨인**은 긴카쿠지보다 찾는 사람이 적은 조용한 절로, 오전 6시부터 오후 4시까지 문을 열고 행사가 없는 날엔 본당 앞까지 참도가 열려 있어요. 산문을 지나면 양쪽에 흰 모래 단이 놓여 있어서, 그 사이를 천천히 지나기만 해도 호흡이 가라앉아요. 머물러도 괜찮은 그늘이 있어요.

오후엔 북쪽 이치조지로 옮겨 보세요. 에이잔 전철 이치조지역에서 걸어서 3분 거리의 **게이분샤 이치조지점**([공식 사이트](https://www.keibunsha-store.com/))은 매일 11:00~19:00 열고(1월 1일 휴무), 책장 사이를 돌며 시간을 잊기 좋아요. **시센도** 가까운 화과자점 **이치조지 나카타니**의 찻집은 10:00부터 17:00 라스트오더까지 열고 수요일엔 쉬어요. 차 한 잔이 식는 동안 창밖 흐름만 지켜봐도 분위기가 읽혀요.

아쉬운 점은 단풍철이면 철학의 길과 이어지는 골목까지 인파가 밀려 여유 공기가 금방 옅어진다는 거예요.

돌길 아침과 책방·찻집 오후를 천천히 잇고 싶은 분께 잘 맞아요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"교토는 담장 밖 골목과 작은 창이 분위기를 완성하는 도시예요. 소리보다 질감—자갈, 나무문, 창호—이 먼저 다가오고, 돌과 나무, 차 향이 섞인 공기에 맞춰 속도를 고르면 잘 맞아요.\n\n하루는 이른 아침 **철학의 길**에서 시작해 보세요. **긴카쿠지**와 **냐쿠오지 다리** 사이 수로를 따라 걷는 길이라 페이스를 낮추기 좋아요. 길 가까이 있는 **호넨인**은 긴카쿠지보다 찾는 사람이 적은 조용한 절로, 오전 6시부터 오후 4시까지 문을 열고 행사가 없는 날엔 본당 앞까지 참도가 열려 있어요. 산문을 지나면 양쪽에 흰 모래 단이 놓여 있어서, 그 사이를 천천히 지나기만 해도 호흡이 가라앉아요. 머물러도 괜찮은 그늘이 있어요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"오후엔 북쪽 이치조지로 옮겨 보세요. 에이잔 전철 이치조지역에서 걸어서 3분 거리의 **게이분샤 이치조지점**([공식 사이트](https://www.keibunsha-store.com/))은 매일 11:00~19:00 열고(1월 1일 휴무), 책장 사이를 돌며 시간을 잊기 좋아요. **시센도** 가까운 화과자점 **이치조지 나카타니**의 찻집은 10:00부터 17:00 라스트오더까지 열고 수요일엔 쉬어요. 차 한 잔이 식는 동안 창밖 흐름만 지켜봐도 분위기가 읽혀요.\n\n","type":"text"},{"type":"image","image_index":1},{"text":"아쉬운 점은 단풍철이면 철학의 길과 이어지는 골목까지 인파가 밀려 여유 공기가 금방 옅어진다는 거예요.\n\n돌길 아침과 책방·찻집 오후를 천천히 잇고 싶은 분께 잘 맞아요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Honen-in+Kyoto","kind":"map","label":"호넨인 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E6%81%B5%E6%96%87%E7%A4%BE+%E4%B8%80%E4%B9%97%E5%AF%BA%E5%BA%97+%E4%BA%AC%E9%83%BD","kind":"map","label":"게이분샤 이치조지점 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E4%B8%80%E4%B9%97%E5%AF%BA%E4%B8%AD%E8%B0%B7+%E4%BA%AC%E9%83%BD","kind":"map","label":"이치조지 나카타니 지도"}]}]'::jsonb WHERE id = '4181696e-e4f4-40c9-9c04-51dd5f23825f'::uuid;

UPDATE public.place_reviews SET content = '
해 질 녘 자리는 **산타 루지아 전망대**로 잡아요. [타일과 정원이 있는 전망대이고, 타주 강이 배경에 깔려요. 산타 엥그라시아 돔, 산투 이스테방 성당, 상 미겔 성당의 두 탑을 기준으로 구도를 짜요. 알파마 골목은 계단과 길이 얽혀 있어요.](https://www.visitlisboa.com/en/places/miradouro-de-santa-luzia) 해 질 녘에는 강빛이 지붕과 돔을 받아 보여 주기 좋은 컷이 나와요. 지나가는 트램을 전경에 넣어도 좋아요.

귀가는 전망대 정류장의 [12E 트램](https://www.carris.pt/en/travel/carreiras/12e/)으로 묶어요. 마르팅 모니스와 루이스 드 카몽이스 광장을 잇고, 산타 루지아 전망대와 포르타스 두 솔에 정차해요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

