UPDATE public.place_reviews SET content = '
해 질 녘 첫 자리는 도르소두로 남쪽 **자테레 강변**으로 잡아요. 넓은 주데카 운하 건너 **주데카 섬** 강변에 [레덴토레 성당과 치텔레 성당이 물을 마주하고 서 있어요](https://www.italia.it/it/veneto/venezia/isola-della-giudecca). 성당 실루엣을 화면 위쪽 3분의 1에 두고, 운하를 오가는 배를 전경에 넣으면 골든아워 물빛이 살아나는 컷이 나와요.

빛이 빠지기 시작하면 자테레 A 정류장에서 2번 바포레토를 타요. [2번 시간표](https://actv.avmspa.it/sites/default/files/avm/navigazione/Actv_nav_linea_2.pdf)대로 피아찰레 로마와 페로비아를 거쳐 리알토에 닿아요.

**리알토 다리**는 [대운하를 한 아치로 건너는 흰 돌다리예요](https://www.italia.it/it/veneto/venezia/ponte-di-rialto). 두 줄 상점 사이로 보행로가 세 갈래 지나가요. 블루아워에는 다리 아래 강변에서 아치 곡선과 양안 불빛을 한 프레임에 담는 각도가 잘 나와요. 수면 반사를 아래쪽에 넉넉히 남기면 보여 주기 좋은 컷이에요.

귀가는 리알토 정류장의 **1번 바포레토**로 묶어요. [1번 시간표](https://actv.avmspa.it/sites/default/files/avm/navigazione/Actv_nav_linea_1.pdf)상 대운하를 따라 페로비아·피아찰레 로마 쪽과 산마르코·리도 쪽 양방향으로 다녀요. **75분권**은 [9.50유로이고, 표는 탈 때마다, 갈아탈 때마다 정류장 개찰기에 대요](https://actv.avmspa.it/en/content/venice-urban-services). 배 위에서 지나가는 운하 야경도 마지막 컷으로 남기기 좋아요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"해 질 녘 첫 자리는 도르소두로 남쪽 **자테레 강변**으로 잡아요. 넓은 주데카 운하 건너 **주데카 섬** 강변에 [레덴토레 성당과 치텔레 성당이 물을 마주하고 서 있어요](https://www.italia.it/it/veneto/venezia/isola-della-giudecca). 성당 실루엣을 화면 위쪽 3분의 1에 두고, 운하를 오가는 배를 전경에 넣으면 골든아워 물빛이 살아나는 컷이 나와요.\n\n빛이 빠지기 시작하면 자테레 A 정류장에서 2번 바포레토를 타요. [2번 시간표](https://actv.avmspa.it/sites/default/files/avm/navigazione/Actv_nav_linea_2.pdf)대로 피아찰레 로마와 페로비아를 거쳐 리알토에 닿아요.\n\n**리알토 다리**는 [대운하를 한 아치로 건너는 흰 돌다리예요](https://www.italia.it/it/veneto/venezia/ponte-di-rialto). 두 줄 상점 사이로 보행로가 세 갈래 지나가요. 블루아워에는 다리 아래 강변에서 아치 곡선과 양안 불빛을 한 프레임에 담는 각도가 잘 나와요. 수면 반사를 아래쪽에 넉넉히 남기면 보여 주기 좋은 컷이에요.\n\n귀가는 리알토 정류장의 **1번 바포레토**로 묶어요. [1번 시간표](https://actv.avmspa.it/sites/default/files/avm/navigazione/Actv_nav_linea_1.pdf)상 대운하를 따라 페로비아·피아찰레 로마 쪽과 산마르코·리도 쪽 양방향으로 다녀요. **75분권**은 [9.50유로이고, 표는 탈 때마다, 갈아탈 때마다 정류장 개찰기에 대요](https://actv.avmspa.it/en/content/venice-urban-services). 배 위에서 지나가는 운하 야경도 마지막 컷으로 남기기 좋아요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Fondamenta%20delle%20Zattere%20Venezia","kind":"map","label":"자테레 강변 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Chiesa%20del%20Redentore%20Giudecca%20Venezia","kind":"map","label":"주데카 섬 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Ponte%20di%20Rialto%20Venezia","kind":"map","label":"리알토 다리 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Rialto%20vaporetto%20stop%20Venezia","kind":"map","label":"1번 바포레토 지도"}]}]'::jsonb WHERE id = '44178bf5-e46c-48f6-8781-532835d850bc'::uuid;

UPDATE public.place_reviews SET content = '
**트리아나 시장**(Mercado de Triana, [공식 누리집](https://mercadodetrianasevilla.com/horarios/))은 알토사노 광장, 산호르헤 거리 6번에 있어요. 공식 시간표는 식재료 점포를 월~토 9:00~14:30로 적고, 일·공휴일에는 점포가 쉬어요. 바·식당은 월~토 9:00~17:00와 18:00~0시, 일·공휴일 10:00~17:00에 열려요.

같은 장의 **바 라 무랄라**(Bar La Muralla, [가판 안내](https://mercadodetrianasevilla.com/comercio/bar-la-muralla/))는 72번 가판이에요. 시장에서 받은 재료로 이베리코 챠시나와 플랑차 생선, 여러 가지 튀김, 가정식 스튜와 레부엘토를 내요.

하몬을 고르면 **하모네리아 호세 루이스 로메로**(Jamonería José Luis Romero, [하몬 안내](https://mercadodetrianasevilla.com/comercio/jamoneria-jose-luis-romero/))가 50·57~59번 가판이에요. 판매 공간과 시식 공간이 나뉘고, 벨요타 이베리코 하몬을 그 자리에서 썰어 줘요. 시식 메뉴에는 이베리코 하몬 타르타르와, 훈제 정어리 살코기에 살모레호를 곁들인 접시가 있고, 하몬 카르투초를 받아 장 안에서 먹을 수도 있어요.

점포가 닫힌 뒤에도 바 영업이 이어지니, 오전에 하몬을 보고 18시 이후 타파스 바로 넘어가는 순서가 맞아요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**트리아나 시장**(Mercado de Triana, [공식 누리집](https://mercadodetrianasevilla.com/horarios/))은 알토사노 광장, 산호르헤 거리 6번에 있어요. 공식 시간표는 식재료 점포를 월~토 9:00~14:30로 적고, 일·공휴일에는 점포가 쉬어요. 바·식당은 월~토 9:00~17:00와 18:00~0시, 일·공휴일 10:00~17:00에 열려요.\n\n같은 장의 **바 라 무랄라**(Bar La Muralla, [가판 안내](https://mercadodetrianasevilla.com/comercio/bar-la-muralla/))는 72번 가판이에요. 시장에서 받은 재료로 이베리코 챠시나와 플랑차 생선, 여러 가지 튀김, 가정식 스튜와 레부엘토를 내요.\n\n하몬을 고르면 **하모네리아 호세 루이스 로메로**(Jamonería José Luis Romero, [하몬 안내](https://mercadodetrianasevilla.com/comercio/jamoneria-jose-luis-romero/))가 50·57~59번 가판이에요. 판매 공간과 시식 공간이 나뉘고, 벨요타 이베리코 하몬을 그 자리에서 썰어 줘요. 시식 메뉴에는 이베리코 하몬 타르타르와, 훈제 정어리 살코기에 살모레호를 곁들인 접시가 있고, 하몬 카르투초를 받아 장 안에서 먹을 수도 있어요.\n\n점포가 닫힌 뒤에도 바 영업이 이어지니, 오전에 하몬을 보고 18시 이후 타파스 바로 넘어가는 순서가 맞아요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Mercado+de+Triana+Plaza+del+Altozano+Sevilla","kind":"map","label":"트리아나 시장 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Bar+La+Muralla+Mercado+de+Triana+Sevilla","kind":"map","label":"바 라 무랄라 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Jamoneria+Jose+Luis+Romero+Mercado+de+Triana+Sevilla","kind":"map","label":"하모네리아 호세 루이스 로메로 지도"}]}]'::jsonb WHERE id = '45fcae82-f643-4155-a7d9-ea3e9f18fe70'::uuid;

UPDATE public.place_reviews SET content = '
해가 지면 나카강 둑에 리어카 포장마차가 줄지어 서는 곳이 **나카스 야타이**예요. 후쿠오카시 [영업 규칙](https://www.city.fukuoka.lg.jp/keizai/yatai/shisei/documents/01_rule.pdf)상 자리를 펴는 시간은 설치·철거를 합쳐 오후 5시부터 새벽 4시까지이고, 한 칸은 폭 3m·깊이 2.5m 안이에요. 요금표는 손님 눈에 잘 띄는 곳에 걸어야 해요.

시 야타이 지도 기준으로 문 여는 시각은 가게마다 달라서 이르면 18시쯤, 대개 18시 반~19시예요. 날씨가 거친 날은 갑자기 쉬기도 해요. 주문 전에 요금표부터 보고, 기본 안주(오토시)를 두는 가게도 있으니 앉을 때 물어보면 깔끔해요.

청류공원 쪽 **고지마 상점**(小島商店, [시 관광 소개](https://yokanavi.com/features/260529))은 하카타 돈코츠 라멘이 중심이에요. 갓 끓인 국물과 숙성한 국물 두 솥을 섞어 맛을 고르게 맞추고, 많을 때는 30명쯤 줄이 서는 가판이에요.

같은 공원의 **다케짱**(武ちゃん, [시 관광 특집](https://yokanavi.com/features/260602))은 라멘 대신 한입 교자를 내요. 한 접시 8개로, 아와지섬 양파를 재워 단맛을 살리고 직접 만든 유즈코쇼를 곁들여요. 음식 주문은 한 번, 추가는 음료만 받는 방식이고 일주일에 3~4일 정도만 열어요.

두 가판은 걸어서 2~3분 거리라, 줄이 짧은 쪽에서 먼저 한 그릇 하고 다른 쪽으로 옮겨 가는 순서가 무난해요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"해가 지면 나카강 둑에 리어카 포장마차가 줄지어 서는 곳이 **나카스 야타이**예요. 후쿠오카시 [영업 규칙](https://www.city.fukuoka.lg.jp/keizai/yatai/shisei/documents/01_rule.pdf)상 자리를 펴는 시간은 설치·철거를 합쳐 오후 5시부터 새벽 4시까지이고, 한 칸은 폭 3m·깊이 2.5m 안이에요. 요금표는 손님 눈에 잘 띄는 곳에 걸어야 해요.\n\n시 야타이 지도 기준으로 문 여는 시각은 가게마다 달라서 이르면 18시쯤, 대개 18시 반~19시예요. 날씨가 거친 날은 갑자기 쉬기도 해요. 주문 전에 요금표부터 보고, 기본 안주(오토시)를 두는 가게도 있으니 앉을 때 물어보면 깔끔해요.\n\n청류공원 쪽 **고지마 상점**(小島商店, [시 관광 소개](https://yokanavi.com/features/260529))은 하카타 돈코츠 라멘이 중심이에요. 갓 끓인 국물과 숙성한 국물 두 솥을 섞어 맛을 고르게 맞추고, 많을 때는 30명쯤 줄이 서는 가판이에요.\n\n같은 공원의 **다케짱**(武ちゃん, [시 관광 특집](https://yokanavi.com/features/260602))은 라멘 대신 한입 교자를 내요. 한 접시 8개로, 아와지섬 양파를 재워 단맛을 살리고 직접 만든 유즈코쇼를 곁들여요. 음식 주문은 한 번, 추가는 음료만 받는 방식이고 일주일에 3~4일 정도만 열어요.\n\n두 가판은 걸어서 2~3분 거리라, 줄이 짧은 쪽에서 먼저 한 그릇 하고 다른 쪽으로 옮겨 가는 순서가 무난해요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=%E4%B8%AD%E6%B4%B2+%E5%B1%8B%E5%8F%B0+%E6%B8%85%E6%B5%81%E5%85%AC%E5%9C%92","kind":"map","label":"나카스 야타이 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E5%B0%8F%E5%B3%B6%E5%95%86%E5%BA%97+%E4%B8%AD%E6%B4%B2+%E5%B1%8B%E5%8F%B0","kind":"map","label":"고지마 상점 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E6%AD%A6%E3%81%A1%E3%82%83%E3%82%93+%E4%B8%AD%E6%B4%B2+%E5%B1%8B%E5%8F%B0+%E9%A4%83%E5%AD%90","kind":"map","label":"다케짱 지도"}]}]'::jsonb WHERE id = '4616d9a7-2d50-4d26-8129-762906196952'::uuid;

UPDATE public.place_reviews SET content = '
바르셀로나에서 속도를 늦추려면 고딕 지구의 돌골목과 그라시아의 광장을 하루에 나눠 쓰면 돼요. 돌벽에 스민 그늘과 잔에 닿는 햇빛이 두 동네를 잇는 기준점이에요.

이른 아침이나 해 질 무렵엔 고딕 지구 좁은 골목 사이에 숨은 **산트 펠립 네리 광장**([공식 안내](https://thisisbarcelona.com/architecture/urban-spaces-and-elements/placa-de-sant-felip-neri))부터 찾아가 보세요. 누구나 드나들 수 있는 광장으로, 나무 그늘과 돌 분수 곁에 바로크 성당이 서 있고 정면엔 1938년 폭격 자국이 그대로 남아 있어요. 옛 유대인 지구의 가장자리이고, 이 시간대엔 빛이 남다르고 고요가 거의 끊기지 않아서, 책 한 권 펴 두기 좋아요.

오후엔 그라시아로 올라가 **비야 데 그라시아 광장**([공식 안내](https://www.barcelona.cat/capitalmundialarquitectura/ca/espai/placa-de-la-vila-de-gracia))에 앉아 보세요. 1862~1864년에 세운 33m 팔각 시계탑이 한가운데 서 있고, 탑 발치엔 분수가, 한쪽엔 하늘색 파사드의 옛 구청사가 있어요. 광장 19번지의 독립 책방 **라 메모리아**([공식 사이트](https://www.llibrerialamemoria.com/))는 2013년부터 이 자리를 지켜 왔어요. 같은 동네 **비레이나 광장** 5번지의 **테라 바**([공식 사이트](https://terrabartrobada.com/))는 1996년부터 야외 테라스를 내고 있어서, 책을 옆에 두고 잔 하나로 오후를 늘이기 좋아요.

아쉬운 점은 산트 펠립 네리 광장이 좁은 골목 사이에 숨어 있어서, 처음엔 방향을 몇 번 다시 잡아야 할 수 있다는 거예요.

분수 곁 아침 고요에서 시계탑 아래 오후 테라스까지, 바르셀로나를 두 광장의 속도로 걷는 하루예요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
