UPDATE public.place_reviews SET content = '
벨빌·메닐몽탕에 하루를 맡긴다면 무대는 불바르 드 벨빌의 장날, 그리고 그 위 언덕의 **벨빌 공원**이에요. 장보기와 출근, 공원 산책이 한 동네 안에서 시간대별로 차례차례 바뀌어요.

아침은 **마르셰 벨빌**([공식 안내](https://www.paris.fr/lieux/marche-belleville-5475))부터예요. 화·금요일 07:00~13:30에 불바르 드 벨빌 중앙 분리대 위에 장이 서요. 메트로 Belleville·Couronnes역 가까이 가판이 늘어서서, 출근길과 장바구니 동선이 겹치는 이른 시간이 이 동네다운 장면이에요. 같은 요일, 이어지는 불바르 드 메닐몽탕에도 **마르셰 메닐몽탕**([공식 안내](https://www.paris.fr/lieux/marche-menilmontant-5478))이 07:00~13:30 서요. 목·일요일이라면 20구 뤼 데 피레네의 **마르셰 피레네**([공식 안내](https://www.paris.fr/lieux/marche-pyrenees-5533))로 옮기면 돼요(목 07:00~13:30, 일 07:00~14:30). 점심은 장 주변 동네 빵집이나 식당에서 가볍게 고르면 돼요.

오후는 뤼 데 쿠론 쪽 입구로 벨빌 공원([공식 안내](https://www.paris.fr/lieux/parc-de-belleville-1777)) 언덕을 올라가 보세요. 여는 시각과 닫는 시각은 계절마다 달라요. 꼭대기 **벨베데르 윌리 로니스**에서 파리 전경이 트이고, 비탈엔 1992년에 다시 심은 포도밭이 있어요. 해가 기울면 뤼 피아 쪽으로 내려와 동네 저녁으로 이어 가면 돼요. 아쉬운 점은 벨빌 대로의 큰 장이 화·금요일 오전뿐이라, 다른 요일엔 아침 무대가 작아진다는 거예요.

화·금요일 장날 아침부터 언덕 공원 해 질 녘까지, 벨빌 한 동네에 하루를 맡기고 싶을 때 추천해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"벨빌·메닐몽탕에 하루를 맡긴다면 무대는 불바르 드 벨빌의 장날, 그리고 그 위 언덕의 **벨빌 공원**이에요. 장보기와 출근, 공원 산책이 한 동네 안에서 시간대별로 차례차례 바뀌어요.\n\n아침은 **마르셰 벨빌**([공식 안내](https://www.paris.fr/lieux/marche-belleville-5475))부터예요. 화·금요일 07:00~13:30에 불바르 드 벨빌 중앙 분리대 위에 장이 서요. 메트로 Belleville·Couronnes역 가까이 가판이 늘어서서, 출근길과 장바구니 동선이 겹치는 이른 시간이 이 동네다운 장면이에요. 같은 요일, 이어지는 불바르 드 메닐몽탕에도 **마르셰 메닐몽탕**([공식 안내](https://www.paris.fr/lieux/marche-menilmontant-5478))이 07:00~13:30 서요. 목·일요일이라면 20구 뤼 데 피레네의 **마르셰 피레네**([공식 안내](https://www.paris.fr/lieux/marche-pyrenees-5533))로 옮기면 돼요(목 07:00~13:30, 일 07:00~14:30). 점심은 장 주변 동네 빵집이나 식당에서 가볍게 고르면 돼요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"오후는 뤼 데 쿠론 쪽 입구로 벨빌 공원([공식 안내](https://www.paris.fr/lieux/parc-de-belleville-1777)) 언덕을 올라가 보세요. 여는 시각과 닫는 시각은 계절마다 달라요. 꼭대기 **벨베데르 윌리 로니스**에서 파리 전경이 트이고, 비탈엔 1992년에 다시 심은 포도밭이 있어요. 해가 기울면 뤼 피아 쪽으로 내려와 동네 저녁으로 이어 가면 돼요. 아쉬운 점은 벨빌 대로의 큰 장이 화·금요일 오전뿐이라, 다른 요일엔 아침 무대가 작아진다는 거예요.\n\n화·금요일 장날 아침부터 언덕 공원 해 질 녘까지, 벨빌 한 동네에 하루를 맡기고 싶을 때 추천해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=March%C3%A9+Belleville+Paris","kind":"map","label":"마르셰 벨빌 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=March%C3%A9+M%C3%A9nilmontant+Paris","kind":"map","label":"마르셰 메닐몽탕 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=March%C3%A9+Pyr%C3%A9n%C3%A9es+Paris+20e","kind":"map","label":"마르셰 피레네 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Parc+de+Belleville+Paris","kind":"map","label":"벨빌 공원 지도"}]}]'::jsonb WHERE id = '57649f3d-550c-400c-b616-cd28dc7359af'::uuid;

UPDATE public.place_reviews SET content = '

해 진 뒤 **브래드필드 파크**([공식 사이트](https://www.northsydney.nsw.gov.au/directory-record/1385/bradfield-park))를 한 촬영 거점으로 잡아요. **시드니 하버 브리지** 아래로 공원이 이어지고, 물 건너 **시드니 오페라하우스**가 보여요. 다리의 큰 구조를 위쪽에, 수면을 아래쪽에 두면 항구의 깊이를 담기 좋아요.


한 자리에서 넓은 하버 전경을 먼저 담고, 다음 컷은 오페라하우스 지붕 쪽으로 좁혀요. 밝은 지붕과 어두운 물의 대비를 살리는 구도예요. 수면을 넉넉히 남기는 컷도 함께 구성해요.


귀가는 **밀슨스 포인트 선착장**에서 **서큘러 키**행 F4 페리로 묶어요. 시각은 모두 시드니 현지 시각이에요. 2026년 6월 14일부터 적용되는 [공식 시간표](https://transportnsw.info/documents/timetables/93-F4-Pyrmont-Bay-20260614.pdf)의 월~금요일·공휴일 제외 편성에서, 이 방향 F4 마지막 배는 23:30 출발해 23:37 도착해요. 막차보다 앞선 22:30편은 22:37에 닿아요. 촬영을 이 배에 맞춰 끝내는 동선으로 추천해요.

정보 확인일 2026-11-08 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"해 진 뒤 **브래드필드 파크**([공식 사이트](https://www.northsydney.nsw.gov.au/directory-record/1385/bradfield-park))를 한 촬영 거점으로 잡아요. **시드니 하버 브리지** 아래로 공원이 이어지고, 물 건너 **시드니 오페라하우스**가 보여요. 다리의 큰 구조를 위쪽에, 수면을 아래쪽에 두면 항구의 깊이를 담기 좋아요.\n\n\n한 자리에서 넓은 하버 전경을 먼저 담고, 다음 컷은 오페라하우스 지붕 쪽으로 좁혀요. 밝은 지붕과 어두운 물의 대비를 살리는 구도예요. 수면을 넉넉히 남기는 컷도 함께 구성해요.\n\n\n귀가는 **밀슨스 포인트 선착장**에서 **서큘러 키**행 F4 페리로 묶어요. 시각은 모두 시드니 현지 시각이에요. 2026년 6월 14일부터 적용되는 [공식 시간표](https://transportnsw.info/documents/timetables/93-F4-Pyrmont-Bay-20260614.pdf)의 월~금요일·공휴일 제외 편성에서, 이 방향 F4 마지막 배는 23:30 출발해 23:37 도착해요. 막차보다 앞선 22:30편은 22:37에 닿아요. 촬영을 이 배에 맞춰 끝내는 동선으로 추천해요.\n\n정보 확인일 2026-11-08 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Bradfield+Park+Milsons+Point+NSW+Australia","kind":"map","label":"브래드필드 파크 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Sydney+Harbour+Bridge+Sydney+NSW+Australia","kind":"map","label":"시드니 하버 브리지 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Sydney+Opera+House+Bennelong+Point+NSW+Australia","kind":"map","label":"시드니 오페라하우스 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Milsons+Point+Wharf+NSW+Australia","kind":"map","label":"밀슨스 포인트 선착장 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Circular+Quay+Wharf+Sydney+NSW+Australia","kind":"map","label":"서큘러 키 지도"}]}]'::jsonb WHERE id = '5b4c6c81-147a-4e06-a18a-35b3368f4f35'::uuid;

UPDATE public.place_reviews SET content = '
**반남켐 쓰나미 추모공원**(Ban Nam Khem Tsunami Memorial Park, [추모공원 안내](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342))은 따꾸아빠 지구에서 약 7km 떨어진 어촌 해안에 있어요. 08:00~20:00에 열고, 공원 안 춤폰 왕자상과 불상 앞에서 어부들이 출항 전마다 안전을 빌어요. 해변을 따라 어촌 마을과 동네 식당이 이어지고, 현지 가족이 소풍을 오는 곳이기도 해요.

2004년 쓰나미 뒤 일부 주민은 다시 어업으로 돌아갔고, 다른 이들은 새 생업을 찾았어요. 왓 남켐과 마을 학교는 대피 안전지대로 정해져 있고, 대피 훈련은 정기적으로 열려요([정부 공보](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342)). 이 마을에서 바다는 일터이고, 대비는 일상이에요.

**따꾸아빠 올드타운**(Takua Pa Old Town, [올드타운 안내](https://www.thailandgoodtravel.info/?locale=en))은 주석 채굴과 무역으로 외국 상인이 모이던 일터 도시예요. 중국인 이주민은 고무 농장과 주석 광산에서 일하며 터를 잡았고, 시노-포르투갈풍 건물은 지금 카페와 잡화점이 됐어요. 시립 식품시장은 끌룬깨우와 몬뜨리 2 도로 모퉁이에 있고, 생선알 팬케이크와 미앙라오, 팥 크레이프 같은 동네 먹거리가 나와요.

월·수·목·토 14:00~22:00에는 **방니앙 시장**(Bang Niang Market, [공식 페이지](https://bangniangmarket.com/))이 카오락 한가운데에 서요. 17년 넘게 이어 온 장이고, 상인이 300곳을 넘어요. 농산물 구역에서 태국 과일과 채소를 팔고, 길거리 음식 구역에서 꼬치와 스프링롤, 해산물이 나와요. 장날은 이른 저녁이 가장 활기가 돌아요.

정보 확인일 2026-11-18 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**반남켐 쓰나미 추모공원**(Ban Nam Khem Tsunami Memorial Park, [추모공원 안내](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342))은 따꾸아빠 지구에서 약 7km 떨어진 어촌 해안에 있어요. 08:00~20:00에 열고, 공원 안 춤폰 왕자상과 불상 앞에서 어부들이 출항 전마다 안전을 빌어요. 해변을 따라 어촌 마을과 동네 식당이 이어지고, 현지 가족이 소풍을 오는 곳이기도 해요.\n\n2004년 쓰나미 뒤 일부 주민은 다시 어업으로 돌아갔고, 다른 이들은 새 생업을 찾았어요. 왓 남켐과 마을 학교는 대피 안전지대로 정해져 있고, 대피 훈련은 정기적으로 열려요([정부 공보](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342)). 이 마을에서 바다는 일터이고, 대비는 일상이에요.\n\n**따꾸아빠 올드타운**(Takua Pa Old Town, [올드타운 안내](https://www.thailandgoodtravel.info/?locale=en))은 주석 채굴과 무역으로 외국 상인이 모이던 일터 도시예요. 중국인 이주민은 고무 농장과 주석 광산에서 일하며 터를 잡았고, 시노-포르투갈풍 건물은 지금 카페와 잡화점이 됐어요. 시립 식품시장은 끌룬깨우와 몬뜨리 2 도로 모퉁이에 있고, 생선알 팬케이크와 미앙라오, 팥 크레이프 같은 동네 먹거리가 나와요.\n\n월·수·목·토 14:00~22:00에는 **방니앙 시장**(Bang Niang Market, [공식 페이지](https://bangniangmarket.com/))이 카오락 한가운데에 서요. 17년 넘게 이어 온 장이고, 상인이 300곳을 넘어요. 농산물 구역에서 태국 과일과 채소를 팔고, 길거리 음식 구역에서 꼬치와 스프링롤, 해산물이 나와요. 장날은 이른 저녁이 가장 활기가 돌아요.\n\n정보 확인일 2026-11-18 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Ban%20Nam%20Khem%20Tsunami%20Memorial%20Park%2C%20Bang%20Muang%2C%20Takua%20Pa%2C%20Phang%20Nga","kind":"map","label":"반남켐 쓰나미 추모공원 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Takua%20Pa%20Old%20Town%2C%20Takua%20Pa%2C%20Phang%20Nga","kind":"map","label":"따꾸아빠 올드타운 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Bang%20Niang%20Market%2C%20Khao%20Lak%2C%20Phang%20Nga","kind":"map","label":"방니앙 시장 지도"}]}]'::jsonb WHERE id = '5d40e738-6d2b-4ec7-8a1a-5b40517023fc'::uuid;

UPDATE public.place_reviews SET content = '
**방삭 해변**(Bang Sak Beach)과 **팍윕 해변**(Pak Weep Beach)은 카오락에서 한적한 쪽 해안이에요. 모래 위에 자리를 잡고 책을 펴 보세요. 물가를 느린 걸음으로 걷다가, 해가 기우는 때에 수평선 쪽으로 자리를 옮겨 앉아도 좋아요([관광청 안내](https://news.cision.com/tourism-authority-of-thailand/r/7-best-things-to-do-in-khao-lak,c3416503)).

카오락-람루 국립공원 안에는 카오락에서 약 9km 떨어진 **똔총파 폭포**(Ton Chong Fa Waterfall)가 있어요. 다섯 단으로 바위를 타고 내려온 물이 큰 웅덩이에 고여요. 입구에서 폭포까지 길이 비교적 쉬워서 서두를 이유가 없어요. 웅덩이 곁 바위에 앉아 물소리를 오래 들어 보세요. 오른쪽 윗단 길은 좁고 가파르고 미끄러워 아래에서 머물러도 충분해요([폭포 안내](https://news.cision.com/tourism-authority-of-thailand/r/7-best-things-to-do-in-khao-lak,c3416503)).

카오락에서 약 40분 거리의 **반남켐 쓰나미 추모공원**(Ban Nam Khem Tsunami Memorial Park)에는 파도 모양으로 휜 콘크리트 벽이 옛 어선과 마주 서 있어요. 흙벽을 따라 1,400명이 넘는 이름이 새겨진 길이 이어져요. 말을 아끼고 걸음을 한 칸씩 늦춰 이름 앞을 지나 보세요. 공원과 해변은 08:00~20:00, 박물관은 수~일 08:30~16:30에 열어요([추모공원 안내](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342)).

**따꾸아빠 올드타운**(Takua Pa Old Town)에는 시노-포르투갈풍 건물이 줄지어 서 있고 벽에 거리 그림이 많이 그려져 있어요. 그림 하나 앞에서 한참 서 있다가 다음 골목은 천천히 걸어 보세요. 카페로 쓰는 건물에 들어가 잠시 앉아 쉬어도 좋아요([올드타운 안내](https://www.thailandgoodtravel.info/?locale=en)).

정보 확인일 2026-11-18 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**방삭 해변**(Bang Sak Beach)과 **팍윕 해변**(Pak Weep Beach)은 카오락에서 한적한 쪽 해안이에요. 모래 위에 자리를 잡고 책을 펴 보세요. 물가를 느린 걸음으로 걷다가, 해가 기우는 때에 수평선 쪽으로 자리를 옮겨 앉아도 좋아요([관광청 안내](https://news.cision.com/tourism-authority-of-thailand/r/7-best-things-to-do-in-khao-lak,c3416503)).\n\n카오락-람루 국립공원 안에는 카오락에서 약 9km 떨어진 **똔총파 폭포**(Ton Chong Fa Waterfall)가 있어요. 다섯 단으로 바위를 타고 내려온 물이 큰 웅덩이에 고여요. 입구에서 폭포까지 길이 비교적 쉬워서 서두를 이유가 없어요. 웅덩이 곁 바위에 앉아 물소리를 오래 들어 보세요. 오른쪽 윗단 길은 좁고 가파르고 미끄러워 아래에서 머물러도 충분해요([폭포 안내](https://news.cision.com/tourism-authority-of-thailand/r/7-best-things-to-do-in-khao-lak,c3416503)).\n\n카오락에서 약 40분 거리의 **반남켐 쓰나미 추모공원**(Ban Nam Khem Tsunami Memorial Park)에는 파도 모양으로 휜 콘크리트 벽이 옛 어선과 마주 서 있어요. 흙벽을 따라 1,400명이 넘는 이름이 새겨진 길이 이어져요. 말을 아끼고 걸음을 한 칸씩 늦춰 이름 앞을 지나 보세요. 공원과 해변은 08:00~20:00, 박물관은 수~일 08:30~16:30에 열어요([추모공원 안내](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342)).\n\n**따꾸아빠 올드타운**(Takua Pa Old Town)에는 시노-포르투갈풍 건물이 줄지어 서 있고 벽에 거리 그림이 많이 그려져 있어요. 그림 하나 앞에서 한참 서 있다가 다음 골목은 천천히 걸어 보세요. 카페로 쓰는 건물에 들어가 잠시 앉아 쉬어도 좋아요([올드타운 안내](https://www.thailandgoodtravel.info/?locale=en)).\n\n정보 확인일 2026-11-18 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Bang%20Sak%20Beach%2C%20Takua%20Pa%2C%20Phang%20Nga","kind":"map","label":"방삭·팍윕 해변 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Ton%20Chong%20Fa%20Waterfall%2C%20Khao%20Lak-Lam%20Ru%20National%20Park%2C%20Phang%20Nga","kind":"map","label":"똔총파 폭포 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Ban%20Nam%20Khem%20Tsunami%20Memorial%20Park%2C%20Bang%20Muang%2C%20Takua%20Pa%2C%20Phang%20Nga","kind":"map","label":"반남켐 쓰나미 추모공원 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Takua%20Pa%20Old%20Town%2C%20Takua%20Pa%2C%20Phang%20Nga","kind":"map","label":"따꾸아빠 올드타운 지도"}]}]'::jsonb WHERE id = '5f9cc144-1af2-432f-8dc9-05353bfb8bd8'::uuid;

UPDATE public.place_reviews SET content = '
무릎이 불편한 부모님과 비탈 위 절까지 갈 수 있을까, 이 고민은 **기요미즈데라**([공식 사이트](https://www.kiyomizudera.or.jp/))에서 들어가는 길을 고르면 풀려요. 경내로 가는 길은 기요미즈자카를 올라 니오몬 앞으로 가는 길과 자완자카(茶わん坂)를 올라 방재도로로 가는 길, 두 가지뿐이에요. 지도 앱이 못 들어가는 길을 안내하기도 해서, 이 두 길만 기억해 두면 헤매지 않아요.

정면으로 걸어 들어간다면 참배 순로 바로 왼쪽에 본당까지 단차 없이 이어지는 길이 있어요. 휠체어를 챙겨 간다면 방재도로 입구로 차량이 들어가 본당 가까이까지 안내받고, 그다음은 단차 없는 순로로 경내를 한 바퀴 돌 수 있어요. 절에는 휠체어 대여가 없어서 필요하면 따로 준비해 가요. 정면 문전 거리는 8:00~19:00 차량이 다닐 수 없어요.

본당 입구 도도로키몬에서 경내 지도를 나눠 주고, 장애인 대응 화장실이 경내 여러 곳에 있어요. 방재도로로 들어서면 바로 오른쪽에 화장실이 있어서, 오르기 전에 여기서 한 번 끊어 가면 좋아요.

이동은 토·휴일이면 교토역에서 **관광특급버스**([공식 안내](https://www2.city.kyoto.lg.jp/kotsu/webguide/ja/bus/limited_express.html)) EX100·EX101로 고조자카 정류장까지 12분이에요. 오전엔 약 7~8분 간격으로 다니고, 성인 요금은 500엔이에요. 다른 날엔 시버스 206·100계통으로 고조자카에서 내려 걸어서 약 10분이에요. 문은 6:00에 열고, 11월 20일까지는 18:00에 닫아요.

비탈 걱정에 기요미즈데라를 빼려던 가족이라면, 들어가는 길부터 정하는 일정으로 추천해요.

정보 확인일 2026-10-19 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
