UPDATE public.place_reviews SET content = '
휠체어로 파리 시내를 다닌다면 버스가 축이에요. 파리 시내 버스는 전 노선이 휠체어 접근 노선이고, 중앙 문에서 경사판이 나와요. 차 안에는 손잡이와 하차 버튼이 있는 휠체어 자리가 있어요. 접근 노선이어도 일부 정류장은 노선도에 접근 불가로 표시돼 있어요. 73번 버스는 RATP 공식 시간표에 **오르세 미술관** 방면이 있고, 69번도 이 미술관을 지나가요.

입구는 단차가 없고 자동문이 있어요. 장애가 있는 방문객과 동행 1명은 증명서를 보여 주면 무료이고, 우선 입장이에요. 관내는 휠체어로 이용할 수 있고, 손잡이와 시각·음성 안내가 있는 엘리베이터가 있어요. 가장 좁은 통로 폭은 120cm, 문은 90cm예요. 접근 가능한 화장실이 있어요. 휠체어와 접이식 의자를 빌려요. 시설 정보는 파리 관광청 접근성 안내(2022년 7월) 기준이에요. [공식 안내](https://parisjetaime.com/eng/culture/musee-d-orsay-p3592)

시내 버스로 오르세 미술관 입구와 관내 이동을 준비하는, 이동이 불편하거나 느리게 다니는 여행자에게 맞아요.

정보 확인일 2026-11-21 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"휠체어로 파리 시내를 다닌다면 버스가 축이에요. 파리 시내 버스는 전 노선이 휠체어 접근 노선이고, 중앙 문에서 경사판이 나와요. 차 안에는 손잡이와 하차 버튼이 있는 휠체어 자리가 있어요. 접근 노선이어도 일부 정류장은 노선도에 접근 불가로 표시돼 있어요. 73번 버스는 RATP 공식 시간표에 **오르세 미술관** 방면이 있고, 69번도 이 미술관을 지나가요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"입구는 단차가 없고 자동문이 있어요. 장애가 있는 방문객과 동행 1명은 증명서를 보여 주면 무료이고, 우선 입장이에요. 관내는 휠체어로 이용할 수 있고, 손잡이와 시각·음성 안내가 있는 엘리베이터가 있어요. 가장 좁은 통로 폭은 120cm, 문은 90cm예요. 접근 가능한 화장실이 있어요. 휠체어와 접이식 의자를 빌려요. 시설 정보는 파리 관광청 접근성 안내(2022년 7월) 기준이에요. [공식 안내](https://parisjetaime.com/eng/culture/musee-d-orsay-p3592)\n\n","type":"text"},{"type":"image","image_index":1},{"text":"시내 버스로 오르세 미술관 입구와 관내 이동을 준비하는, 이동이 불편하거나 느리게 다니는 여행자에게 맞아요.\n\n정보 확인일 2026-11-21 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Mus%C3%A9e+d%27Orsay+Paris","kind":"map","label":"오르세 미술관 지도"},{"url":"https://www.gateo.kr/place/paris?open=tour&from=review","kind":"official","label":"투어 찾기"}]}]'::jsonb WHERE id = '62190bb0-b77d-4485-9e83-98ec5e3d85f6'::uuid;

UPDATE public.place_reviews SET content = '
1930년 무렵 무도회장 열일곱 곳이 들어섰던 바스티유 뒤 **rue de Lappe**는 파리 동쪽 밤의 출발선이에요. 9번지 **Le Balajo**(1936년~, [공식 사이트](https://www.balajo.fr/le-balajo))가 금·토 23:00부터 07:00까지 힙합·아프로비트 클럽 나이트를 열고, 옷 보관은 필수예요.

오베르캄프는 rue Oberkampf·Jean-Pierre Timbaud·Parmentier에 카페·공연장·클럽이 모여 저녁이면 보도까지 사람이 몰려요. 109번지 **Charbon**은 금·토 05:00, 다른 날 02:00까지 열고 저녁 자리는 [온라인 예약](https://www.lecafecharbon.fr/)이나 [전화](tel:+33143575513)로 잡아요. 같은 번지 **Nouveau Casino**는 공연 뒤 자정~06:00 클럽 나이트가 붙는 주말이 많고, 티켓은 [공식 일정표](https://www.nouveaucasino.fr/)의 일정별 링크로 사요.

몸풀기는 7층 루프톱 **Le Perchoir Ménilmontant**이 좋아요. 바는 평일 18:00, 주말 16:00에 열어 02:00(일요일 자정)까지 가고, [온라인 예약](https://leperchoir.fr/location/le-perchoir-menilmontant/)은 3주 전에 열려요.

자정을 넘기면 입구 줄과 보도 인파가 두꺼워지니 지갑·휴대폰은 앞으로 챙겨요. 메트로는 금·토 02:15, 다른 날 01:15 무렵 끊기고, 이후엔 Noctilien 심야버스가 05:30까지 달려요. 즐기려면 루프톱 해넘이 → Charbon 저녁 → 자정 클럽 순서로 내려와요. 피하려면 rue de Lappe·rue Oberkampf 한복판의 금·토 자정 전후는 비우고 평일 초저녁 한 잔으로 끝내요.

아코디언 무도회장 골목에서 새벽 클럽까지, 파리 밤을 끝까지 타고 싶을 때 권해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"1930년 무렵 무도회장 열일곱 곳이 들어섰던 바스티유 뒤 **rue de Lappe**는 파리 동쪽 밤의 출발선이에요. 9번지 **Le Balajo**(1936년~, [공식 사이트](https://www.balajo.fr/le-balajo))가 금·토 23:00부터 07:00까지 힙합·아프로비트 클럽 나이트를 열고, 옷 보관은 필수예요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"오베르캄프는 rue Oberkampf·Jean-Pierre Timbaud·Parmentier에 카페·공연장·클럽이 모여 저녁이면 보도까지 사람이 몰려요. 109번지 **Charbon**은 금·토 05:00, 다른 날 02:00까지 열고 저녁 자리는 [온라인 예약](https://www.lecafecharbon.fr/)이나 [전화](tel:+33143575513)로 잡아요. 같은 번지 **Nouveau Casino**는 공연 뒤 자정~06:00 클럽 나이트가 붙는 주말이 많고, 티켓은 [공식 일정표](https://www.nouveaucasino.fr/)의 일정별 링크로 사요.\n\n","type":"text"},{"type":"image","image_index":1},{"text":"몸풀기는 7층 루프톱 **Le Perchoir Ménilmontant**이 좋아요. 바는 평일 18:00, 주말 16:00에 열어 02:00(일요일 자정)까지 가고, [온라인 예약](https://leperchoir.fr/location/le-perchoir-menilmontant/)은 3주 전에 열려요.\n\n자정을 넘기면 입구 줄과 보도 인파가 두꺼워지니 지갑·휴대폰은 앞으로 챙겨요. 메트로는 금·토 02:15, 다른 날 01:15 무렵 끊기고, 이후엔 Noctilien 심야버스가 05:30까지 달려요. 즐기려면 루프톱 해넘이 → Charbon 저녁 → 자정 클럽 순서로 내려와요. 피하려면 rue de Lappe·rue Oberkampf 한복판의 금·토 자정 전후는 비우고 평일 초저녁 한 잔으로 끝내요.\n\n아코디언 무도회장 골목에서 새벽 클럽까지, 파리 밤을 끝까지 타고 싶을 때 권해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Le+Balajo+9+rue+de+Lappe+Paris","kind":"map","label":"Le Balajo 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Caf%C3%A9+Charbon+109+rue+Oberkampf+Paris","kind":"map","label":"Charbon 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Nouveau+Casino+109+rue+Oberkampf+Paris","kind":"map","label":"Nouveau Casino 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Le+Perchoir+M%C3%A9nilmontant+14+rue+Crespin+du+Gast+Paris","kind":"map","label":"Le Perchoir Ménilmontant 지도"}]}]'::jsonb WHERE id = '669c2eea-23fa-4929-84d9-6a715d256574'::uuid;

UPDATE public.place_reviews SET content = '
나라 공원은 북쪽에서 남쪽으로 한 번만 지나가게 잡으면 되돌아오는 걸음이 없어요. 출발은 **요시키엔(吉城園)**이에요. 연못 정원, 이끼 정원, 다화(茶花) 정원으로 나뉘고 입장은 무료예요. 9:00~17:00에 열고 입장은 16:30까지, 2월 24~28일은 쉬어요([공식 안내](https://www.pref.nara.lg.jp/n113/39910.html)).

이끼 정원에서 숨을 고른 뒤 남쪽으로 내려가요. 가스가 참배길 남쪽 구릉이 **아사지가하라(浅茅ヶ原)**예요. 땅의 높낮이가 이어지는 조용한 숲이고, 쉼터 가와마타테이(川股亭)가 있어요([공원 안내](https://www.pref.nara.lg.jp/site/park/2590.html)).

숲을 빠져나오면 사기이케(鷺池) 연못 위 육각당 **우키미도(浮見堂)**가 나와요. 관람은 자유이고, 해가 지면 22:00까지 불을 밝혀요. 일몰 시각은 계절마다 달라요([관광 안내](https://yamatoji.nara-kankou.or.jp/02nature/07park/01north_area/ukimido/)). 물에 비친 당을 보며 오래 머물러도 괜찮아요.

사슴은 사람에게 익숙해도 야생동물이에요. 가을엔 수사슴이 발정기라 더 예민해요. 시카센베이 말고는 아무것도 주지 않고, 지도나 비닐봉지도 먹으니 짐을 꼭 쥐어요. 공원에는 쓰레기통이 없어서 쓰레기는 가지고 돌아가요([사슴 안내](https://www.pref.nara.lg.jp/site/park/1232.html)).

마지막엔 가스가타이샤오모테산도(春日大社表参道) 정류장까지 걸어서 5분쯤, 긴테쓰나라역까지는 걸어서 20분쯤이에요.

정보 확인일 2026-11-09 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
