UPDATE public.place_reviews SET content = '
베를린 테크노 문화는 2024년 독일 무형문화유산 국가 목록에 올랐어요([공식 안내](https://www.unesco.de/staette/technokultur-in-berlin/)). 클럽 행사가 한 해 5만 8천 건쯤 열리고, 금요일 밤에 시작한 파티가 월요일 아침까지 이어지기도 해요([관광청 안내](https://www.visitberlin.de/en/clubs-berlin)).

한 축만 고르면 프리드리히스하인의 **바르샤우어 슈트라세**예요. 이 거리 S반 고가 아치 바로 아래에 **매트릭스**가 있어요. 5개 층에 최대 2,500명이 들어가고 1년 365일 문을 열어서 평일 밤에도 파티를 이어 갈 수 있어요([공식 안내](https://www.visitberlin.de/en/matrix)).

역에서 몇 분 걸으면 레발러 슈트라세의 **RAW 부지**예요. 콘서트홀 **아스트라 쿨투어하우스**와 클럽·야외 바가 한데 모여 있어요. 공연·파티는 [행사 일정](https://raw-gelaende.de/)에 날짜별로 올라오고, 아스트라 인기 공연은 표가 빨리 팔려요([공식 안내](https://www.visitberlin.de/en/astra-kulturhaus)).

즐기려면 금·토 밤에 잡아요. 금→토, 토→일 밤과 공휴일 전날 밤에는 U반이 15분, S반이 30분 간격으로 밤새 다녀요([심야 교통](https://www.berlin.de/en/public-transportation/1859225-2913840-night-buses-public-transport-at-night.en.html)). 바르샤우어 슈트라세역에는 U1·U3과 S3·S5·S7·S9가 서요. 아쉬운 점은 평일 밤이에요. U반·S반이 1시~1시 30분쯤 끊겨서, 그 뒤 귀가는 N 야간버스로 바꿔 타야 해요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"베를린 테크노 문화는 2024년 독일 무형문화유산 국가 목록에 올랐어요([공식 안내](https://www.unesco.de/staette/technokultur-in-berlin/)). 클럽 행사가 한 해 5만 8천 건쯤 열리고, 금요일 밤에 시작한 파티가 월요일 아침까지 이어지기도 해요([관광청 안내](https://www.visitberlin.de/en/clubs-berlin)).\n\n한 축만 고르면 프리드리히스하인의 **바르샤우어 슈트라세**예요. 이 거리 S반 고가 아치 바로 아래에 **매트릭스**가 있어요. 5개 층에 최대 2,500명이 들어가고 1년 365일 문을 열어서 평일 밤에도 파티를 이어 갈 수 있어요([공식 안내](https://www.visitberlin.de/en/matrix)).\n\n역에서 몇 분 걸으면 레발러 슈트라세의 **RAW 부지**예요. 콘서트홀 **아스트라 쿨투어하우스**와 클럽·야외 바가 한데 모여 있어요. 공연·파티는 [행사 일정](https://raw-gelaende.de/)에 날짜별로 올라오고, 아스트라 인기 공연은 표가 빨리 팔려요([공식 안내](https://www.visitberlin.de/en/astra-kulturhaus)).\n\n즐기려면 금·토 밤에 잡아요. 금→토, 토→일 밤과 공휴일 전날 밤에는 U반이 15분, S반이 30분 간격으로 밤새 다녀요([심야 교통](https://www.berlin.de/en/public-transportation/1859225-2913840-night-buses-public-transport-at-night.en.html)). 바르샤우어 슈트라세역에는 U1·U3과 S3·S5·S7·S9가 서요. 아쉬운 점은 평일 밤이에요. U반·S반이 1시~1시 30분쯤 끊겨서, 그 뒤 귀가는 N 야간버스로 바꿔 타야 해요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=S%2BU%20Warschauer%20Stra%C3%9Fe%20Berlin","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=Matrix%20Warschauer%20Platz%2018%2010245%20Berlin","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=RAW-Gel%C3%A4nde%20Revaler%20Stra%C3%9Fe%2099%20Berlin","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=Astra%20Kulturhaus%20Revaler%20Stra%C3%9Fe%2099%20Berlin","kind":"map","label":"지도에서 보기"}]}]'::jsonb WHERE id = '7315cf26-78f3-4c92-9ee7-ac5dc9c15b24'::uuid;

UPDATE public.place_reviews SET content = '
후에의 **동바 시장**(Chợ Đông Ba, [공식 페이지](https://vietnamtourism.vn/index.php/tourism/items/491))은 향강(Perfume River) 북쪽 기슭, 쩐흥다오(Trần Hưng Đạo) 거리에 있어요. 쯔엉띠엔(Trường Tiền) 다리에서 북쪽으로 약 100m라, 다리를 건너 곧바로 이어 보세요. 중부에서 가장 큰 시장이에요.

안에서는 푸깜(Phú Cam)의 논라와 함께, 껌언(cơm hến), 분보, 반콰이 같은 후에 음식을 만나는 자리이기도 해요. 시장과 다리, 강이 함께 후에의 상징으로 여겨지니, 장을 본 뒤에는 같은 강변으로 돌아가 보세요. 설(Tet) 무렵에는 장이 더 바빠지니, 여유 있게 시간을 잡아 보세요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"후에의 **동바 시장**(Chợ Đông Ba, [공식 페이지](https://vietnamtourism.vn/index.php/tourism/items/491))은 향강(Perfume River) 북쪽 기슭, 쩐흥다오(Trần Hưng Đạo) 거리에 있어요. 쯔엉띠엔(Trường Tiền) 다리에서 북쪽으로 약 100m라, 다리를 건너 곧바로 이어 보세요. 중부에서 가장 큰 시장이에요.\n\n안에서는 푸깜(Phú Cam)의 논라와 함께, 껌언(cơm hến), 분보, 반콰이 같은 후에 음식을 만나는 자리이기도 해요. 시장과 다리, 강이 함께 후에의 상징으로 여겨지니, 장을 본 뒤에는 같은 강변으로 돌아가 보세요. 설(Tet) 무렵에는 장이 더 바빠지니, 여유 있게 시간을 잡아 보세요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Dong+Ba+Market+Hue","kind":"map","label":"동바 시장 지도"}]}]'::jsonb WHERE id = '7c31a683-e627-4b7a-8ad1-99b21e10273e'::uuid;

UPDATE public.place_reviews SET content = '
해 질 녘 첫 자리는 **갈라타 다리**로 잡아요. [금각만을 가로질러 베요글루와 파티흐의 에미뇌뉘를 잇고, 지금 다리는 1994년에 지은 다섯 번째 다리예요. 다리를 건너며 금각만 양쪽 스카이라인과 오가는 배를 한 화면에 담을 수 있어요. 낮과 밤 모두 낚시하는 사람들이 어깨를 맞대고 늘어서 있어요.](https://goturkiye.com/istanbul/old-galata-bridge) [금각만과 보스포루스 너머로 해가 지는 풍경을 함께 볼 수 있어요.](https://goturkiye.com/istanbul/golden-horn) 수면 반사를 아래쪽에 남기고, 사람이 적은 틈을 찾아 구도를 짜요.

귀가는 다리 바로 옆 에미뇌뉘에서 위스퀴다르로 가는 [시히르 하틀라르 페리](https://sehirhatlari.istanbul/tr/seferler/ic-hatlar/istanbul-ici-hatlar/uskudar-karakoy-eminonu-164)로 묶어요. 보스포루스를 가로지르며 양안 불빛을 마지막 컷으로 남기기 좋아요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

