UPDATE public.place_reviews SET content = '
레알에는 1730년에 문을 연 파티스리와 새벽 5시까지 문을 여는 브라스리가 걸어서 몇 분 거리에 있어요. 오후의 디저트와 한밤의 양파 수프를 한 동네에서 고를 수 있다는 뜻이에요.

낮에는 **몽토르괴유 거리** 51번지 **스토레**(Stohrer, [공식 사이트](https://stohrer.fr/))부터 들러요. 파리에서 가장 오래된 파티스리로, 월~토 08:00~20:30, 일 08:00~20:00 열어요. 창업자 니콜라 스토레가 만든 바바 오 럼과 퓌 다무르가 대표로 나와요. 진열장에서 골라 포장해 가기 좋아요.

저녁과 밤은 코키예르 거리 6번지 **오 피에 드 코숑**(Au Pied de Cochon)이 맡아요. 매일 08:00~05:00 쉬지 않고 열고, 예약은 [공식 사이트](https://www.pieddecochon.com/)에서 온라인으로 받아요. 레알식 양파 수프 그라티네와 베아르네즈 소스를 곁들인 구운 돼지 족발이 간판이에요. 실내 홀과 테라스가 있어 늦은 시간 둘이서 들르기에도 무리가 없어요. 레알 일대는 점심 12~14시에 붐비는 편이라, 밤 10시 넘어 수프 한 그릇을 두는 쪽이 오히려 여유로워요. 여행객은 **포럼 데 알** 주변에 몰리고, 몽토르괴유 안쪽으로 들어갈수록 주민 비중이 높아지는 편이에요. 단점이라면 족발 요리가 기름지고 양이 커서, 가볍게 가려면 수프 하나로 끝내는 게 나아요.

바바 한 조각으로 오후를 열고 자정 넘어 양파 수프로 닫는 레알 하루라면, 이 두 곳이면 충분해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"레알에는 1730년에 문을 연 파티스리와 새벽 5시까지 문을 여는 브라스리가 걸어서 몇 분 거리에 있어요. 오후의 디저트와 한밤의 양파 수프를 한 동네에서 고를 수 있다는 뜻이에요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"낮에는 **몽토르괴유 거리** 51번지 **스토레**(Stohrer, [공식 사이트](https://stohrer.fr/))부터 들러요. 파리에서 가장 오래된 파티스리로, 월~토 08:00~20:30, 일 08:00~20:00 열어요. 창업자 니콜라 스토레가 만든 바바 오 럼과 퓌 다무르가 대표로 나와요. 진열장에서 골라 포장해 가기 좋아요.\n\n저녁과 밤은 코키예르 거리 6번지 **오 피에 드 코숑**(Au Pied de Cochon)이 맡아요. 매일 08:00~05:00 쉬지 않고 열고, 예약은 [공식 사이트](https://www.pieddecochon.com/)에서 온라인으로 받아요. 레알식 양파 수프 그라티네와 베아르네즈 소스를 곁들인 구운 돼지 족발이 간판이에요. 실내 홀과 테라스가 있어 늦은 시간 둘이서 들르기에도 무리가 없어요. 레알 일대는 점심 12~14시에 붐비는 편이라, 밤 10시 넘어 수프 한 그릇을 두는 쪽이 오히려 여유로워요. 여행객은 **포럼 데 알** 주변에 몰리고, 몽토르괴유 안쪽으로 들어갈수록 주민 비중이 높아지는 편이에요. 단점이라면 족발 요리가 기름지고 양이 커서, 가볍게 가려면 수프 하나로 끝내는 게 나아요.\n\n바바 한 조각으로 오후를 열고 자정 넘어 양파 수프로 닫는 레알 하루라면, 이 두 곳이면 충분해요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Stohrer+51+rue+Montorgueil+Paris","kind":"map","label":"스토레 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Au+Pied+de+Cochon+6+rue+Coquilli%C3%A8re+Paris","kind":"map","label":"오 피에 드 코숑 지도"}]}]'::jsonb WHERE id = '8e4e0384-1110-453c-954a-d29dfbe121a4'::uuid;

UPDATE public.place_reviews SET content = '
**아이투타키**에선 날마다 여러 업체의 배가 라군의 모투(작은 섬)와 스노클링 지점으로 떠나요. 본섬을 큰 라군이 감싸고, 모투 15개가 흩어져 있어요. 라로통가에서 비행기로 50분이에요([관광청 안내](https://cookislands.travel/islands/aitutaki)).

에너지가 모이는 곳은 **바카 크루즈** 갑판이에요. 월~토 10시에 떠나 6시간 동안 스노클링, 배에서 굽는 생선 바비큐, 모투 들르기가 이어지고, 돌아오는 길엔 승무원이 파레우 매기와 섬 노래를 즉석에서 이끌어요([크루즈 안내](https://cookislands.travel/supplier/vaka-cruise)). 라로통가 당일 투어객도 월~토에 이 배를 타고 **원 풋 아일랜드**에 들러요([당일 투어](https://cookislands.travel/supplier/aitutaki-day-tour)). 여기선 여권에 도장을 받을 수 있어요.

속도를 원하면 남동 무역풍을 타는 카이트보딩 강습이 있어요.

밤 무대는 리조트 **아일랜드 나이트**예요. 북·노래·춤에 섬 음식이 곁들여지고, 월요일 아이투타키 라군 프라이빗 아일랜드 리조트(성인 전용), 화요일 리조트 타바에, 수·토요일 타마누 비치 리조트에서 열려요([공연표](https://cookislands.travel/experiences/arts-culture/island-nights)).

즐기려면 크루즈 날과 공연 요일을 맞춰 묵어요. 자외선 차단제, 갈아입을 가벼운 옷, 도장 받을 여권을 챙겨요. 당일 투어객을 피하려면 일요일에 **키아 오라나 크루즈**를 타요. 일~금 9~15시에 모투 여섯 곳을 돌아요([일요일 크루즈](https://cookislands.travel/supplier/kia-orana-cruise-aitutaki)).

아쉬운 점은 밤의 폭이에요. 공연표에 목·금·일 공연이 없고, 섬 춤 수업은 라로통가에서 열려요.

정보 확인일 2026-11-18 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**아이투타키**에선 날마다 여러 업체의 배가 라군의 모투(작은 섬)와 스노클링 지점으로 떠나요. 본섬을 큰 라군이 감싸고, 모투 15개가 흩어져 있어요. 라로통가에서 비행기로 50분이에요([관광청 안내](https://cookislands.travel/islands/aitutaki)).\n\n에너지가 모이는 곳은 **바카 크루즈** 갑판이에요. 월~토 10시에 떠나 6시간 동안 스노클링, 배에서 굽는 생선 바비큐, 모투 들르기가 이어지고, 돌아오는 길엔 승무원이 파레우 매기와 섬 노래를 즉석에서 이끌어요([크루즈 안내](https://cookislands.travel/supplier/vaka-cruise)). 라로통가 당일 투어객도 월~토에 이 배를 타고 **원 풋 아일랜드**에 들러요([당일 투어](https://cookislands.travel/supplier/aitutaki-day-tour)). 여기선 여권에 도장을 받을 수 있어요.\n\n속도를 원하면 남동 무역풍을 타는 카이트보딩 강습이 있어요.\n\n밤 무대는 리조트 **아일랜드 나이트**예요. 북·노래·춤에 섬 음식이 곁들여지고, 월요일 아이투타키 라군 프라이빗 아일랜드 리조트(성인 전용), 화요일 리조트 타바에, 수·토요일 타마누 비치 리조트에서 열려요([공연표](https://cookislands.travel/experiences/arts-culture/island-nights)).\n\n즐기려면 크루즈 날과 공연 요일을 맞춰 묵어요. 자외선 차단제, 갈아입을 가벼운 옷, 도장 받을 여권을 챙겨요. 당일 투어객을 피하려면 일요일에 **키아 오라나 크루즈**를 타요. 일~금 9~15시에 모투 여섯 곳을 돌아요([일요일 크루즈](https://cookislands.travel/supplier/kia-orana-cruise-aitutaki)).\n\n아쉬운 점은 밤의 폭이에요. 공연표에 목·금·일 공연이 없고, 섬 춤 수업은 라로통가에서 열려요.\n\n정보 확인일 2026-11-18 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Aitutaki%20Lagoon%20Cook%20Islands","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=One%20Foot%20Island%20Aitutaki","kind":"map","label":"지도에서 보기"},{"url":"https://www.google.com/maps/search/?api=1&query=Tamanu%20Beach%20Resort%20Aitutaki","kind":"map","label":"지도에서 보기"}]}]'::jsonb WHERE id = '91ab5557-db37-4dff-b809-60a4d7a753a6'::uuid;

UPDATE public.place_reviews SET content = '
마을과 마을을 잇는 공식 산책로 가운데 낮은 길이 **비아 델라모레(Via dell''Amore)**예요. **리오마조레**에서 **마나롤라**까지 약 1.1km, 관광 등급으로 편도 약 25분이에요. 여행객은 친퀘테레 카드와 시간대 예약이 필요하고, 길 위에서는 최대 30분 안에 지나가요([이용 안내](https://www.parconazionale5terre.it/pagina.php?id=480)).

여는 시각은 계절마다 달라요. 2026년 10월 26일부터 2027년 3월 28일까지는 매일 9:00~18:00이고, 마지막 입장은 17:30이에요. 카드와 예약은 공원 공식 페이지에서 받아요([카드·예약](https://card.parconazionale5terre.it)).

마나롤라에 내려오면 그제야 걸음을 낮출 자리가 생겨요. 같은 해안길의 마나롤라~코르닐리아 구간(592-2)은 닫혀 있어요([산책로 현황](https://www.parconazionale5terre.it/rete-sentieristica.php)).

절벽 아래 바다가 보여도, 마을 골목에서 한숨 고르는 쪽이 이 짧은 길의 나머지를 완성해요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"마을과 마을을 잇는 공식 산책로 가운데 낮은 길이 **비아 델라모레(Via dell''Amore)**예요. **리오마조레**에서 **마나롤라**까지 약 1.1km, 관광 등급으로 편도 약 25분이에요. 여행객은 친퀘테레 카드와 시간대 예약이 필요하고, 길 위에서는 최대 30분 안에 지나가요([이용 안내](https://www.parconazionale5terre.it/pagina.php?id=480)).\n\n여는 시각은 계절마다 달라요. 2026년 10월 26일부터 2027년 3월 28일까지는 매일 9:00~18:00이고, 마지막 입장은 17:30이에요. 카드와 예약은 공원 공식 페이지에서 받아요([카드·예약](https://card.parconazionale5terre.it)).\n\n마나롤라에 내려오면 그제야 걸음을 낮출 자리가 생겨요. 같은 해안길의 마나롤라~코르닐리아 구간(592-2)은 닫혀 있어요([산책로 현황](https://www.parconazionale5terre.it/rete-sentieristica.php)).\n\n절벽 아래 바다가 보여도, 마을 골목에서 한숨 고르는 쪽이 이 짧은 길의 나머지를 완성해요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Via+dell+Amore+Riomaggiore","kind":"map","label":"비아 델라모레 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Manarola+Cinque+Terre","kind":"map","label":"마나롤라 지도"}]}]'::jsonb WHERE id = '9b7bf10f-0d82-4574-81db-511a750f9ed6'::uuid;

UPDATE public.place_reviews SET content = '
메트로가 자정에 멈춰도 라파의 **Rio Scenarium**은 토요일 새벽 3시까지 문을 열어요. 저녁엔 키오스크가 늘어선 코파카바나 4km 산책로와 이파네마 Vieira Souto 쪽에 음악을 끼고 사람이 몰려요.

Rua do Lavradio 20번지 19세기 저택 Rio Scenarium([공식 사이트](https://www.rioscenarium.com.br/))은 수·목 19:00~01:00, 금 19:00~02:00, 토 20:00~03:00 열어요. 표는 Sympla [티켓 예매](https://site.bileto.sympla.com.br/rioscenarium/) 페이지에서 사고, 예약만으론 입장이 보장 안 돼요. Av. Mem de Sá 79 **Carioca da Gema**([공식 사이트](https://www.barcariocadagema.com.br/))는 화~금 19:30·토 20:30 개장, 금·토 메인 공연 22:00, 입장 30~35헤알 선이에요. **Circo Voador**는 [공식 일정표](https://www.circovoador.com.br/) 링크로 표를 팔고 매표소는 개문 2시간 전에 열어요.

215계단 **Escadaria Selarón**([공식 안내](https://visitrio.com.br/lapa-o-coracao-da-vida-noturna-do-rio/))은 밝을 때 들러요. 메트로 1·2·4호선은 월~토 05:00~24:00, 일요일·공휴일 07:00~23:00 운행하고, 환승은 종료 시각까지 환승역 승강장에 있어야 해요. Rio Scenarium이 닫을 무렵엔 메트로가 끊겨 택시·호출 앱 비용이 따로 드는 게 아쉬워요. 밤엔 외진 길을 피하고 귀중품은 두고 나와요. 즐기려면 키오스크에서 해넘이를 보고 라파 공연으로 넘어가요. 피하려면 토요일 자정 넘은 Lavradio는 건너뛰고 평일 첫 공연만 봐요.

해변 키오스크에서 새벽 삼바까지, 리우 밤을 끝까지 달리고 싶을 때 맞아요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"메트로가 자정에 멈춰도 라파의 **Rio Scenarium**은 토요일 새벽 3시까지 문을 열어요. 저녁엔 키오스크가 늘어선 코파카바나 4km 산책로와 이파네마 Vieira Souto 쪽에 음악을 끼고 사람이 몰려요.\n\n","type":"text"},{"type":"image","image_index":0},{"text":"Rua do Lavradio 20번지 19세기 저택 Rio Scenarium([공식 사이트](https://www.rioscenarium.com.br/))은 수·목 19:00~01:00, 금 19:00~02:00, 토 20:00~03:00 열어요. 표는 Sympla [티켓 예매](https://site.bileto.sympla.com.br/rioscenarium/) 페이지에서 사고, 예약만으론 입장이 보장 안 돼요. Av. Mem de Sá 79 **Carioca da Gema**([공식 사이트](https://www.barcariocadagema.com.br/))는 화~금 19:30·토 20:30 개장, 금·토 메인 공연 22:00, 입장 30~35헤알 선이에요. **Circo Voador**는 [공식 일정표](https://www.circovoador.com.br/) 링크로 표를 팔고 매표소는 개문 2시간 전에 열어요.\n\n","type":"text"},{"type":"image","image_index":1},{"text":"215계단 **Escadaria Selarón**([공식 안내](https://visitrio.com.br/lapa-o-coracao-da-vida-noturna-do-rio/))은 밝을 때 들러요. 메트로 1·2·4호선은 월~토 05:00~24:00, 일요일·공휴일 07:00~23:00 운행하고, 환승은 종료 시각까지 환승역 승강장에 있어야 해요. Rio Scenarium이 닫을 무렵엔 메트로가 끊겨 택시·호출 앱 비용이 따로 드는 게 아쉬워요. 밤엔 외진 길을 피하고 귀중품은 두고 나와요. 즐기려면 키오스크에서 해넘이를 보고 라파 공연으로 넘어가요. 피하려면 토요일 자정 넘은 Lavradio는 건너뛰고 평일 첫 공연만 봐요.\n\n해변 키오스크에서 새벽 삼바까지, 리우 밤을 끝까지 달리고 싶을 때 맞아요.\n\n정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Rio+Scenarium+Rua+do+Lavradio+20+Rio+de+Janeiro","kind":"map","label":"Rio Scenarium 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Carioca+da+Gema+Av.+Mem+de+S%C3%A1+79+Rio+de+Janeiro","kind":"map","label":"Carioca da Gema 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Circo+Voador+Rio+de+Janeiro","kind":"map","label":"Circo Voador 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=Escadaria+Selar%C3%B3n+Rio+de+Janeiro","kind":"map","label":"Escadaria Selarón 지도"}]}]'::jsonb WHERE id = 'b6bb0a1d-0481-4a1e-91b2-5d46c8841026'::uuid;

UPDATE public.place_reviews SET content = '
프라하의 밤 에너지는 맥주홀에서 시작해요. 긴 나무 테이블에 모르는 사람과 합석하고, 잔이 비면 다음 잔이 자연스럽게 오는 리듬이라 금·토 저녁이면 홀 전체가 웅성거림으로 꽉 차요. 조용한 한잔보다 사람 소리 속에 섞이는 걸 즐기는 분께 맞는 도시예요.

금·토 밤 8시 이후면 오래된 양조 맥주홀 **U Fleků**([공식 사이트](https://ufleku.cz/)) 같은 인기 홀에 사람이 몰려요. U Fleků 식당은 매일 10:00~23:00 열고 12월 24일은 쉬어요. 예약은 [전화 예약](tel:+420224934019)으로 받아요. 자리가 없으면 한두 블록 밖 동네 펍으로 옮겨 강도를 낮추기 좋아요.

강변 쪽은 날씨에 따라 스위치가 달라져요. 블타바강 둑길의 바와 배를 개조한 바는 따뜻한 저녁에 가장 북적이고, 선선해지는 가을밤에는 한산해질 수 있어요.

주말 밤 구시가지에는 단체 파티 손님도 많아서 소음이 꽤 커지고, 붐비는 곳에서는 소매치기 주의가 필요해요. 조용한 밤을 원하면 구시가지 중심은 피하는 편이 나아요. 아쉬운 점은 인기 홀일수록 관광객 비중이 높아 동네 분위기가 옅어진다는 거예요. 금·토 밤 맥주홀의 소란을 여행의 한 장면으로 넣고 싶다면 추천해요.

정보 확인일 2026-09-29 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
