UPDATE public.place_reviews SET content = '

**니시키 시장**([공식 사이트](https://www.kyoto-nishiki.or.jp/))은 데라마치에서 다카쿠라까지 약 390m 아케이드에 가게가 늘어선 교토의 주방이에요. 시장 전체 통일 영업시간은 없고 가게마다 시간이 다르며, 수요일에 쉬는 곳이 많아요. 산 음식은 그 가게 앞이나 안에서 먹어요.


다시마키는 **미키 케이란**(三木鶏卵, [공식 페이지](https://www.kyoto-nishiki.or.jp/stores/mikikeiran/))이 09:00~17:00 열어요. 교토식 다시마키와 장어·아나고를 넣은 말이 나와요. 생유바·건조유바는 **유바키치**(湯波吉, [공식 페이지](https://www.kyoto-nishiki.or.jp/stores/yubakichi/))가 09:00~18:00 열고, 니시키에서 유바를 만들어 파는 가게예요. 타코야키는 **카리카리 하카세**(カリカリ博士, [공식 페이지](https://www.kyoto-nishiki.or.jp/stores/karikarihakase/))가 10:00~19:00 열고, 점보와 치즈·파를 넣은 스페셜이 나와요.

골목이 좁아 붐비는 편이라 오전 11시 전후가 덜 붐비고, 17:00에 닫는 다시마키부터 들르는 순서가 편해요.

정보 확인일 2026-11-08 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**니시키 시장**([공식 사이트](https://www.kyoto-nishiki.or.jp/))은 데라마치에서 다카쿠라까지 약 390m 아케이드에 가게가 늘어선 교토의 주방이에요. 시장 전체 통일 영업시간은 없고 가게마다 시간이 다르며, 수요일에 쉬는 곳이 많아요. 산 음식은 그 가게 앞이나 안에서 먹어요.\n\n\n다시마키는 **미키 케이란**(三木鶏卵, [공식 페이지](https://www.kyoto-nishiki.or.jp/stores/mikikeiran/))이 09:00~17:00 열어요. 교토식 다시마키와 장어·아나고를 넣은 말이 나와요. 생유바·건조유바는 **유바키치**(湯波吉, [공식 페이지](https://www.kyoto-nishiki.or.jp/stores/yubakichi/))가 09:00~18:00 열고, 니시키에서 유바를 만들어 파는 가게예요. 타코야키는 **카리카리 하카세**(カリカリ博士, [공식 페이지](https://www.kyoto-nishiki.or.jp/stores/karikarihakase/))가 10:00~19:00 열고, 점보와 치즈·파를 넣은 스페셜이 나와요.\n\n골목이 좁아 붐비는 편이라 오전 11시 전후가 덜 붐비고, 17:00에 닫는 다시마키부터 들르는 순서가 편해요.\n\n정보 확인일 2026-11-08 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=%E4%BA%AC%E9%83%BD%E9%8C%A6%E5%B8%82%E5%A0%B4","kind":"map","label":"니시키 시장 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E4%B8%89%E6%9C%A8%E9%B6%8F%E5%8D%B5+%E9%8C%A6%E5%B8%82%E5%A0%B4","kind":"map","label":"미키 케이란 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E6%B9%AF%E6%B3%A2%E5%90%89+%E9%8C%A6%E5%B8%82%E5%A0%B4","kind":"map","label":"유바키치 지도"},{"url":"https://www.google.com/maps/search/?api=1&query=%E3%82%AB%E3%83%AA%E3%82%AB%E3%83%AA%E5%8D%9A%E5%A3%AB+%E9%8C%A6%E5%B8%82%E5%A0%B4","kind":"map","label":"카리카리 하카세 지도"}]}]'::jsonb WHERE id = 'bf044b52-27cb-47bf-a6cd-d26a2596f52f'::uuid;

UPDATE public.place_reviews SET content = '
**완안칸**(Waankarn, [관광청 소개](https://waankarn.com/))은 카오락 중심 끅칵의 남부 태국 요리점이에요. 10:00~22:00에 열고, 따꾸아빠의 역사와 문화에서 착안한 메뉴를 내요. 먼저 고를 접시는 푸켓식 돼지고기 조림 무홍, 그리고 나콘시탐마랏산 포멜로와 푸켓산 파인애플이 들어간 완안칸 샐러드예요.

타이므앙군 람깬의 **끄라창 카오락**(Krachang Khao Lak, [미쉐린 가이드](https://guide.michelin.com/th/en/th-phang-nga-region/th-phang-nga/restaurant/krachang-khao-lak))은 빕구르망에 오른 해산물 식당이에요. 매일 12:00~20:00에 열고, 대부분 살아 있는 해산물을 단품으로 조리해요. 대표 접시로는 멜린조 잎 새우 코코넛 수프와 강황에 재운 자이언트 트레발리 구이가 나오고, 그날의 추천은 스페셜 보드에 적혀 있어요. 예약은 식당에 직접 [전화 예약](tel:+66956560862)으로 해요.

**방니앙 시장**(Bang Niang Market, [공식 누리집](https://bangniangmarket.com/))은 방니앙 한가운데서 월·수·목·토 14:00~22:00에 서요. 상인 300곳이 넘고, 길거리 음식 구역에는 꼬치·스프링롤·해산물이, 농산물 구역에는 태국 과일과 채소가 놓여요. 운영 측은 이른 저녁을 가장 활기찬 때로 꼽아요.

장이 서는 저녁에는 해 질 무렵 방니앙에서 꼬치로 시작하고, 화·금·일 저녁은 22:00까지 여는 완안칸으로 옮기면 돼요. 끄라창은 20:00에 닫으니 해산물은 점심이나 이른 저녁에 넣어요.

정보 확인일 2026-11-11 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

