UPDATE public.place_reviews SET content = '

바르셀로나에 하루를 맡긴다면 람블라스 대신 그라시아 동네 안쪽의 **리베르타트 시장**(Mercat de la Llibertat, [공식 사이트](https://www.mercatllibertat.cat/))을 하루의 축으로 삼아 보세요. 주소는 Plaça de la Llibertat, 27이에요. 1888년에 문을 연 건물을 리모델링한 시립 시장이고, 채소·과일, 생선·해산물, 정육, 빵과 농민 직판 가판까지 장보기 품목이 고루 들어 있어요.

시장 평상 시간표는 월~금 08:00~20:30이라, 장보는 시간을 일정에 맞춰 자유롭게 고를 수 있어요. 아침에 장을 보고 오후엔 동네 골목을 걷거나, 반대로 낮을 다른 일정에 쓰고 저녁 무렵 장을 봐도 돼요. 토요일은 15:00에 장을 마치니 장보기는 오전으로 잡고, 오후는 조리 가능한 숙소에서 장 본 것으로 한 끼를 차리는 일정으로 이어 가요.

시장 시간표를 축으로 동네의 하루를 짜고 싶을 때 추천해요.

정보 확인일 2026-11-08 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

