', content_blocks = '[{"text":"바르셀로나에 하루를 맡긴다면 람블라스 대신 그라시아 동네 안쪽의 **리베르타트 시장**(Mercat de la Llibertat, [공식 사이트](https://www.mercatllibertat.cat/))을 하루의 축으로 삼아 보세요. 주소는 Plaça de la Llibertat, 27이에요. 1888년에 문을 연 건물을 리모델링한 시립 시장이고, 채소·과일, 생선·해산물, 정육, 빵과 농민 직판 가판까지 장보기 품목이 고루 들어 있어요.\n\n시장 평상 시간표는 월~금 08:00~20:30이라, 장보는 시간을 일정에 맞춰 자유롭게 고를 수 있어요. 아침에 장을 보고 오후엔 동네 골목을 걷거나, 반대로 낮을 다른 일정에 쓰고 저녁 무렵 장을 봐도 돼요. 토요일은 15:00에 장을 마치니 장보기는 오전으로 잡고, 오후는 조리 가능한 숙소에서 장 본 것으로 한 끼를 차리는 일정으로 이어 가요.\n\n시장 시간표를 축으로 동네의 하루를 짜고 싶을 때 추천해요.\n\n정보 확인일 2026-11-08 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Mercat+de+la+Llibertat+Pla%C3%A7a+de+la+Llibertat+27+08012+Barcelona","kind":"map","label":"리베르타트 시장 지도"}]}]'::jsonb WHERE id = 'c0367f6b-57fc-4353-a1b5-7d177aaf1848'::uuid;

UPDATE public.place_reviews SET content = '
11월에 아이와 갯벌에 직접 들어가도 될지 걱정이라면, 이 시기엔 갯벌 안이 아니라 **람사르고창갯벌센터**([공식 사이트](https://www.gochang.go.kr/tidalflat/index.gochang))를 거점으로 잡으면 풀려요. 하전 갯벌 체험은 11월부터 3월까지 쉬어요.

센터는 09:00~18:00 열고 매주 월요일은 쉬어요. 주차할 수 있어서 차에서 내리면 바로 실내예요. 1층 전시실에서 고창 갯벌과 갯벌 생물을 먼저 보고, 4층 전망대에서 펼쳐진 갯벌을 위에서 내려다보면 갯벌에 내려가지 않아도 반나절이 채워져요. 바닷바람이 찬 날에도 실내라 아이 걸음에 맞춰 끊어 가기 좋아요.

밖에서 갯벌 가까이 가고 싶다면 물때가 기준이에요. 물이 가장 많이 빠지는 간조 2시간 전부터 2시간 후까지만 머물고, 들물이 시작되기 전에 넉넉히 나와요. 갯골은 밀물 때 물이 먼저 차니 건너지 않고, 안개가 끼면 바로 나와요. 아이는 늘 어른 곁에 두고, 물때표는 [국립해양조사원](https://www.khoa.go.kr/)에서 봐요.

전시·전망·쉼을 건물 하나에서 끝내는 일정이라, 갯벌을 처음 보는 어린아이와 짧게 다녀오려는 가족에게 맞아요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
