UPDATE public.place_reviews SET content = '
테마파크에서 수유·기저귀 갈 곳과 쉬는 자리가 흩어질까, 하루가 너무 길까 걱정이라면, **씨월드**([공식 사이트](https://seaworld.com.au/park-info)) 한 곳에 머물며 부모의 방을 기준으로 짜면 풀려요.

2026년 11월 중순 평일은 10:30~16:00, 주말은 10:00~17:00이에요. 만 3세 미만은 무료이고, 만 3~13세는 어린이 요금이에요. 만 14세 미만은 어른과 함께 다녀요.

부모의 방은 Top Terrace의 Exit Shop 왼쪽, 그리고 Shark Bay와 Penguin Point 사이에 있어요. 수유 공간과 기저귀 교환이 나뉘어 있어요. 유모차는 6개월~3세, 15kg·키 100cm 미만까지 빌릴 수 있고 신분증이 필요해요. 휠체어는 신분증을 맡기고 무료로 빌릴 수 있으나 수량이 적어요. 구급실은 Top Terrace 근처예요.

평일 폐장이 16:00로 짧은 날이 많아, 놀이기구를 많이 돌기보다 수조·동물 전시와 부모의 방에서 끊어 가는 반나절이 좋아요. 차는 현장 주차장에 세우거나, 서퍼스 파라다이스·브로드비치에서 705번 버스를 타면 돼요.

어린아이와 짧게 한 곳만 쓸 가족에게 맞아요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"테마파크에서 수유·기저귀 갈 곳과 쉬는 자리가 흩어질까, 하루가 너무 길까 걱정이라면, **씨월드**([공식 사이트](https://seaworld.com.au/park-info)) 한 곳에 머물며 부모의 방을 기준으로 짜면 풀려요.\n\n2026년 11월 중순 평일은 10:30~16:00, 주말은 10:00~17:00이에요. 만 3세 미만은 무료이고, 만 3~13세는 어린이 요금이에요. 만 14세 미만은 어른과 함께 다녀요.\n\n부모의 방은 Top Terrace의 Exit Shop 왼쪽, 그리고 Shark Bay와 Penguin Point 사이에 있어요. 수유 공간과 기저귀 교환이 나뉘어 있어요. 유모차는 6개월~3세, 15kg·키 100cm 미만까지 빌릴 수 있고 신분증이 필요해요. 휠체어는 신분증을 맡기고 무료로 빌릴 수 있으나 수량이 적어요. 구급실은 Top Terrace 근처예요.\n\n평일 폐장이 16:00로 짧은 날이 많아, 놀이기구를 많이 돌기보다 수조·동물 전시와 부모의 방에서 끊어 가는 반나절이 좋아요. 차는 현장 주차장에 세우거나, 서퍼스 파라다이스·브로드비치에서 705번 버스를 타면 돼요.\n\n어린아이와 짧게 한 곳만 쓸 가족에게 맞아요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Sea+World+Gold+Coast","kind":"map","label":"씨월드 지도"}]}]'::jsonb WHERE id = 'd4c0b844-c24d-4a82-8312-e9db0c2ce561'::uuid;

UPDATE public.place_reviews SET content = '
**토르베할레르네**(Torvehallerne, [공식 누리집](https://torvehallernekbh.dk/op-set/opening-hours/))는 프레데릭스보르가데 21번에 두 채의 홀로 서 있어요. 공식 시간은 월~금 10:00~19:00, 토·일 10:00~18:00이고, 아침 커피와 빵은 7시부터 나와요. 시 관광 안내 [비시트코펜하겐](https://www.visitcopenhagen.com/copenhagen/planning/torvehallerne-gdk545401)은 이 장을 뇌레포트 역 옆으로 적어요.

홀 안의 **할레르네스 스뫼레브뢰**(Hallernes Smørrebrød, [가판 안내](https://torvehallernekbh.dk/stade/hallernes-smorrebrod/))는 시장의 생선·고기·채소를 올려 두툼한 스뫼레브뢰를 만들어요. 감자, 갓 구운 프리카델레, 갓 훈제한 연어가 기본 토핑으로 나와요. 가판 시간도 월~금 10:00~19:00, 토·일 10:00~18:00이고, 바 좌석 16개와 바깥 공용 자리가 있어요.

같은 장의 **하브**(Hav, [생선 가판](https://torvehallernekbh.dk/stade/hav/))는 생선 가게와 오픈 키친을 함께 둬요. 피시 타파스, 갓 삶은 조개·갑각류, 식초에 재운 갓 구운 청어, 피시 프리카델레가 나와요.

7시에 빵을 먼저 사고, 홀이 열리는 10시 이후 스뫼레브뢰로 이어가는 순서가 맞아요.

