UPDATE public.place_reviews SET content = '
**알라메다 공원(Parque da Alameda)**은 구시가 서쪽을 끼고 펼쳐진 약 8만 5천㎡ 공원이에요. 알라메다 산책로, 산타 수사나 참나무 숲, 페라두라 산책길로 나뉘고, 하루 24시간 열려 있어요. 공원 한 바퀴는 보통 30분쯤 걸려요. 완만한 오르막에 그늘과 벤치가 이어져요([공원 안내](https://www.santiagoturismo.com/parques-e-xardins/parque-da-alameda)).

동쪽 비탈의 파세오 다 페라두라(Paseo da Ferradura)에서는 대성당의 서쪽 정면이 구시가 지붕 너머로 보여요. 가장 기념비적인 정면을 정면에서 바라보는 자리예요.

대성당 안으로 들어가지 않아도, 공원 벤치에서 탑이 빛에 잠길 때까지 머물러 보세요.

정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**알라메다 공원(Parque da Alameda)**은 구시가 서쪽을 끼고 펼쳐진 약 8만 5천㎡ 공원이에요. 알라메다 산책로, 산타 수사나 참나무 숲, 페라두라 산책길로 나뉘고, 하루 24시간 열려 있어요. 공원 한 바퀴는 보통 30분쯤 걸려요. 완만한 오르막에 그늘과 벤치가 이어져요([공원 안내](https://www.santiagoturismo.com/parques-e-xardins/parque-da-alameda)).\n\n동쪽 비탈의 파세오 다 페라두라(Paseo da Ferradura)에서는 대성당의 서쪽 정면이 구시가 지붕 너머로 보여요. 가장 기념비적인 정면을 정면에서 바라보는 자리예요.\n\n대성당 안으로 들어가지 않아도, 공원 벤치에서 탑이 빛에 잠길 때까지 머물러 보세요.\n\n정보 확인일 2026-11-10 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Parque+da+Alameda+Santiago+de+Compostela","kind":"map","label":"알라메다 공원 지도"}]}]'::jsonb WHERE id = 'e17ff4b9-be5e-4bd0-a19b-2fa02b52ea7f'::uuid;

UPDATE public.place_reviews SET content = '
루브르 근처에서 아이가 뛰어놀 곳이 필요하다면, 이 고민은 **튀일리리 정원**([공식 사이트](https://www.louvre.fr/decouvrir/les-jardins))에서 풀려요. 입장은 1년 내내 무료이고, 놀이 시설은 대부분 리볼리 거리 쪽 북쪽에 모여 있어요.

북쪽 카스티글리오네 입구 근처엔 미끄럼틀·그네·회전놀이기구와 나무 사이 밧줄 다리가 있는 무료 놀이터가 있어요. 같은 자리 나무 그늘 아래 회전목마는 3유로예요. 푀양 테라스와 큰 팔각 연못 사이엔 2세부터 타는 트램펄린이 있고, 역시 3유로예요.

중앙 산책로의 큰 팔각 연못에선 작은 돛단배를 빌려 막대를 들고 띄워요. 30분에 6유로이고, 방학이 아닐 땐 수·금·토·일요일과 공휴일, 방학엔 매일 11:00~18:00 운영해요.

화장실은 콩코르드 광장 쪽 입구와 리볼리 거리 입구(Rue du 29 Juillet 맞은편) 두 곳으로, 무료이고 정원이 열려 있는 동안 써요. 여름엔 화장실 4곳이 더 설치되고, 모든 화장실에 거동이 불편한 사람을 위한 칸이 있어요. 놀이터로 가기 전 리볼리 쪽에서 한 번 들러 가면 좋아요.

정원은 4·5·9·10월엔 07:00~21:00, 6~8월엔 07:00~23:00, 11~3월엔 07:30~19:30 열고, 닫기 30분 전부터 내보내요.

놀이터·회전목마·트램펄린·돛단배를 반나절에 묶고 싶은 아이 동반 가족에게 추천해요.

정보 확인일 2026-10-22 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요
', content_blocks = '[{"text":"루브르 근처에서 아이가 뛰어놀 곳이 필요하다면, 이 고민은 **튀일리리 정원**([공식 사이트](https://www.louvre.fr/decouvrir/les-jardins))에서 풀려요. 입장은 1년 내내 무료이고, 놀이 시설은 대부분 리볼리 거리 쪽 북쪽에 모여 있어요.\n\n북쪽 카스티글리오네 입구 근처엔 미끄럼틀·그네·회전놀이기구와 나무 사이 밧줄 다리가 있는 무료 놀이터가 있어요. 같은 자리 나무 그늘 아래 회전목마는 3유로예요. 푀양 테라스와 큰 팔각 연못 사이엔 2세부터 타는 트램펄린이 있고, 역시 3유로예요.\n\n중앙 산책로의 큰 팔각 연못에선 작은 돛단배를 빌려 막대를 들고 띄워요. 30분에 6유로이고, 방학이 아닐 땐 수·금·토·일요일과 공휴일, 방학엔 매일 11:00~18:00 운영해요.\n\n화장실은 콩코르드 광장 쪽 입구와 리볼리 거리 입구(Rue du 29 Juillet 맞은편) 두 곳으로, 무료이고 정원이 열려 있는 동안 써요. 여름엔 화장실 4곳이 더 설치되고, 모든 화장실에 거동이 불편한 사람을 위한 칸이 있어요. 놀이터로 가기 전 리볼리 쪽에서 한 번 들러 가면 좋아요.\n\n정원은 4·5·9·10월엔 07:00~21:00, 6~8월엔 07:00~23:00, 11~3월엔 07:30~19:30 열고, 닫기 30분 전부터 내보내요.\n\n놀이터·회전목마·트램펄린·돛단배를 반나절에 묶고 싶은 아이 동반 가족에게 추천해요.\n\n정보 확인일 2026-10-22 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Jardin+des+Tuileries+Paris","kind":"map","label":"튀일리리 정원 지도"}]}]'::jsonb WHERE id = 'e93cafdf-d704-48df-8aba-bca6d86d0c29'::uuid;

UPDATE public.place_reviews SET content = '
**터페 문**에서 **왓 프라싱**까지, 시청이 일요일마다 도로 일부를 막아요. 그 자리에 좌판과 먹거리·거리 공연이 들어서는 **선데이 워킹 스트리트**예요. 대략 17:00부터 22:00까지, 거리는 약 1.5km예요([시청 안내](https://www.cmcity.go.th/list/page/496/%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B8%A7%E0%B8%B1%E0%B8%95%E0%B8%B4%E0%B8%84%E0%B8%A7%E0%B8%B2%E0%B8%A1%E0%B9%80%E0%B8%9B%E0%B9%87%E0%B8%99%E0%B8%A1%E0%B8%B2/)).

출발은 터페 문 쪽이에요. 라차담넌 길을 따라 왓 프라싱 방향으로 한 줄로 걸어요. 중간에 프라폭끌라오 길과 십자로 만나요. 즐기려면 저녁 일찍 시작해 끝까지 천천히 걷고, 피하려면 터페 문 근처에서 짧게 보고 돌아와요. 일요일만 열려서 평일 밤 일정과 이어 잡기는 어려워요.

마무리는 **Grab**이에요. 치앙마이에서는 GrabCar와 JustGrab을 쓸 수 있고, 요금은 출발 전에 앱에 먼저 보여요([교통 안내](https://www.grab.com/th/en/transport/)). 터페 문 밖이나 거리 끝에서 불러 숙소로 바로 가요.

정보 확인일 2026-11-09 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요

이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.
', content_blocks = '[{"text":"**터페 문**에서 **왓 프라싱**까지, 시청이 일요일마다 도로 일부를 막아요. 그 자리에 좌판과 먹거리·거리 공연이 들어서는 **선데이 워킹 스트리트**예요. 대략 17:00부터 22:00까지, 거리는 약 1.5km예요([시청 안내](https://www.cmcity.go.th/list/page/496/%E0%B8%9B%E0%B8%A3%E0%B8%B0%E0%B8%A7%E0%B8%B1%E0%B8%95%E0%B8%B4%E0%B8%84%E0%B8%A7%E0%B8%B2%E0%B8%A1%E0%B9%80%E0%B8%9B%E0%B9%87%E0%B8%99%E0%B8%A1%E0%B8%B2/)).\n\n출발은 터페 문 쪽이에요. 라차담넌 길을 따라 왓 프라싱 방향으로 한 줄로 걸어요. 중간에 프라폭끌라오 길과 십자로 만나요. 즐기려면 저녁 일찍 시작해 끝까지 천천히 걷고, 피하려면 터페 문 근처에서 짧게 보고 돌아와요. 일요일만 열려서 평일 밤 일정과 이어 잡기는 어려워요.\n\n마무리는 **Grab**이에요. 치앙마이에서는 GrabCar와 JustGrab을 쓸 수 있고, 요금은 출발 전에 앱에 먼저 보여요([교통 안내](https://www.grab.com/th/en/transport/)). 터페 문 밖이나 거리 끝에서 불러 숙소로 바로 가요.\n\n정보 확인일 2026-11-09 · 운영시간·메뉴는 현지 사정에 따라 바뀔 수 있어요\n\n이 리뷰는 공개된 정보(공식 안내·여행 자료)를 바탕으로 GATEO 리뷰어가 정리했어요.","type":"text"},{"type":"links","items":[{"url":"https://www.google.com/maps/search/?api=1&query=Ratchadamnoen+Road+Tha+Phae+Gate+Chiang+Mai","kind":"map","label":"선데이 워킹 스트리트 지도"}]}]'::jsonb WHERE id = 'ff09c541-dd74-4638-b6f8-ed5b796885a9'::uuid;

UPDATE public.reports SET content = '## 1. 여행지 선정 이유

오래 마음에 두었던 도시로 첫 유럽 여행을 열고 싶었다. 그래서 목적지는 파리로 정했다.

운영에서 뽑은 인기 스냅샷(2026-09-19)을 보니 파리가 맨 앞에 있었다. 사이트에 실시간으로 돌아가는 순위판을 본 게 아니라, 그날 기록해 둔 인기 목록을 참고한 정도다. 방콕·바르셀로나·제주도 후보에 있었지만, 첫 글은 마음이 먼저 간 도시에서 시작하기로 했다. 자세한 안내는 [GATEO 파리](https://www.gateo.kr/place/paris)에서 보면 된다.

![에펠탑 실루엣](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_w72yrpjrk.jpg)

에펠탑 실루엣, 세느의 빛, 박물관 앞 줄, 골목 빵집 냄새. 이런 장면만 떠올려도 설렌다. 막상 떠나기 전에는 시기며 입국 절차, 공항에서 시내로 가는 길, 첫날 동선이 한꺼번에 걱정된다. 그래서 GATEO의 AI 도슨트 **MOONi**에게 먼저 말을 걸어 보기로 했다. 혼자 메모를 쌓기보다, 옆에 앉은 안내자와 길을 그려 보는 느낌으로.

---

## 2. 여행 준비

### 시기와 계절감

봄·초여름은 강변 산책과 테라스가 잘 어울린다. 가을에는 박물관과 골목이 편하고, 한여름은 낮이 길어 활기차다. 겨울은 조명과 실내 전시가 따뜻하다. 정답을 찾기보다, 내가 견딜 만한 날씨와 붐빔의 균형을 고르면 된다. 출발 전에 파리 페이지를 열어 두고, MOONi에게 며칠 묵을지·무엇을 보고 싶은지 말해 두면 일정 초안을 잡기 쉽다.

### 비자·입국 관련 (한국 여권 기준, 확인 필수)

한국 여권으로 프랑스·솅겐 지역을 관광 목적으로 짧게 머물 때는, 보통 비자 없이 입국하는 제도가 적용된다. 흔한 기준은 솅겐에서 최근 180일 중 최대 90일이다. 여권 유효기간, 귀국(또는 다음 목적지) 항공권, 숙소·경비 증빙도 챙긴다.

- **EES:** 비EU 여행자는 생체정보 등록 대상이 될 수 있다. 입국 대기에 여유를 둔다. 공항과 시점에 따라 달라질 수 있다.
- **ETIAS:** 이 글을 쓰는 시점(2026-09)에는 아직 신청을 받지 않는다. 시행 시기와 필요 여부를 단정하지 말고, 출발 직전 공식 ETIAS 안내와 주한 프랑스대사관 등 공식 채널을 다시 본다.
- 장기·다국가 일정이나 특수한 체류 규정은 대사관·공식 안내를 우선한다. 이 글은 법률 자문이 아니다.

짧게 말해, 단기 관광은 비자 면제가 일반적이지만 여권·체류일수·EES·(향후) ETIAS는 출발 직전에 공식으로 확인하는 편이 안전하다.

### 항공·환전·짐

도착이 샤를 드골(CDG)인지 오를리(ORY)인지에 따라 시내 가는 길이 달라진다. 항공권을 정한 뒤 공항 이름을 MOONi에게 알려 두면, 첫날 동선을 맞춰 주기 쉽다. 통화는 유로(EUR)다. 카드와 소액 현금·비상 카드를 나누어 두면 마음이 놓인다. 수수료와 환율은 시점마다 달라서, 여기서는 숫자를 적지 않는다.

파리에서는 걷는 시간이 많다. 편한 신발, 계절에 맞는 겉옷, 접이식 우산, 보조배터리, 여행자보험 증빙, 여권 사본을 챙긴다. 박물관·성당의 복장과 가방 규정은 방문 전 공식 안내에서 확인한다.

![파리 카페 거리](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_gt26b85mb.jpg)

### GATEO / MOONi에서 미리 볼 것 · 제휴 안내

1. [파리 장소 페이지](https://www.gateo.kr/place/paris)에서 도시 소개·관심 테마·CTA를 훑어 본다.
2. MOONi에게 체류 일수, 동행, 관심사, 도착 공항을 말하고 일정 초안·루트 초안을 받는다.
3. 비자·이동·치안은 [파리 여행 플래너](https://www.gateo.kr/place/paris/planner)에서 출발 전 체크리스트로 다시 본다.

GATEO는 여행을 탐색·계획·기록하도록 돕는 서비스다. **여행사가 아니며, 결제를 대행하지 않는다.** 숙박·액티비티·교통·eSIM은 필요할 때 제휴 파트너 안내 링크를 통해, 각 서비스 조건으로 진행한다. 최종 약관·가격·환불은 해당 파트너와 이용자 사이의 문제다.

---

## 3. 이동

### 공항에서 시내로

도착하면 짐을 끌기 전에 시내 진입 수단을 고른다. CDG는 비교적 멀고, ORY는 상대적으로 가깝다는 정도만 기억해도 충분하다. RER·공항 연계 철도, 버스·셔틀, 택시·차량 호출 중 짐과 시간대에 맞춰 고른다. 요금·배차·운행 시간은 시즌·공사·파업에 따라 바뀐다. 출발 당일에는 공식 교통 앱·공항 안내를 우선하고, 필요하면 MOONi에게도 다시 물어본다. EES 대기까지 넣어 시내 도착 시각은 넉넉히 잡자.

### 메트로·RER 감각과 첫날

파리에서는 메트로·RER·버스·트램이 기본이다. 숙소, 자주 갈 곳, 환승 허브 서너 곳만 먼저 익히면 노선도가 덜 복잡해 보인다. 패스 종류와 요금은 현지 공식 안내 기준으로 확인한다. 큰 캐리어로 러시아워를 피하는 편이 편하다. 소지품은 앞쪽 가방, 지퍼 잠금처럼 기본만 지켜도 도움이 된다.

첫날은 많이 보는 날보다, 몸을 도시 리듬에 맞추는 날이다.

1. 공항 → 숙소 체크인(또는 짐 보관)
2. 가까운 골목에서 가벼운 식사·커피
3. 세느 강변이나 숙소 인근을 1~2시간 걷기
4. 시차와 걸음 수를 생각해 일찍 쉬기

![파리 스카이라인](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_4beg6wogw.jpg)

에펠탑 야경이나 루브르를 첫날에 몰아넣기보다, MOONi에게 「첫날은 가볍게」라고 말해 두면 그날 일정이 한결 여유 있어진다.

---

## 4. 현지에서

실제 방문 여부와 순서는 체류 일수·예약·컨디션에 따라 바꾼다. 영업시간·입장료·휴관일은 공식 사이트 확인이 필수다. 아래에는 특정 금액을 넣지 않았다.

### 세느를 축으로 한 하루

시테 섬 근처에서 강과 다리의 리듬을 느낀다. 좌안과 우안을 오가며 카페·서점·광장을 끼워 넣는다. 유람선은 선택이다. 강변 산책로와 다리 위에서도 파리의 공기가 온다. 해 질 녘에는 붐비는 스폿보다 한 블록 옆 각도를 찾아 천천히 걷는다.

![세느 강과 다리 황혼](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530301_kz74yhbox.jpg)

### 박물관과 동네

루브르·오르세·오랑주리·퐁피두는 이름만으로도 하루가 사라진다. **하루 한 곳, 또는 반나절 한 곳을 깊게** 보는 편이 낫다. 예약제·입장 시간·가방 규정은 전날 공식 안내와 MOONi에게 확인한다. 티켓 가격은 여기서 단정하지 않는다.

![루브르 피라미드](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_82yzpvw80.jpg)

- **마레·레알:** 골목과 작은 숍, 광장에 앉는 시간이 곧 일정이 된다.
- **생제르맹·라탱:** 서점·카페·학생가의 오후 산책.
- **몽마르트:** 언덕과 전망의 양면이 있어, 이른 아침이나 해 질 녘이 편하다.
- **벨빌·바스티유:** 명소보다 일상적인 파리의 결을 느끼고 싶을 때.
- **개선문·샹젤리제:** 상징성은 크지만 사람이 많다. 측도로 빠질 여유를 둔다.

![몽마르트 사크레쾨르](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_dhpqvppdg.jpg)

지도상 거리보다, 숙소에서 왕복하는 피로를 먼저 계산한다. 오전 한 권역·오후 한 권역처럼 나누고, 비가 오면 실내 비중을 늘린다.

### 음식과 3~4일 예시

아침은 빵과 커피, 점심은 카페식 한 접시, 저녁은 예약한 비스트로. 이런 리듬이면 여행이 안정된다. 줄을 설 한 곳과 백업 한 곳을 짝지어 둔다. 시장에서 과일·치즈를 사 강변에서 먹는 점심도 남겨 두자. 식이 제한이나 알레르기가 있으면 번역 문장을 준비한다. 가격은 메뉴와 시즌에 따라 달라서 단정하지 않는다.

- **Day 1:** 도착·숙소·강변 짧은 산책·이른 휴식
- **Day 2:** 박물관 하나와 인근 동네 카페
- **Day 3:** 시테·강변 다리, 원하면 유람 또는 야경
- **Day 4:** 몽마르트 또는 마레 하나와 여유 쇼핑

![루브르 외관](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_cxw7rtp9u.jpg)

이 순서는 정답이 아니다. 과밀을 막는 안전장치에 가깝다. 다리가 아프면 벤치에 앉는 시간을 일정에 넣고, MOONi에게 그날 컨디션을 말해 일정을 다시 짜 달라고 하면 된다.

---

## 5. TIP / 마무리

### 짧게 챙기는 실전 메모

- 공식·최신 정보는 대사관·France.fr·EU ETIAS 안내·공항·교통 공사를 우선하고, 블로그·후기는 참고만 한다.
- 가격·패스·개장 시간은 대략만 기억하고 당일 확인한다.
- 첫날은 욕심을 줄인다. 파리는 남은 날에도 그 자리에 있다.
- 사진보다 걸음과 앉는 시간을 일정에 넣는다.
- GATEO는 탐색·계획·기록 도구이고, 예약·결제는 제휴 파트너의 영역이다.

### CTA

파리 여행을 구체화할 준비가 되었다면, 먼저 도시 페이지를 열어 두자.

![에펠탑과 파리 전경](https://phdjnbfitvmrguqzverm.supabase.co/storage/v1/object/public/images/1790252530302_pau5cr7sz.jpg)

- 파리 장소: [https://www.gateo.kr/place/paris](https://www.gateo.kr/place/paris)
- GATEO 홈: [https://www.gateo.kr/](https://www.gateo.kr/)

3D 지구본이나 탐색에서 파리를 고른 뒤, 이어서 MOONi에게 체류 일수와 취향을 말해 보면 된다. 화면이 알아서 이어지지는 않으니, 내가 파리를 고르고 대화를 이어 가면 된다. 이 글의 흐름을 참고해 각자의 일정으로 다시 짜 볼 수 있다.

### 다음 목적지 힌트

이번 글은 **2026-09-19 운영 인기 스냅샷에서 맨 앞에 있던 파리**로 시리즈를 열었다. 다음 목적지는 같은 스냅샷의 후보(방콕·바르셀로나·제주 등)와 시즌·검색 의도를 함께 보고, **검수·추천 확정 후**에 이어 쓸 예정이다. 실시간 순위나 다음 도시를 미리 단정하지 않는다.

