## 강으로 들어가기 전에

### 전자관광비자(e-Tourist Visa)

한국 여권으로 관광차 인도에 들어가려면 전자관광비자(e-Tourist Visa)를 받는다. 신청은 인도 정부 공식 전자비자 사이트에서만 한다. 대한민국(Republic Of Korea) 기준 요금은 30일권 10~25미국달러(4~6월 10, 7~3월 25), 1년권 40미국달러, 5년권 200미국달러이고, 여기에 은행 수수료 3%가 붙는다. [GATEO 타지마할 페이지](https://www.gateo.kr/place/taj-mahal)에서 MOONi에게 도착일과 금요일 휴관을 알리고, 일출 입장과 석양 전망을 어느 날에 둘지 이틀의 순서를 함께 정해 두자.

**여행 팁 · 전자관광비자(e-Tourist Visa)**
- 대상: 한국 여권 · 관광
- 종류: 30일 · 1년 · 5년(복수 입국) · 1년·5년권은 한 해 체류 합산 최대 180일
- 요금: 30일 10~25미국달러 · 1년 40미국달러 · 5년 200미국달러 · 은행 수수료 3% 추가
- 신청: 인도 정부 공식 전자비자 사이트에서만
- 링크: [전자비자 신청하기](https://indianvisaonline.gov.in/evisa/) · [요금표(PDF)](https://indianvisaonline.gov.in/evisa/images/Etourist_fee_final.pdf)

## 첫째 날, 흰 돔과 요새

### 해 뜨기 전의 매표소

**타지마할(Taj Mahal)**은 야무나강 남쪽에 선 흰색 대리석 묘다. 일반 관람은 해 뜨기 30분 전부터 해 지기 30분 전까지이고, 매주 금요일은 닫는다. 매표소는 해 뜨기 1시간 전부터 해 지기 45분 전까지 동문·서문에서 표를 팔며, 지금은 남문으로 들어갈 수 없고 나가기만 한다. 본묘(main mausoleum) 안까지 들어가려면 입장권에 더해 200루피짜리 추가 표가 필요하다.

[사진 2]

**여행 팁 · 타지마할(Taj Mahal)**
- 위치: Tajganj, Agra, Uttar Pradesh · 동문·서문 입장 · 남문은 퇴장만
- 시간: 해 뜨기 30분 전~해 지기 30분 전 · 매주 금요일 휴관 · 매표소는 해 뜨기 1시간 전~해 지기 45분 전
- 요금(외국인, ASI·ADA 포함): 1,100루피 · 온라인 예매 시 50루피 할인 · 본묘 추가 200루피(선택) · 15세 미만 무료
- 예약: 온라인 예매 가능 · 외국인 입장권에 신발 커버·생수·아그라 관광 지도·배터리 버스·골프 카트가 포함된다
- 하이라이트: 정원 축선의 흰 돔 · 본묘(추가 표)
- 붐빔 피하기: 온라인으로 미리 사 두면 현장 줄을 건너뛸 수 있다(ASI 예매 안내)
- 링크: [예매하기](https://asi.paygov.org.in/asi-webapp/#/ticketbooking) · [운영시간·요금](https://tajmahal.gov.in/visiting-hours.aspx) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Taj%20Mahal%20Agra)

[사진 3]

[사진 4]

### 붉은 요새의 오후

타지마할에서 약 2.5km 떨어진 **아그라 요새(Agra Fort)**로 옮긴다. 악바르가 붉은 사암으로 다시 쌓고 샤 자한이 흰 대리석으로 꾸민 무굴 황제의 성채다. 자한기르 마할, 카스 마할, 디완이암, 무사만 부르즈, 모티 마스지드가 2.5km 성벽 안에 이어지고, 방문객 입구는 아마르 싱 게이트(Amar Singh Gate)다. 타지마할이 쉬는 금요일에도 문을 연다.

[사진 5]

**여행 팁 · 아그라 요새(Agra Fort)**
- 위치: Rakabganj, Agra · 타지마할에서 약 2.5km · 아그라 칸트 역에서 약 3km · 입장 Amar Singh Gate
- 시간: 일출~일몰(대략 06:00~18:00) · 매일
- 요금: 외국인 600~650루피(평일 650 · 금요일·타지 당일 방문 후 600) · 15세 미만 무료
- 예약: 온라인 예매 가능 · 매표소에서 UPI·카드 가능 · 공인 가이드·오디오 가이드 이용 가능
- 하이라이트: 무사만 부르즈에서 바라보는 야무나 쪽 타지마할 · 자한기르 마할·카스 마할
- 링크: [예매하기](https://asi.paygov.org.in/asi-webapp/#/ticketbooking) · [공식 안내](https://agra.nic.in/tourist-place/agra-fort/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Agra%20Fort)

[사진 6]

### 강 건너의 석양

해 질 무렵에는 야무나 북쪽 **메흐타브 바그(Mehtab Bagh)**로 건너간다. 타지마할과 강을 마주 보도록 맞춰 둔 무굴 정원으로, 석양 때 맞은편 흰 돔을 바라보는 자리다. 아그라 요새에서 암베드카르(야무나) 다리를 넘어 약 8km다.

[사진 7]

**여행 팁 · 메흐타브 바그(Mehtab Bagh)**
- 위치: 야무나 좌안 · 타지마할 맞은편 · 아그라 요새에서 약 8km(Ambedkar/Yamuna Bridge)
- 시간: 일출~일몰 · 매일
- 요금: 외국인 300루피 · 15세 미만 무료
- 예약: 온라인 예매 가능
- 하이라이트: 석양 무렵 타지마할 정면 전망 · 차르바그 정원
- 붐빔 피하기: 사진 찍기 좋은 빛은 16:30~18:00(아그라 지구 공식 안내)
- 링크: [예매하기](https://asi.paygov.org.in/asi-webapp/#/ticketbooking) · [공식 안내](https://agra.nic.in/tourist-place/mehtab-bagh/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Mehtab%20Bagh%20Agra)

## 둘째 날, 붉은 사암 도시

### 파테푸르 시크리

둘째 날 아침에는 아그라 서쪽으로 36~40km 떨어진 **파테푸르 시크리(Fatehpur Sikri)**로 나간다. 1571년 악바르가 세운 옛 수도로, 54m 높이의 불란드 다르와자, 자마 마스지드, 셰이크 살림 치슈티의 흰 대리석 묘, 판치 마할, 디완이카스가 붉은 사암 도시 안에 이어진다. 시내 ISBT·이드가에서 UPSRTC 버스와 택시가 연결되고, 주차장에서 공인 배터리 버스로 유적 입구까지 간다.

[사진 8]

**여행 팁 · 파테푸르 시크리(Fatehpur Sikri)**
- 위치: 아그라 서쪽 36~40km · NH-21(Fatehpur Sikri Road) · 입장 Diwan-i-Aam 쪽 매표소
- 시간: 일출~일몰(대략 06:00~18:00) · 매일 · 자마 마스지드 안 다르가는 더 늦게까지 연다
- 요금: 외국인 610루피 · 15세 미만 무료
- 예약: 온라인 예매 가능 · 공인 가이드만 이용
- 하이라이트: 불란드 다르와자 · 살림 치슈티 묘 · 판치 마할
- 링크: [예매하기](https://asi.paygov.org.in/asi-webapp/#/ticketbooking) · [공식 안내](https://agra.nic.in/tourist-place/fatehpur-sikri/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Fatehpur%20Sikri)

### 이틀의 순서

- **첫째 날 새벽:** 타지마할 동·서 매표소(해 뜨기 1시간 전 개표) · 금요일 제외
- **첫째 날 오후:** 아그라 요새 Amar Singh Gate(일출~일몰)
- **첫째 날 석양:** 메흐타브 바그(16:30~18:00 빛이 좋다)
- **둘째 날:** 파테푸르 시크리(아그라에서 36~40km · 일출~일몰)

파테푸르 시크리의 붉은 성문이 뒤로 멀어지면, 이틀의 아그라는 흰 돔과 붉은 사암으로 남는다.

