## 바다에 닿기 전에

### 푸켓 공항에서 북쪽으로

카오락은 팡아주의 안다만 해안에 있고, 푸켓 국제공항(HKT)에서 북쪽으로 약 78km 떨어져 있어요. 차로 약 1시간 10분~1시간 20분(태국관광청 자료별 차이)이 걸려요. 공항 교통 안내에 나오는 버스는 푸켓타운행 공항버스 8411번(08:00~21:00)과 빠통·까론·까따 등 푸켓 섬 해변을 도는 스마트버스뿐이라, 카오락까지는 차량 이동을 기준으로 잡아요. 국제선 도착층 1층 2번 출입구에는 관광객 지원센터(TAC)가 24시간 열려 있어요. [GATEO 카오락 페이지](https://www.gateo.kr/place/khao-lak)에서 해변과 시장, 시미란 일정까지 사흘 순서를 잡아 보세요.

**여행 팁 · 푸켓 국제공항(HKT) → 카오락**
- 거리·시간: 약 78km · 차로 약 1시간 10분~1시간 20분
- 공항버스: 8411번은 푸켓타운행(08:00~21:00) · 스마트버스는 푸켓 섬 서쪽 해변행 · 공항 교통 안내에 카오락행 노선 없음
- 도움: 관광객 지원센터(TAC) 국제선 도착층 1층 2번 출입구 · 24시간 · +66 76 327 100 · 관광경찰 1155
- 링크: [공항 교통 안내](https://phuket.airportthai.co.th/service/transportation) · [관광객 지원센터](https://phuket.airportthai.co.th/service/transportation/detail/1177)

### 입국 카드

태국에 들어가는 외국인은 디지털 입국 카드(TDAC)를 입국일을 포함해 3일 안에 공식 사이트에서 제출해요. 공식 사이트에서는 수수료가 없고, 한국어 안내가 있어요. 제출하면 오는 확인 메일을 입국심사 때 여권과 함께 보여 주면 돼요.

**여행 팁 · 태국 디지털 입국 카드(TDAC)**
- 시기: 입국일 포함 3일 이내 제출 · 입국할 때마다 새로 제출
- 요금: 공식 사이트 무료
- 준비: 여권 정보 · 항공편 번호와 도착일 · 태국 내 숙소 주소 · 이메일
- 링크: [공식 페이지](https://tdac.immigration.go.th/) · [한국어 안내](https://tdac.immigration.go.th/manual/kr/faq.html)

## 첫째 날, 해변의 결

### 낭통에서 방삭까지

카오락의 해변은 성격이 갈려요. **낭통 해변(Nang Thong Beach)**은 쇼핑·식당·나이트라이프가 몰린 중심가에 있어 걸어서 다니기 편해요. **방삭 해변(Bang Sak Beach)**과 **팍윕 해변(Pak Weep Beach)**은 북적임에서 비켜 앉아 책을 읽거나 수영하고, 해변을 걷다 해 지는 바다를 보기 좋은 곳이에요.

[사진 2]

**여행 팁 · 카오락 해변 고르기**
- 낭통 해변: 중심가 · 쇼핑·식당·나이트라이프가 가까움
- 방삭·팍윕 해변: 한적한 쪽 · 독서·수영·해변 산책·일몰
- 링크: [낭통 해변 지도](https://www.google.com/maps/search/?api=1&query=Nang%20Thong%20Beach%2C%20Khao%20Lak%2C%20Phang%20Nga) · [방삭 해변 지도](https://www.google.com/maps/search/?api=1&query=Bang%20Sak%20Beach%2C%20Takua%20Pa%2C%20Phang%20Nga)

### 장이 서는 요일

저녁에는 카오락 한가운데 방니앙의 **방니앙 시장(Bang Niang Market)**으로 가요. 월·수·목·토요일 14:00~22:00에 열리고, 상인이 300곳이 넘어요. 길거리 음식 구역에는 꼬치와 스프링롤, 해산물이, 농산물 구역에는 태국 과일과 채소가 놓여요. 시장 운영 측은 이른 저녁이 가장 활기찬 시간이라고 해요.

[사진 3]

**여행 팁 · 방니앙 시장(Bang Niang Market)**
- 위치: 방니앙 중심 · 카오락 지역 한가운데
- 시간: 월·수·목·토 14:00~22:00 · 화·금·일은 열리지 않음
- 하이라이트: 꼬치·스프링롤·해산물 길거리 음식 · 태국 과일·채소 · 수공예 기념품
- 붐빔: 이른 저녁에 가장 활기참(시장 운영 측 안내)
- 링크: [공식 페이지](https://bangniangmarket.com/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Bang%20Niang%20Market%2C%20Khao%20Lak%2C%20Phang%20Nga)

시장이 서지 않는 날 저녁은 카오락 중심 끅칵의 **완안칸(Waankarn)**도 있어요. 따꾸아빠의 역사와 문화에서 메뉴를 빌려 온 현대식 남부 태국 요리점이고, 푸켓식 돼지고기 조림 무홍을 대표 메뉴로 내요.

**여행 팁 · 완안칸(Waankarn)**
- 위치: 5, 58 7, Tambon Khuekkhak, Takua Pa District, Phang Nga 82190
- 시간: 10:00~22:00
- 대표 메뉴: 푸켓식 무홍 · 완안칸 샐러드(포멜로·파인애플)
- 링크: [태국관광청 소개](https://waankarn.com/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Waankarn%2C%20Khuekkhak%2C%20Takua%20Pa%20District%2C%20Phang%20Nga%2082190)

### 숲 쪽으로 한 걸음

해변에서 등을 돌리면 카오락-람루 국립공원이 있어요. 카오락에서 약 9km 떨어진 **똔총파 폭포(Ton Chong Fa Waterfall)**는 다섯 단으로 바위를 타고 내려와 큰 웅덩이에 고여요. 입구에서 폭포까지는 비교적 쉬운 길이고, 폭포 오른쪽으로 윗단에 오르는 길은 좁고 가파르며 미끄러워요.

[사진 4]

**여행 팁 · 똔총파 폭포(Ton Chong Fa Waterfall)**
- 위치: 카오락-람루 국립공원 · 카오락에서 약 9km
- 하이라이트: 다섯 단 폭포와 아래 웅덩이
- 길: 입구~폭포는 비교적 쉬움 · 오른쪽 윗단 길은 가파르고 미끄러움
- 링크: [태국관광청 안내](https://news.cision.com/tourism-authority-of-thailand/r/7-best-things-to-do-in-khao-lak,c3416503) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Ton%20Chong%20Fa%20Waterfall%2C%20Khao%20Lak-Lam%20Ru%20National%20Park%2C%20Phang%20Nga)

## 둘째 날, 시미란으로 가는 배

### 당일치기 섬

**시미란 국립공원(Mu Ko Similan National Park)**의 2026–27 시즌은 2026년 10월 15일부터 2027년 5월 15일까지예요. 섬에서는 묵을 수 없고, 아침에 나가 저녁에 돌아오는 당일 일정만 돼요. 배는 대부분 타이므앙군의 **탑라무 선착장(Thap Lamu Pier)**과 그 근처에서 떠나는 스피드보트나 카타마란이고, 약 1시간 30분이 걸려요. 태국 정부홍보국은 당일 투어 상품을 이용하라고 권해요.

[사진 5]

외국인 입장료는 성인 500바트, 어린이 250바트예요. 식당과 매점, 화장실은 4번 섬과 8번 섬에만 있어요. 섬에는 ATM이 없고 전화 신호가 끊길 때가 있어 현금을 챙겨 가요. 산호에 해로운 성분이 없는 선크림을 쓰고 일회용 플라스틱은 줄여요. 따차이섬은 2016년부터 상륙이 막혀 있어요. [GATEO 시미란 제도 페이지](https://www.gateo.kr/place/similan-islands)에서 MOONi에게 여행 날짜를 알려 주고, 시미란 배를 사흘 가운데 어느 날에 넣을지 골라 보세요.

[사진 6]

**여행 팁 · 시미란 국립공원(Mu Ko Similan National Park)**
- 시즌: 2026-10-15~2027-05-15 · 당일 일정만 · 모든 섬 숙박 금지
- 배: 대부분 탑라무 선착장(타이므앙군)과 근처에서 출발 · 스피드보트·카타마란 약 1시간 30분 · 당일 투어 상품 권장
- 입장료: 외국인 성인 500바트 · 어린이 250바트
- 섬 시설: 식당·매점·화장실은 4번·8번 섬 · ATM 없음 · 전화 신호 끊김 있음
- 지킬 것: 산호에 안전한 선크림 · 일회용 플라스틱 줄이기 · 따차이섬 상륙 금지
- 문의: 공원 076-453-272
- 링크: [정부홍보국 시즌 안내](https://prd.go.th/main/article/0000a994-18ba-4c93-ba0f-eff02dc7ab47) · [국립공원청 소식](http://news.dnp.go.th/news/50049) · [탑라무 선착장 지도](https://www.google.com/maps/search/?api=1&query=Thap%20Lamu%20Pier%2C%20Thai%20Mueang%2C%20Phang%20Nga)

[사진 7]

### 선착장 쪽의 해산물

탑라무 선착장과 같은 타이므앙군의 람깬에는 미쉐린 가이드 빕구르망의 **끄라창 카오락(Krachang Khao Lak)**이 있어요. 대부분 살아 있는 해산물을 단품으로 조리하고, 그날의 추천은 스페셜 보드에 적어요. 멜린조 잎을 넣은 새우 코코넛 수프와 강황에 재운 자이언트 트레발리 구이가 대표 접시예요.

**여행 팁 · 끄라창 카오락(Krachang Khao Lak)**
- 위치: 78/155 Moo 5, Lam Kaen, Thai Mueang, Phang Nga 82210
- 시간: 매일 12:00~20:00
- 대표 메뉴: 멜린조 잎 새우 코코넛 수프 · 강황 자이언트 트레발리 구이 · 스페셜 보드
- 예약: 식당에 직접 문의
- 링크: [미쉐린 가이드](https://guide.michelin.com/th/en/th-phang-nga-region/th-phang-nga/restaurant/krachang-khao-lak) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Krachang%20Khao%20Lak%2C%2078%2F155%20Moo%205%2C%20Lam%20Kaen%2C%20Thai%20Mueang%2C%20Phang%20Nga%2082210)

## 셋째 날, 북쪽 해안의 기억

### 이름이 새겨진 길

카오락에서 차로 약 40분, 반남켐 해안 가까이에 **반남켐 쓰나미 추모공원(Ban Nam Khem Tsunami Memorial Park)**이 있어요. 파도를 본뜬 굽은 콘크리트 벽이 쓰나미에 부서진 옛 어선과 마주 서 있고, 공원 다른 쪽 흙벽을 따라 이곳에서 희생된 1,400명이 넘는 이름이 새겨진 길이 이어져요. 공원 주변에는 해산물 식당과 관광안내소, 주민들이 만든 기념품 가게가 있고, 해변을 따라 어촌 마을까지 걸을 수 있어요.

**여행 팁 · 반남켐 쓰나미 추모공원(Ban Nam Khem Tsunami Memorial Park)**
- 위치: Bang Muang, Takua Pa, Phang Nga · 카오락에서 차로 약 40분
- 시간: 추모공원·해변 08:00~20:00 · 박물관 수~일 08:30~16:30
- 하이라이트: 파도 모양의 벽과 옛 어선 · 희생자 이름이 새겨진 길 · 해변의 어촌 마을
- 링크: [태국관광청 안내](https://thailand.prd.go.th/en/content/category/detail/id/52/iid/351342) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Ban%20Nam%20Khem%20Tsunami%20Memorial%20Park%2C%20Bang%20Muang%2C%20Takua%20Pa%2C%20Phang%20Nga)

### 주석의 옛 도시

추모공원에서 약 7km 떨어진 따꾸아빠에는 **따꾸아빠 올드타운(Takua Pa Old Town)**이 있어요. 주석과 광물의 채굴·무역으로 외국 상인이 모이던 도시라 시노-포르투갈풍 건물이 늘어서 있고, 지금은 그 건물들이 카페와 잡화점으로 쓰여요. 벽에는 거리 그림이 많아 사진을 남기는 자리가 돼요.

**여행 팁 · 따꾸아빠 올드타운(Takua Pa Old Town)**
- 위치: Takua Pa, Phang Nga · 반남켐 추모공원에서 약 7km
- 하이라이트: 시노-포르투갈풍 건물을 고친 카페·잡화점 · 거리 벽화
- 링크: [태국관광청 안내](https://www.thailandgoodtravel.info/?locale=en) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Takua%20Pa%20Old%20Town%2C%20Takua%20Pa%2C%20Phang%20Nga)

### 사흘의 순서

- **첫째 날:** 낭통 또는 방삭·팍윕 해변 → 저녁 방니앙 시장(월·수·목·토 14:00~22:00). 장이 없는 날은 완안칸(10:00~22:00) · 낮에 똔총파 폭포
- **둘째 날:** 탑라무 선착장 → 시미란 당일 배(약 1시간 30분) → 끄라창 카오락(12:00~20:00)
- **셋째 날:** 반남켐 쓰나미 추모공원(08:00~20:00, 박물관 수~일 08:30~16:30) → 따꾸아빠 올드타운

[사진 8]

섬에서 돌아온 저녁과 이름이 새겨진 벽 사이에서, 카오락의 사흘은 바다의 두 얼굴로 남아요.

