[사진 1]

자카르타 주정부는 지난 9월 9일 문화재 보존 전문가들과 함께 탑 몸체와 독립의 방, 디오라마 전시실을 집중 청소하기 시작했다고 알렸어요. 그래서 이 글은 탑 안이 아니라 광장에서 바라보는 모습만 담아요. 탑을 눈에 담았다면 반나절은 북쪽의 옛 도심 코타 투아(Kota Tua)로 옮겨 가 보세요.

## 파타힐라 광장의 옛 시청

코타 투아의 중심 파타힐라 광장에는 1710년 바타비아 시청(Stadhuis)으로 완공된 건물이 남아 있어요. 1974년부터는 자카르타 역사박물관(Museum Sejarah Jakarta)으로 쓰이고, 흔히 파타힐라 박물관이라고도 불러요. 선사 시대부터 바타비아 시절, 독립까지 이어지는 도시의 이야기를 약 2만 3,500점의 소장품으로 보여 주고, 앞마당에는 시 자구르 대포(Meriam Si Jagur)가 놓여 있어요.

[사진 2]

박물관은 월요일에 쉬고, 화요일부터 일요일까지 오전 9시에 문을 열어요. 닫는 시각은 자카르타 관광청과 인도네시아 문화부 안내가 서로 달라서 오전에 먼저 들르는 편이 안전해요. 일정을 짤 때는 [GATEO 자카르타 페이지](https://www.gateo.kr/place/jakarta)를 함께 열어 두세요.

**여행 팁 · 자카르타 역사박물관(파타힐라 박물관)**
- 주소: Jl. Taman Fatahillah No.1, Pinangsia, Taman Sari, 자카르타 서부
- 운영: 화~일 09:00 개관 · 월요일 휴관 · 닫는 시각은 공식 안내마다 13:00~20:00로 달라요
- 가는 길: KRL 자카르타 코타(Jakarta Kota)역에서 약 230m(도보 약 3분) · 트랜스자카르타 코타(Kota) 정류장(1번 블록M 노선) · MRT는 분다란 HI역에서 트랜스자카르타 1번(블록M–코타 투아)으로 환승
- 링크: [자카르타 관광청 박물관 안내](https://enjoy.jakarta.go.id/article/museum-sejarah-jakarta) · [인도네시아 문화부 박물관 정보](https://museum.kemenbud.go.id/museum/profile/museum+sejarah+jakarta) · [모나스 청소 소식(자카르타 주정부)](https://www.beritajakarta.id/potret-jakarta/album/19996/pemprov-dki-kembali-lakukan-perawatan-tugu-monas) · [지도에서 보기 · 박물관](https://www.google.com/maps/search/?api=1&query=Museum%20Sejarah%20Jakarta) · [지도에서 보기 · 모나스](https://www.google.com/maps/search/?api=1&query=Monumen%20Nasional%20Jakarta)

현지 정보 확인일: 2026-11-18 · 운영시간·일정은 현지 사정에 따라 바뀔 수 있어요

