[사진 1]

Photo by [Juliana Barquero](https://unsplash.com/@juliebaa?utm_source=gateo&utm_medium=referral) on [Unsplash](https://unsplash.com/photos/boat-on-river-between-high-rise-buildings-during-nighttime-WaHPhFveWLk?utm_source=gateo&utm_medium=referral)

## 난바에 닿기 전에

### 공항에서 난바까지

간사이공항역(Kansai-Airport)에서 난카이 난바역(Namba)까지는 난카이 전철의 공항 특급 라피트(Rapi:t)가 가장 빠르다. 최단 34분이 걸리고, 승차권과 특급권을 묶은 디지털 티켓은 레귤러 시트 1,410엔, 슈퍼 시트 1,590엔이다. 특급권을 차 안에서 사면 300엔이 더 붙는다. 특급권 없이 타는 공항 급행은 약 45분이 걸린다.

**여행 팁 · 난카이 라피트(Rapi:t)**
- 구간: 간사이공항역–난카이 난바역 · 최단 34분 · 공항 급행은 약 45분
- 요금: 디지털 티켓(승차권+특급권) 레귤러 1,410엔 · 슈퍼 시트 1,590엔(성인) · 특급권만 레귤러 700엔 · 차내 구매 시 300엔 추가
- 구매: 디지털 티켓은 구매 뒤 스마트폰에서 열차·좌석 지정, QR로 지정 개찰구 통과
- 링크: [운행 안내](https://www.nankai.co.jp/en_railway/traffic/express/rapit.html) · [승차권](https://www.nankai.co.jp/en_railway/ticket/rapit) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Nankai%20Namba%20Station)

### 단기 체류

일반 여권을 가진 한국인은 관광 같은 단기 체재(90일 이내)라면 비자 없이 일본에 들어갈 수 있다. [GATEO 오사카 페이지](https://www.gateo.kr/place/osaka)에서 MOONi에게 여행 날짜를 알려 주고, 천수각과 공중정원의 마지막 입장 시각을 이틀 순서에 맞춰 잡아 보자.

**여행 팁 · 단기 체재(주부산일본국총영사관)**
- 대상: 대한민국 일반 여권 · 관광·친지 방문 등 단기 체재(보수를 받는 활동 제외)
- 체재: 90일 이내 · 사증 면제(2005년 3월부터)
- 링크: [사증 안내](https://www.busan.kr.emb-japan.go.jp/itpr_ko/nsm_021.html)

## 첫째 날, 운하의 네온

### 도톤보리의 저녁

라피트에서 내리면 **도톤보리(道頓堀)**까지는 걸어서 닿는다. 운하를 따라 늘어선 간판이 해가 지면서 하나씩 켜지고, 다리 위에서는 물에 비친 불빛과 지나가는 배가 한 화면에 들어온다. 거리와 다리는 표 없이 걷는 공공 공간이다.

[사진 2]

Photo by [Agathe](https://unsplash.com/@agathe_26?utm_source=gateo&utm_medium=referral) on [Unsplash](https://unsplash.com/photos/people-standing-between-buildings-at-night-SMwAfgzj-VU?utm_source=gateo&utm_medium=referral)

## 둘째 날, 시장에서 성으로, 그리고 하늘로

### 아침의 구로몬 시장

둘째 날 아침은 **구로몬 시장(黒門市場)**에서 연다. 약 580미터 아케이드 아래 150곳 남짓한 가게가 늘어서 있고, 여름에는 갯장어(하모), 겨울에는 복어가 이 시장의 명물이다. 생선 가게의 해산물 꼬치구이, 과일 가게의 생과일주스, 찻집의 말차 소프트처럼 걸으며 먹는 메뉴가 많다. 가게마다 영업시간이 다르다.

[사진 3]

Photo by [Cody Chan](https://unsplash.com/@cceee?utm_source=gateo&utm_medium=referral) on [Unsplash](https://unsplash.com/photos/people-inside-building-OFxnqWpADN4?utm_source=gateo&utm_medium=referral)

**여행 팁 · 구로몬 시장(黒門市場)**
- 위치: 大阪市中央区日本橋2丁目4番1号(오사카시 주오구 닛폰바시 2-4-1) · 미나미
- 시간: 가게마다 다름 · 구로몬 인포메이션 센터 09:00~18:00 연중무휴(환전기·화장실)
- 대표 먹거리: 여름 갯장어 · 겨울 복어 · 해산물 꼬치구이 · 생과일주스 · 말차 소프트
- 링크: [공식 페이지](https://kuromon.com/jp/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Kuromon%20Ichiba%20Market%20Osaka)

### 천수각의 오후

오후에는 **오사카성 천수각(大阪城天守閣)**으로 옮긴다. 1931년 시민 기부금으로 다시 세운 세 번째 천수각이고, 안은 도요토미 히데요시와 오사카성 역사를 다루는 박물관이다. 3·4층 전시는 두 달마다 바뀐다. 09:00부터 18:00까지 열고 입장은 17:30까지인데, 붐비는 날에는 17:30 전에 매표 줄을 막기도 한다. 입장 예약은 받지 않으니 매표소로 바로 간다.

[사진 4]

Photo by [Stefan K](https://unsplash.com/@stefankst?utm_source=gateo&utm_medium=referral) on [Unsplash](https://unsplash.com/photos/white-and-green-temple-under-blue-sky-during-daytime-h29Uu7BYF44?utm_source=gateo&utm_medium=referral)

**여행 팁 · 오사카성 천수각(大阪城天守閣)**
- 위치: 大阪市中央区大阪城1-1 · JR 오사카조코엔역·모리노미야역, 오사카 메트로 다니마치욘초메역
- 시간: 09:00~18:00(입장 17:30까지) · 12월 28일~1월 1일 휴관 · 전시 교체·시설 점검으로 쉬는 날이 있음
- 요금: 성인 1,200엔 · 대학생·고등학생 600엔(학생증) · 중학생 이하 무료(나이 확인)
- 예약·결제: 입장 예약 없음 · 현금·신용카드·교통계 IC카드·QR 결제
- 짐: 코인로커 없음 · 매표소에서 1개 100엔에 보관(09:00~17:30 접수)
- 링크: [공식 이용 안내](https://www.osakacastle.net/guide/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Osaka%20Castle%20Main%20Tower)

### 공중정원의 밤

해가 지면 **우메다 스카이빌딩 공중정원 전망대(空中庭園展望台)**로 오른다. 두 동을 39·40층과 옥상에서 잇는 전망대이고, 옥상은 360도로 트여 있다. 09:30부터 22:30까지 열고 마지막 입장은 22:00이다. 타워 이스트·웨스트의 엘리베이터로는 들어갈 수 없고, 3층 전용 입구로 올라 39층 매표소에서 입장 절차를 밟는다. 비바람이 거센 날에는 옥상이 닫힐 수 있다.

[사진 5]

Photo by [Dmitry Romanoff](https://unsplash.com/@dm8ryphotos?utm_source=gateo&utm_medium=referral) on [Unsplash](https://unsplash.com/photos/a-tall-clock-tower-towering-over-a-city-w_YJh3JNcaw?utm_source=gateo&utm_medium=referral)

**여행 팁 · 우메다 스카이빌딩 공중정원 전망대(Kuchu Teien Observatory)**
- 위치: 大阪市北区大淀中1-1-88 우메다 스카이빌딩 · JR 오사카역에서 걸어서 약 7분
- 시간: 09:30~22:30(마지막 입장 22:00) · 특별 영업일·단축 영업일 있음
- 요금: 성인 2,000엔 · 4세~초등학생 500엔 · 4세 미만 무료
- 예약: 사전 웹 티켓 또는 39층 당일권 · 입장은 3층 전용 입구
- 링크: [공식 이용 안내](https://www.skybldg.co.jp/observatory/information/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Umeda%20Sky%20Building%20Kuchu%20Teien%20Observatory)

### 이틀의 순서

- **첫째 날:** 간사이공항역 → 라피트(최단 34분) → 난바 · 저녁 도톤보리
- **둘째 날 아침:** 구로몬 시장(가게마다 시간 다름)
- **둘째 날 오후:** 오사카성 천수각(입장 17:30까지)
- **둘째 날 밤:** 공중정원 전망대(마지막 입장 22:00)

옥상 둘레를 한 바퀴 돌고 나면, 오사카의 이틀은 운하의 네온과 성의 돌담, 39층 위의 바람으로 남는다.

## Editor’s Note

오사카의 이틀을 펼쳐 볼 때는 [GATEO 오사카 페이지](https://www.gateo.kr/place/osaka)를 함께 열어 두자.

GATEO는 여행사가 아니며, 교통·입장권을 포함한 예약·결제는 각 서비스에서 이뤄진다.

