UPDATE public.reports SET content = '밀라노 대성당(Duomo di Milano)은 안에서 올려다보는 곳이기도 하지만, 지붕 위로 올라가 걸어 볼 수 있는 성당이기도 해요. 대성당 공식 매표 안내에 따르면 테라스는 지상 약 50m 높이에 있고, 계단으로 오르면 251개를 밟아 닿아요.

[사진 1]

테라스에 서면 칸돌리아(Candoglia) 대리석으로 깎은 첨탑과 조각상, 플라잉 버트레스가 손 닿을 듯 가까이 모여 있어요. 첨탑 사이로는 두오모 광장과 도시의 지붕들이 펼쳐지고요. 아래에서는 한 덩어리로 보이던 성당이, 위에서는 조각 하나하나의 얼굴로 다가오는 셈이에요.

## 계단으로 갈까, 엘리베이터로 갈까

오르는 방법은 두 가지예요. 계단권은 16유로(할인 8유로), 엘리베이터권은 18유로(할인 9유로)예요. 엘리베이터는 테라스 첫 층까지만 올라가고, 위층으로 가거나 내려올 때는 계단만 써요. 그래서 엘리베이터권을 골라도 어느 정도는 걷게 돼요. 줄을 덜 서고 엘리베이터로 오르는 패스트트랙권(28유로, 할인 14유로)도 있어요.

[사진 2]

테라스는 매일 09:00~19:00에 열고, 표 판매는 17:50, 마지막 입장은 18:00에 끝나요. 관람은 60분 이상 잡아 두면 좋아요. 오후 늦게 오를 생각이라면 마지막 입장 시각부터 거꾸로 일정을 맞춰 보세요. 밀라노 하루 일정은 [GATEO 밀라노 페이지](https://www.gateo.kr/place/milan)에서 함께 짜 볼 수 있어요.

**여행 팁 · 밀라노 대성당 테라스**
- 위치: 두오모 광장(P.za del Duomo, 20122 Milano)
- 운영: 매일 09:00~19:00 · 표 판매 마감 17:50 · 마지막 입장 18:00
- 요금: 계단 16유로(할인 8유로) · 엘리베이터 18유로(할인 9유로) · 패스트트랙(엘리베이터) 28유로(할인 14유로)
- 엘리베이터: 첫 층까지만 운행 · 위층과 내려오는 길은 계단
- 들고 갈 수 없는 것: 큰 짐·삼각대·음식과 음료·유모차 · 반려동물은 안내견만
- 겨울: 11월 19일 공식 공지에 추위로 얼음 위험이 있어 테라스 동선이 바뀌거나 제한될 수 있다고 나와 있어요
- 표: 대성당 공식 매표 사이트는 공식 채널이 아닌 판매처의 표 유효성을 보장할 수 없다고 안내해요
- 링크: [테라스 계단권 예매하기](https://ticket.duomomilano.it/en/eventi/terrazze-salita-a-piedi/) · [테라스 엘리베이터권 예매하기](https://ticket.duomomilano.it/en/eventi/english-terrazze-salita-in-ascensore/) · [테라스 표 한눈에 보기](https://ticket.duomomilano.it/en/categoria/terrazze/) · [오늘의 공식 공지](https://www.duomomilano.it/en/calendario/?filterCal=avvisi) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Duomo%20di%20Milano)

