[사진 1]

## 호수에 닿기 전에

### 공항에서 시내까지

노이바이 국제공항(Noi Bai)에서 시내로는 86번 공항버스가 하노이역(Ga Hà Nội)까지 이어 줘요. 편도 5만 동이고, 공항에서 06:40부터 22:15까지 30분 간격으로 출발해요. 공항 택시도 터미널의 지정 승차장에서 탈 수 있어요.

**여행 팁 · 86번 공항버스(Noi Bai–Ha Noi Railway Station)**
- 구간: 노이바이 공항–하노이역
- 요금: 편도 5만 동
- 시간: 06:40~22:15 출발 · 30분 간격
- 링크: [공항 교통 안내](https://noibaiairport.vn/en/transportation) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Ga%20H%C3%A0%20N%E1%BB%99i%20Hanoi%20Railway%20Station)

### 단기 체류

대한민국 국민은 여권 종류와 관계없이 베트남 입국일부터 최대 45일까지 비자 없이 머물 수 있어요. 이 조치는 2028년 3월 14일까지 이어지고, 여권은 남은 유효기간이 6개월 이상이어야 해요. [GATEO 하노이 페이지](https://www.gateo.kr/place/hanoi)에서 MOONi에게 여행 날짜를 알려 주고, 문묘의 밤 개방 요일에 맞춰 이틀 순서를 잡아 보세요.

**여행 팁 · 단기 체류(주베트남 대한민국 대사관)**
- 대상: 대한민국 국민 · 여권 종류 무관
- 체류: 입국일부터 최대 45일 · 무비자(2028-03-14까지)
- 여권: 남은 유효기간 6개월 이상
- 링크: [대사관 공지](https://vn.mofa.go.kr/vn-ko/brd/m_2203/view.do?page=1&seq=1345931)

## 첫째 날, 감옥 담장에서 호수까지

### 호아로의 오후

첫 오후는 **호아로 수용소 유적(Di tích Nhà tù Hỏa Lò)**에서 보내요. 매일 08:00부터 17:00까지, 설과 공휴일에도 문을 열어요. 입장료는 1인 5만 동이에요.

**여행 팁 · 호아로 수용소 유적(Di tích Nhà tù Hỏa Lò)**
- 위치: Số 1 phố Hỏa Lò, phường Cửa Nam, Hà Nội
- 시간: 매일 08:00~17:00(설·공휴일 포함)
- 요금: 1인 5만 동
- 링크: [공식 입장 안내](https://hoalo.vn/Home/Ve) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Hoa%20Lo%20Prison%20Relic%20Hanoi)

### 호수의 저녁

해가 기울면 **호안끼엠 호수(Hồ Hoàn Kiếm)**로 걸어요. 붉은 다리가 호수 위에 걸려 있고, 호수 둘레는 표 없이 걷는 공공 공간이에요.

[사진 2]

### 물 위의 인형극

저녁은 호수 맞은편 **탕롱 수상인형극장(Nhà hát Múa rối Thăng Long)**에서 마무리해요. 300석 극장에서 50분 동안 용춤, 물소와 피리 소년, 모내기, 레로이 왕의 검 전설 같은 장면이 물 위에서 이어져요. 진행은 영어이고, 7개 언어 오디오 가이드는 요금이 따로 있어요.

**여행 팁 · 탕롱 수상인형극장(Nhà hát Múa rối Thăng Long)**
- 위치: 57B Đinh Tiên Hoàng, Hoàn Kiếm, Hà Nội · 호안끼엠 호수 맞은편
- 공연: 약 50분 · 300석 · 영어 · 7개 언어 오디오 가이드(별도 요금)
- 예약: 공식 예매 페이지 또는 전화 024 3824 9494
- 링크: [예매하기](https://nhahatmuaroithanglong.vn/en/ticket-book/) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Thang%20Long%20Water%20Puppet%20Theatre%2057B%20Dinh%20Tien%20Hoang)

## 둘째 날, 비석의 뜰과 붉은 철교

### 문묘의 아침

둘째 날은 **문묘·국자감(Văn Miếu – Quốc Tử Giám)**으로 가요. 매일 08:00~17:00에 열고, 수·토·일에는 18:00~22:00에 밤 개방이 한 번 더 있어요. 문을 지나면 규문각(Khuê Văn Các), 진사 비석을 모신 비석의 뜰, 대성전, 옛 국자감 건물이 차례로 이어져요. 일반 입장권은 7만 동이고, 안내 데스크와 오디오 가이드가 있어요.

[사진 3]

[사진 4]

**여행 팁 · 문묘·국자감(Văn Miếu – Quốc Tử Giám)**
- 위치: 58 Quốc Tử Giám, Hà Nội(정문) · 버스 38번 58 Quốc Tử Giám 정류장, 02·41·E08·E09번 40 Tôn Đức Thắng 맞은편 정류장
- 시간: 매일 08:00~17:00 · 밤 개방 수·토·일 18:00~22:00
- 요금: 일반 7만 동
- 하이라이트: 규문각 · 진사 비석의 뜰 · 대성전 · 국자감
- 링크: [공식 방문 안내](https://www.vanmieu.gov.vn/en/introduction/visitor-information) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Temple%20of%20Literature%2058%20Quoc%20Tu%20Giam%20Hanoi)

### 철교 위의 해 질 녘

오후에는 올드쿼터 골목을 지나 홍강 쪽 **롱비엔 다리(Cầu Long Biên)**까지 걸어요. 강 위로 길게 뻗은 철교를 바라보며 이틀째 해를 보내요.

[사진 5]

[사진 6]

### 이틀의 순서

- **첫째 날:** 노이바이 공항 → 86번 버스(06:40~22:15) → 하노이역 · 오후 호아로(08:00~17:00) · 저녁 호안끼엠 호수 · 탕롱 수상인형극장
- **둘째 날 오전:** 문묘·국자감(08:00~17:00 · 수·토·일은 밤 개방 18:00~22:00)
- **둘째 날 해 질 녘:** 올드쿼터 → 롱비엔 다리

강 위로 해가 지면, 하노이의 이틀은 호수의 붉은 다리와 비석의 뜰, 물 위의 인형으로 남아요.

