## 밤 기차로 오르는 길

### 하노이역에서 라오까이역까지

베트남 철도는 2026년 10월부터 하노이–라오까이 구간에 매일 밤 세 편을 띄운다. SP15가 21:45, SP3가 22:00, SP7이 22:40에 하노이역(Ga Hà Nội)을 떠나 이튿날 05:20, 05:50, 06:27에 라오까이역(Ga Lào Cai)에 닿는다. 돌아오는 밤 기차는 SP16(21:25)과 SP4(21:50)이고, SP8은 12:05에 라오까이를 떠나 19:30에 하노이에 들어오는 낮 기차다. 중간에 서는 역은 자럼·옌비엔·푹옌·옌바이·바오하·포루 여섯 곳으로 줄었다.

**여행 팁 · 하노이–라오까이 열차(SP15·SP3·SP7 / SP16·SP4·SP8)**
- 하노이 출발(매일): SP15 21:45 · SP3 22:00 · SP7 22:40
- 라오까이 도착: 05:20 · 05:50 · 06:27(이튿날)
- 돌아오는 열차: SP16 21:25 · SP4 21:50(밤) · SP8 12:05 출발, 하노이 19:30 도착(낮)
- 링크: [예매하기](https://dsvn.vn/) · [운행 공지](https://vr.com.vn/tin-tuc/tuyen-duong-sat-ha-noi-lao-cai-tang-len-3-doi-tau-khach-moi-ngay) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Ga%20L%C3%A0o%20Cai%20Lao%20Cai%20Railway%20Station)

[GATEO 사파 페이지](https://www.gateo.kr/place/sapa)에서 MOONi에게 하노이를 떠나는 날짜를 알려 주고, 판시판 케이블카의 요일별 운행 시간에 맞춰 밤 기차를 골라 보자.

## 계곡을 건너 정상으로

### 무엉호아 산악열차

판시판으로 가는 길은 선 월드 판시판 레전드(Sun World Fansipan Legend) 단지 안의 무엉호아 산악열차(Muong Hoa Mountain Train)에서 시작한다. 천장까지 유리를 낸 객차가 중앙역에서 케이블카 역 쪽으로 무엉호아 계곡을 가로지르고, 창밖으로 계단식 논과 마을이 이어진다.

[사진 2]

[사진 3]

### 구름 위의 케이블카

케이블카는 9월 28일 정기 점검을 마치고 다시 달린다. 정상으로 오르는 편은 월~목 08:00~14:30, 금 08:00~15:30, 토 07:30~15:30, 일 07:30~14:30에 타고, 마지막 하행은 월~목·일 16:00, 금·토 17:00이다. 날씨에 따라 시간이 조정된다.

[사진 4]

**여행 팁 · 판시판 케이블카(Sun World Fansipan Legend)**
- 위치: Đường Nguyễn Chí Thanh, Sa Pa, Lào Cai
- 상행: 월~목 08:00~14:30 · 금 08:00~15:30 · 토 07:30~15:30 · 일 07:30~14:30
- 마지막 하행: 월~목·일 16:00 · 금·토 17:00
- 문의: 1800 1000 · 0948 30 8888
- 링크: [예매하기](https://booking.sunworld.vn/) · [운행 시간 공지](https://sunworld.vn/en/fansipan/sunworld-news/notice-fansipan-cable-car-officially-resumes-operation-from-september-28-30074) · [지도에서 보기](https://www.google.com/maps/search/?api=1&query=Sun%20World%20Fansipan%20Legend%20Sa%20Pa)

## 다섯 시의 첫 케이블카

### 해돋이 콤보

토·일 새벽에는 «판시판 정상에서 해돋이(Đón bình minh trên đỉnh Fansipan)» 콤보의 첫 케이블카가 05:00에 출발한다. 11월 7일 다시 열린 이 콤보는 2026년 11월 21·22·28·29일 주말 아침으로 끝나고, 아침마다 100명만 받는다. 정상 쪽 산악열차 상행권이 콤보에 들어 있다. 해가 오르면 해발 3,143m 정상에서 국기 게양식이 열리고, 정상의 카페 뒤 솔레유(Cafe Du Soleil)에서 아침을 이어 갈 수 있다.

**여행 팁 · 해돋이 콤보(Đón bình minh trên đỉnh Fansipan)**
- 첫 케이블카: 토·일 05:00
- 2026년 일정: 11월 21·22·28·29일
- 정원: 아침마다 100명
- 포함: 정상 쪽 산악열차 상행권
- 링크: [콤보 안내](https://sunworld.vn/vi/fansipan/tin-tuc-sunworld/dem-nguoc-combo-don-binh-minh-tren-dinh-fansipan-dieu-gi-cho-nguoi-day-som-o-do-cao-3143m-39960) · [예매하기](https://booking.sunworld.vn/)

이 콤보의 올해 운영은 2026년 11월 29일 아침까지다. 내년 일정은 선 월드 판시판 공지에서 확인해 보자.

### 정상의 절과 불상

정상 길을 따라 아미타 대불, 관세음보살상, 낌선바오탕 사원(Kim Sơn Bảo Thắng Tự), 청동 나한상 18기가 늘어선 나한의 길이 차례로 나온다. 11월 말에는 흰 데이지와 수십만 그루 다육 식물 정원이 정상 일대를 채운다.

[사진 5]

### 산 아래 반마이

해가 높이 뜨면 산 아래 반마이(Bản Mây)로 내려온다. 서북부 고산 민족의 집과 직물, 전통 관악기 켄(khèn) 소리가 있고, 베 짜기·향 만들기·대나무 엮기·밀랍 문양 같은 수공예가 이어진다. 공연 «Đỉnh thiêng du ký»와 «Tây Bắc mùa hoa nở»가 하루를 닫는다.

### 사흘의 순서

- **첫날 밤:** 하노이역 SP15 21:45(또는 SP3 22:00 · SP7 22:40)
- **둘째 날:** 라오까이역 05:20~06:27 도착 → 사파 · 무엉호아 산악열차로 계곡 건너기 · 케이블카 상행 마감(월~목 14:30)
- **셋째 날 아침:** 토·일은 05:00 해돋이 케이블카(11/29까지), 평일은 08:00 첫 상행 → 정상의 절과 불상 → 반마이
- **셋째 날 밤:** 라오까이역 SP16 21:25 또는 SP4 21:50 → 하노이 05:15·05:40 도착

구름 아래로 해가 번지고 나면, 사파는 밤 기차의 덜컹거림과 정상의 깃발로 남는다.

