UPDATE public.reports SET content = '대마도(Tsushima)는 일본 땅인데도 한국에서 더 가까운 섬이에요. 일본정부관광국(JNTO) 안내에 따르면 맑은 날 섬의 서쪽 해안에서는 한국의 건물과 산이 보인다고 해요. 바다 너머가 이웃 나라라는 사실이 이 섬을 보는 첫 장면이 돼요.

[사진 1]

나가사키현에서 가장 큰 섬으로 면적은 709제곱킬로미터이고, 산과 숲이 땅의 89%를 덮고 있어요. 그래서 걷고 바라보는 여행에 잘 맞아요. 섬 가운데에 있는 에보시다케(Eboshi-dake, 높이 176m) 정상의 전망대에서는 대마도 해협이 한눈에 들어오고, 아소만(Aso Bay) 일대를 도는 투어도 있어요.

## 섬으로 건너가는 길

나가사키 공항이나 후쿠오카 공항에서 비행기로 약 35분이에요. 배는 후쿠오카 하카타 페리 터미널에서 이즈하라(Izuhara)항으로 가요. 규슈유센 제트포일은 2시간 15분, 규슈유센 페리는 약 4시간 45분이 걸려요.

[사진 2]

대마도 여행을 계획할 때는 [GATEO 대마도 페이지](https://www.gateo.kr/place/tsushima)를 함께 열어 두세요.

**여행 팁 · 대마도(Tsushima)**
- 위치: 일본 나가사키현 쓰시마시
- 가는 길: 항공 약 35분(나가사키·후쿠오카 공항) · 배 하카타 → 이즈하라 제트포일 2시간 15분, 페리 약 4시간 45분
- 전망: 에보시다케 전망대(176m) · 서쪽 해안은 맑은 날 한국이 보인다고 안내돼요
- 링크: [일본정부관광국 쓰시마섬 안내](https://www.japan.travel/ko/spot/731/) · [에보시다케 전망대(디스커버 나가사키)](https://www.discover-nagasaki.com/en/sightseeing/847) · [지도에서 보기 · 에보시다케](https://www.google.com/maps/search/?api=1&query=Eboshidake%20Observatory%20Tsushima) · [지도에서 보기 · 이즈하라항](https://www.google.com/maps/search/?api=1&query=Izuhara%20Port%20Tsushima)

